  ui_story_5028_50280101_X53_dialog_content = "（嗓子都快叫壞了吧，和八十隻烏鴉大合唱一樣！）",
  ui_story_5028_50280101_53_dialog_content = "哎，看看那傢伙又惹什麼麻煩了吧。",
