  ui_story_5028_50280101_55_dialog_content = "囉！囉！",
  ui_story_5028_50280101_56_dialog_content = "好了，別叫了凱羅，我來了。",
  ui_story_5028_50280101_57_dialog_content = "你......你爬到樹上去幹嘛？",
  ui_story_5028_50280101_58_dialog_content = "囉......",
  ui_story_5028_50280101_59_dialog_content = "……",
  ui_story_5028_50280101_60_dialog_content = "不是吧……",
  ui_story_5028_50280101_61_dialog_content = "你那麼大的個子，會被一隻兔子嚇到？",
  ui_story_5028_50280101_62_dialog_content = "囉......",
  ui_story_5028_50280101_63_dialog_content = "什麼嘛，就因為這種事讓我錯過了小鱗甲獸。",
  ui_story_5028_50280101_64_dialog_content = "壞事的傢伙，今天就在樹上掛一天吧！",
  ui_story_5028_50280101_65_dialog_content = "囉......",
  ui_story_5028_50280101_66_dialog_content = "囉，囉。",
  ui_story_5028_50280101_67_dialog_content = "哎呀，我逗你的，用不著叫得這麼可憐吧。",
  ui_story_5028_50280101_68_dialog_content = "兔子先生兔子先生，可以麻煩你換一個地方嗎？",
  ui_story_5028_50280101_69_dialog_content = "你似乎嚇到我的朋友了。",
  ui_story_5028_50280101_70_dialog_content = "？！",
  ui_story_5028_50280101_71_dialog_content = "沒有沒有，不是在說你可怕！",
  ui_story_5028_50280101_72_dialog_content = "<color=#e8d9bb>啪——！</color>",
  ui_story_5028_50280101_73_dialog_content = "喂！人呢！給我出來！",
  ui_story_5028_50280101_74_dialog_content = "看看你做的好事！為什麼非要讓凱羅跟著我啊！",
  ui_story_5028_50280101_75_dialog_content = "牠一點用處都沒有，只會搗亂！",
  ui_story_5028_50280101_76_dialog_content = "好吵啊，是誰來了？",
  ui_story_5028_50280101_77_dialog_content = "送信的？修窗戶的？還是？",
  ui_story_5028_50280101_78_dialog_content = "是我啊！你的徒弟！",
  ui_story_5028_50280101_79_dialog_content = "徒弟？哪個徒弟？",
  ui_story_5028_50280101_80_dialog_content = "維克",
  ui_story_5028_50280101_X80_dialog_content = "18歲？",
  ui_story_5028_50280101_81_dialog_content = "頹廢的無業遊民",
  ui_story_5028_50280101_82_dialog_content = "菲雅啊！菲雅！！！",
  ui_story_5028_50280101_83_dialog_content = "你喝酒喝糊塗了嗎！還記不記得自己叫什麼啊！",
  ui_story_5028_50280101_83X_dialog_content = "這可難不倒我，我叫維克。",
  ui_story_5028_50280101_83X1_dialog_content = "還真的以為我在考你啊......",
  ui_story_5028_50280101_84_dialog_content = "喔！菲雅妳回來了啊。",
  ui_story_5028_50280101_85_dialog_content = "我記得妳是去，那個......",
  ui_story_5028_50280101_86_dialog_content = "去蒐集林脈象糞便了來著？",
  ui_story_5028_50280101_87_dialog_content = "誰要做那種事啊！",
  ui_story_5028_50280101_88_dialog_content = "我去找鱗甲獸了！",
  ui_story_5028_50280101_89_dialog_content = "喔對，鱗甲獸。怎麼樣？抓到了嗎？",
  ui_story_5028_50280101_90_dialog_content = "本來馬上就要抓到了，但、是！",
  ui_story_5028_50280101_91_dialog_content = "這個凱羅一直在搗亂！最後還是讓牠跑掉了。",
  ui_story_5028_50280101_S91_dialog_content = "跑掉了啊，真可惜。所以妳為什麼要抓牠來著？",
  ui_story_5028_50280101_S92_dialog_content = "為了觀察牠的習性啊！這不是你佈置給我的作業嗎！",
  ui_story_5028_50280101_S93_dialog_content = "哦哦。那妳可以在筆記上記下「鱗甲獸膽小怕人」了。",
  ui_story_5028_50280101_S94_dialog_content = "哈？就這樣嗎？",
  ui_story_5028_50280101_S95_dialog_content = "剩下的慢慢來囉。還記得我說的嗎，對神奇動物的研究一定要建立在對牠們的尊重上。",
  ui_story_5028_50280101_S96_dialog_content = "尊重牠們千奇百怪的習性和脾氣，尊重牠們的現實處境。",
  ui_story_5028_50280101_S97_dialog_content = "理解而非干涉，才是成為神奇動物專家的關鍵。",
  ui_story_5028_50280101_92_dialog_content = "求學的道路就是這樣，妳要學習的東西多著呢。",
  ui_story_5028_50280101_93_dialog_content = "又是這一套。我知道我知道，這是「倚老賣老」對吧？",
  ui_story_5028_50280101_94_dialog_content = "說什麼呢！我可不老啊。",
  ui_story_5028_50280101_X94_dialog_content = "帥哥的年齡是不會增長的喔！",
  ui_story_5028_50280101_X95_dialog_content = "（哼，又在臭美。懶得理你！）",
  ui_story_5028_50280101_95_dialog_content = "我不明白的是，為什麼要讓凱羅跟著我？",
  ui_story_5028_50280101_96_dialog_content = "我，我跟牠配合不好，不適合做搭檔！",
  ui_story_5028_50280101_97_dialog_content = "有牠在，我什麼都做不成，更不用說成為<color=#FFB400>神奇動物專家</color>了！",
  ui_story_5028_50280101_98_dialog_content = "因為妳沒法和牠說話，對嗎？",
  ui_story_5028_50280101_99_dialog_content = "……",
  ui_story_5028_50280101_100_dialog_content = "嗯。",
  ui_story_5028_50280101_102_dialog_content = "和動物溝通是妳的天賦，但是太過依賴牠反而會變成壞事喔。",
  ui_story_5028_50280101_103_dialog_content = "就好比妳懂得光靈的語言，但是只靠這個能和大家成為朋友嗎？",
  ui_story_5028_50280101_104_dialog_content = "哦對不起，我忘了妳沒有朋友來著。",
  ui_story_5028_50280101_105_dialog_content = "你……！",
  ui_story_5028_50280101_106_dialog_content = "你不也一樣沒有朋友嗎！神氣什麼！",
  ui_story_5028_50280101_107_dialog_content = "大人交朋友可跟小孩子不一樣，妳懂什麼！",
  ui_story_5028_50280101_108_dialog_content = "哼，大人交朋友就是泡在酒吧裡跟別人吹牛嗎！",
  ui_story_5028_50280101_109_dialog_content = "那，那個是......",
  ui_story_5028_50280101_110_dialog_content = "最後還要自己的徒弟去幫忙付帳！",
  ui_story_5028_50280101_111_dialog_content = "難道無所事事的中年男人最後都會變成你這個樣子嗎？",
  ui_story_5028_50280101_112_dialog_content = "沒有錢，沒有事情做，還天天閒在家裡！",
  ui_story_5028_50280101_113_dialog_content = "好了妳不要再說了！而且誰是無所事事的中年男人啊？！",
  ui_story_5028_50280101_S113_dialog_content = "是誰要靠自己的徒弟照顧才能活下去啊！",
  ui_story_5028_50280101_S114_dialog_content = "每次出門前要給你準備一日三餐，回來還要收拾被小傢伙們弄亂的房間。",
  ui_story_5028_50280101_S115_dialog_content = "能不能試著靠自己獨立活下去啊，成！年！人！",
  ui_story_5028_50280101_S116_dialog_content = "妳......妳......",
  ui_story_5028_50280101_114_dialog_content = "我至少還是妳的師父吧？對師父說話不應該溫柔一點嗎？",
  ui_story_5028_50280101_X114_dialog_content = "那就溫柔一......",
  ui_story_5028_50280101_X115_dialog_content = "（不對不對，菲雅可沒有錯！）",
  ui_story_5028_50280101_X116_dialog_content = "（要是在這種時候示弱的話，又會像之前那樣被他糊弄過去了。）",
  ui_story_5028_50280101_X117_dialog_content = "（想表明態度就要兇一點。對，要兇！）",
  ui_story_5028_50280101_115_dialog_content = "誰讓你不用心教我！",
  ui_story_5028_50280101_116_dialog_content = "什麼都是讓我自己去試，你就在家裡躺著。",
  ui_story_5028_50280101_117_dialog_content = "現在變本加厲，還非要塞一個拖後腿的在我身邊。",
  ui_story_5028_50280101_118_dialog_content = "至少告訴我為什麼要這樣做吧！",
  ui_story_5028_50280101_119_dialog_content = "好吧，好吧，小孩子就是沉不住氣。",
  ui_story_5028_50280101_120_dialog_content = "妳有沒有想過，為什麼妳能跟所有動物溝通，唯獨牠不行？",
  ui_story_5028_50280101_121_dialog_content = "我不知道……",
  ui_story_5028_50280101_122_dialog_content = "因為凱羅牠啊——",
  ui_story_5028_50280101_123_dialog_content = "是<color=#FFB400>珍奇物種</color>喔。",
  ui_story_5028_50280101_124_dialog_content = "珍奇物種？！！",
  ui_story_5028_50280101_125_dialog_content = "囉？",
  ui_story_5028_50280101_126_dialog_content = "我們研究的神奇動物，是自然界中數量稀少、習性奇特的一類生物。",
  ui_story_5028_50280101_X126_dialog_content = "這種奇特也許是因為牠們能用自己的方式運用光能。",
  ui_story_5028_50280101_X127_dialog_content = "而珍奇物種，更是神奇動物中鳳毛麟角的種類，擁有遠超尋常神奇動物的力量。",
  ui_story_5028_50280101_127_dialog_content = "那牠怎麼看起來傻乎乎的？",
  ui_story_5028_50280101_128_dialog_content = "因為牠還沒有成熟啊，傻孩子。",
  ui_story_5028_50280101_129_dialog_content = "珍奇物種需要經歷一次徹底的蛻變，我稱之為<color=#FFB400>「進化」</color>。",
  ui_story_5028_50280101_130_dialog_content = "完成進化的凱羅，強大到讓妳無法想像！",
  ui_story_5028_50280101_131_dialog_content = "想要錢，牠能將石頭化為黃金。",
  ui_story_5028_50280101_132_dialog_content = "想要力量，牠可以輕而易舉地摧毀軍隊，叫白夜城望塵莫及。",
  ui_story_5028_50280101_133_dialog_content = "想要權力，牠與生俱來的威壓無與倫比，連北境女王見了都要低頭！",
  ui_story_5028_50280101_134_dialog_content = "把牠送給妳，師父我可是千萬個捨不得啊。",
  ui_story_5028_50280101_135_dialog_content = "但是，哎，誰讓我們師徒情深呢。",
  ui_story_5028_50280101_136_dialog_content = "……",
  ui_story_5028_50280101_137_dialog_content = "你又在吹牛了吧。",
  ui_story_5028_50280101_138_dialog_content = "啊？怎......怎麼能這樣說師父呢！",
  ui_story_5028_50280101_139_dialog_content = "我已經聽過很多次了。",
  ui_story_5028_50280101_140_dialog_content = "去年，你說要買個飛艇帶我出去玩。",
  ui_story_5028_50280101_141_dialog_content = "我打包行李期待了很久，結果你只是買了一串氣球回來！",
  ui_story_5028_50280101_142_dialog_content = "不是，我只是沒想到飛艇那麼貴......",
  ui_story_5028_50280101_143_dialog_content = "還有冬天的時候，你告訴我說有個重要的課題，需要研究海裡的刺刺豚。",
  ui_story_5028_50280101_144_dialog_content = "我花了三天的時間去找牠，又用了一整晚才把牠抓住。",
  ui_story_5028_50280101_145_dialog_content = "結......果！你只是想用牠刷鞋！！！",
  ui_story_5028_50280101_146_dialog_content = "喔，那個是......",
  ui_story_5028_50280101_147_dialog_content = "還有你說自己是貴族，當過歌手，被幾百萬粉絲圍追堵截才躲起來研究神奇動物。",
  ui_story_5028_50280101_148_dialog_content = "全都是假的！都是在騙我！",
  ui_story_5028_50280101_149_dialog_content = "這次的珍奇物種也一樣！",
  ui_story_5028_50280101_X149_dialog_content = "（氣死了！我明明這麼努力，他卻......他卻......）",
  ui_story_5028_50280101_X150_dialog_content = "菲雅，妳先等一下......",
  ui_story_5028_50280101_150_dialog_content = "<size=50>我，我是真的想成為神奇動物專家的啊！</size>",
  ui_story_5028_50280101_151_dialog_content = "結果，知識沒有學到，還要帶個拖油瓶......",
  ui_story_5028_50280101_152_dialog_content = "這樣子還......還不如我一個人呢！",
  ui_story_5028_50280101_153_dialog_content = "……",
  ui_story_5028_50280101_154_dialog_content = "原來如此，我明白了。",
  ui_story_5028_50280101_155_dialog_content = "在妳看來，我這個師父已經教不了妳任何東西了，是嗎？",
  ui_story_5028_50280101_156_dialog_content = "啊，那個……",
  ui_story_5028_50280101_157_dialog_content = "妳很有天賦，也許是我傳統的教育方式落伍了吧。",
  ui_story_5028_50280101_158_dialog_content = "我以為我在把妳培養成一名合格的神奇動物專家。",
  ui_story_5028_50280101_159_dialog_content = "讓妳自己去試，是因為我覺得親身實踐非常重要。",
  ui_story_5028_50280101_160_dialog_content = "不陪在妳身邊，是希望妳能學會自己解決難題。",
  ui_story_5028_50280101_161_dialog_content = "但是現在看來，我的想法全都錯了啊。",
  ui_story_5028_50280101_162_dialog_content = "哎呀，不是......",
  ui_story_5028_50280101_163_dialog_content = "也是。妳是能跟動物溝通的天才，不需要多餘的教育。",
  ui_story_5028_50280101_164_dialog_content = "妳準備出師吧。",
  ui_story_5028_50280101_165_dialog_content = "出師？！",
  ui_story_5028_50280101_166_dialog_content = "嗯，妳已經不需要我這個師父了。",
  ui_story_5028_50280101_167_dialog_content = "我，我不是這個意思......",
  ui_story_5028_50280101_168_dialog_content = "正好，出師的儀式就由牠來完成吧。",
  ui_story_5028_50280101_169_dialog_content = "囉？",
  ui_story_5028_50280101_170_dialog_content = "欸？",
  ui_story_5028_50280101_171_dialog_content = "最後還是希望，我的徒弟能夠得償所願。",
  ui_story_5028_50280101_172_dialog_content = "這隻稀有的珍奇物種，凱羅，是我送給妳的禮物。",
  ui_story_5028_50280101_173_dialog_content = "如果妳能讓牠順利進化，一定有資格被稱為神奇動物專家了。",
  ui_story_5028_50280101_174_dialog_content = "就讓這件事，作為我給妳上的最後一課吧。",
  ui_story_5028_50280101_175_dialog_content = "師父……",
  ui_story_5028_50280101_176_dialog_content = "不要哭，成為神奇動物專家不是妳一直以來的願望嗎？",
  ui_story_5028_50280101_177_dialog_content = "讓凱羅進化後回來出師，妳的願望就達成了啊。",
  ui_story_5028_50280101_178_dialog_content = "至於我這個可有可無的師父......留我孤獨終老就好了。",
  ui_story_5028_50280101_179_dialog_content = "師父，你......",
  ui_story_5028_50280101_180_dialog_content = "你還沒有告訴我該怎麼讓凱羅進化呢。",
  ui_story_5028_50280101_181_dialog_content = "……",
  ui_story_5028_50280101_182_dialog_content = "妳關心的是這個？",
  ui_story_5028_50280101_183_dialog_content = "不然呢？",
  ui_story_5028_50280101_184_dialog_content = "因為能成為神奇動物專家？",
  ui_story_5028_50280101_185_dialog_content = "嗯！我的夢想！",
  ui_story_5028_50280101_186_dialog_content = "就，就沒什麼想對師父說的嗎？",
  ui_story_5028_50280101_187_dialog_content = "喔——有的！",
  ui_story_5028_50280101_188_dialog_content = "師父你這次不會又是在騙我吧？",
  ui_story_5028_50280101_189_dialog_content = "妳……",
  ui_story_5028_50280101_190_dialog_content = "你不會根本就不知道進化的方法吧？",
  ui_story_5028_50280101_191_dialog_content = "或者說，進化這件事其實也不存在？",
  ui_story_5028_50280101_192_dialog_content = "當，當然確有其事！",
  ui_story_5028_50280101_193_dialog_content = "師父什麼時候騙過妳？",
  ui_story_5028_50280101_194_dialog_content = "……",
  ui_story_5028_50280101_195_dialog_content = "好吧，師父這次不會騙妳。",
  ui_story_5028_50280101_196_dialog_content = "只是珍奇物種的進化確實很困難，我也沒有一定能夠成功的方法。",
  ui_story_5028_50280101_197_dialog_content = "這本筆記，妳收下吧。",
  ui_story_5028_50280101_198_dialog_content = "喔！",
  ui_story_5028_50280101_199_dialog_content = "上面記錄了幾項師父精心設計的試煉。",
  ui_story_5028_50280101_200_dialog_content = "記住師父的話，實踐是最重要的。",
  ui_story_5028_50280101_201_dialog_content = "完成所有試煉，凱羅一定能順利進化。",
  ui_story_5028_50280101_202_dialog_content = "妳要相信自己，總有一天妳會成為......",
  ui_story_5028_50280101_203_dialog_content = "好的，謝謝師父！",
  ui_story_5028_50280101_204_dialog_content = "那我這就出發了噢，拜拜！",
  ui_story_5028_50280101_205_dialog_content = "哎等一下，師父話還沒......",
  ui_story_5028_50280101_206_dialog_content = "<color=#e8d9bb>啪！</color>",
  ui_story_5028_50280101_207_dialog_content = "神奇動物專家......",
  ui_story_5028_50280101_208_dialog_content = "凱羅，你真的能進化嗎？",
  ui_story_5028_50280101_209_dialog_content = "囉！",
  ui_story_5028_50280101_210_dialog_content = "讓我來看看，不靠譜的師父給我留下了什麼試煉。",
  ui_story_5028_50280101_211_dialog_content = "「珍奇物種進化論」",
  ui_story_5028_50280101_212_dialog_content = "「寫在前面：試煉內容來源於本人的經驗。」",
  ui_story_5028_50280101_213_dialog_content = "「僅作建議，不承諾一定有效。」",
  ui_story_5028_50280101_214_dialog_content = "哼，一上來就要撇清責任嗎！",
  ui_story_5028_50280101_215_dialog_content = "不過，一、二、三、四，方法還滿多的。",
  ui_story_5028_50280101_216_dialog_content = "「試煉一：抓捕一隻<color=#FFB400>空裔</color>，並將其馴服，成為朋友。」",
  ui_story_5028_50280101_217_dialog_content = "空裔？那是什麼動物？",
  ui_story_5028_50280201_1_dialog_content = "試煉：抓捕空裔",
  ui_story_5028_50280201_2_dialog_content = "PlayerName，我們什麼時候可以開始玩啊？",
  ui_story_5028_50280201_3_dialog_content = "再等一下，馬上就可以了。",
  ui_story_5028_50280201_4_dialog_content = "為什麼現在不可以？我等不及了。",
  ui_story_5028_50280201_5_dialog_content = "因為我們需要一個寬闊、平坦的場地。",
  ui_story_5028_50280201_6_dialog_content = "這裡到處都是障礙，可沒法打球啊。",
  ui_story_5028_50280201_7_dialog_content = "喔，我知道了。",
  ui_story_5028_50280201_8_dialog_content = "那我們可以走得快一點嗎？",
  ui_story_5028_50280201_9_dialog_content = "真是心急啊，哈哈哈。好吧好吧，我們快點。",
  ui_story_5028_50280201_10_dialog_content = "<color=#e8d9bb>沙......沙沙......</color>",
  ui_story_5028_50280201_11_dialog_content = "接下來我會往妳的方向投球，妳來用手上的球棒擊球。",
  ui_story_5028_50280201_12_dialog_content = "我前段時間剛從研究過這些古代文化的露比那裡學來了規則。",
  ui_story_5028_50280201_13_dialog_content = "簡單來說，把球打得愈遠就愈厲害。",
  ui_story_5028_50280201_14_dialog_content = "妳瞭解了嗎？",
  ui_story_5028_50280201_15_dialog_content = "瞭解了！用棒子打球！",
  ui_story_5028_50280201_16_dialog_content = "好！我們來試一次！",
  ui_story_5028_50280201_17_dialog_content = "三、二、一......",
  ui_story_5028_50280201_18_dialog_content = "接招！",
  ui_story_5028_50280201_19_dialog_content = "<color=#e8d9bb>咻——</color>",
  ui_story_5028_50280201_20_dialog_content = "欸，怎麼躲開了？",
  ui_story_5028_50280201_21_dialog_content = "PlayerName，為什麼要攻擊我？",
  ui_story_5028_50280201_22_dialog_content = "這不是攻擊喔，是在投球。",
  ui_story_5028_50280201_23_dialog_content = "投球？",
  ui_story_5028_50280201_24_dialog_content = "嗯。我把球向妳拋過去，妳在空中將它擊飛，這個遊戲就是這樣玩的。",
  ui_story_5028_50280201_25_dialog_content = "我明白了，再來一次。",
  ui_story_5028_50280201_26_dialog_content = "好。不要緊張，一開始打不中球很正常。",
  ui_story_5028_50280201_27_dialog_content = "嗯。",
  ui_story_5028_50280201_28_dialog_content = "準備好！三、二、一......",
  ui_story_5028_50280201_29_dialog_content = "接招！",
  ui_story_5028_50280201_30_dialog_content = "<color=#e8d9bb>咻——</color>",
  ui_story_5028_50280201_31_dialog_content = "<color=#e8d9bb>嘭！！！</color>",
  ui_story_5028_50280201_32_dialog_content = "喔哦哦！！！打中了！！！",
  ui_story_5028_50280201_33_dialog_content = "喔！我做到了！",
  ui_story_5028_50280201_34_dialog_content = "球，飛得好遠！",
  ui_story_5028_50280201_35_dialog_content = "是啊！這就是傳說中的「全壘打」啊！",
  ui_story_5028_50280201_36_dialog_content = "雷文頓妳說不定有打球的天賦喔！",
  ui_story_5028_50280201_37_dialog_content = "我，有天賦？",
  ui_story_5028_50280201_38_dialog_content = "嗯！第一次就打成這樣太厲害了！",
  ui_story_5028_50280201_39_dialog_content = "打球，好玩。",
  ui_story_5028_50280201_40_dialog_content = "接下來該怎麼玩？",
  ui_story_5028_50280201_41_dialog_content = "接下來啊......",
  ui_story_5028_50280201_42_dialog_content = "呃，好像要先把球撿回來。",
  ui_story_5028_50280201_43_dialog_content = "嗚哇，飛那麼遠，這可麻煩了。",
  ui_story_5028_50280201_44_dialog_content = "對不起，下次，我會打得輕一點。",
  ui_story_5028_50280201_45_dialog_content = "沒有沒有，不是在怪妳，規則就是打得愈遠愈好喔！",
  ui_story_5028_50280201_46_dialog_content = "那，我去撿球吧，我跑得快。",
  ui_story_5028_50280201_47_dialog_content = "好像已經過去五、六分鐘了啊，雷文頓她怎麼還沒回來。",
  ui_story_5028_50280201_48_dialog_content = "<color=#e8d9bb>沙......</color>",
  ui_story_5028_50280201_49_dialog_content = "莫非是找不到球了，或者遇到了什麼危險？",
  ui_story_5028_50280201_50_dialog_content = "我好像隱約回憶起，薇絲和我說這附近似乎有暗鬼出沒？！",
  ui_story_5028_50280201_51_dialog_content = "<color=#e8d9bb>沙......沙......</color>",
  ui_story_5028_50280201_52_dialog_content = "啊，不過一般的暗鬼應該也傷不到她吧。",
  ui_story_5028_50280201_53_dialog_content = "畢竟她可是雷......",
  ui_story_5028_50280201_54_dialog_content = "上！",
  ui_story_5028_50280201_55_dialog_content = "？！網子？？",
  ui_story_5028_50280201_56_dialog_content = "笨蛋凱羅！又歪了！",
  ui_story_5028_50280201_57_dialog_content = "既然這樣就沒辦法了，我們硬上吧！",
  ui_story_5028_50280201_58_dialog_content = "妳，妳是誰啊！？我跟妳講，我可是很厲害的。",
  ui_story_5028_50280201_59_dialog_content = "剛剛在我身邊那個光靈空手劈暗鬼就像是劈西瓜一樣！",
  ui_story_5028_50280201_60_dialog_content = "妳再過來的話，我就要用「感應能力」叫人來幫忙了！",
  ui_story_5028_50280201_61_dialog_content = "「感應能力」？你果然就是空裔！",
  ui_story_5028_50280201_62_dialog_content = "不要給他呼叫幫手的機會！",
  ui_story_5028_50280201_63_dialog_content = "凱羅，我們用B計畫！",
  ui_story_5028_50280201_64_dialog_content = "囉！",
  ui_story_5028_50280201_65_dialog_content = "等一下！B計畫是什麼意思！",
  ui_story_5028_50280201_66_dialog_content = "妳別再過來了，我真的會叫人來喔！",
  ui_story_5028_50280201_67_dialog_content = "動手——",
  ui_story_5028_50280201_68_option_content = "強制......嗷！！",
  ui_story_5028_50280201_69_dialog_content = "我的腰！！",
  ui_story_5028_50280201_70_dialog_content = "囉囉囉！",
  ui_story_5028_50280201_71_dialog_content = "幹得好凱羅，我們按原計畫撤退進森林裡！",
  ui_story_5028_50280201_72_dialog_content = "囉囉！",
  ui_story_5028_50280201_73_dialog_content = "放，放我下來，你們要帶我去哪——！！",
  ui_story_5028_50280201_74_dialog_content = "<anim type=Shake><size=45>雷文頓——雷文——！</size></anim>",
  ui_story_5028_50280201_76_dialog_content = "我回來了，剛剛不小心把一隻白兔當成球追了半天。",
  ui_story_5028_50280201_77_dialog_content = "嗯？PlayerName人呢？",
  ui_story_5028_50280201_78_dialog_content = "球棒也還在這裡，我懂了，是PlayerName想讓我多練習練習全壘打吧？",
  ui_story_5028_50280201_79_dialog_content = "我不會白費你的苦心的，先揮棒一千次，開始。",
  ui_story_5028_50280201_80_dialog_content = "囉！",
  ui_story_5028_50280201_81_dialog_content = "等，等一下，妳想用這個奇怪的東西載著我去哪裡啊！",
  ui_story_5028_50280201_82_dialog_content = "先把我放下來，我的腰剛剛好像被撞斷了，痛死了！",
  ui_story_5028_50280201_83_dialog_content = "囉？",
  ui_story_5028_50280201_84_dialog_content = "等一下，凱羅！",
  ui_story_5028_50280201_85_dialog_content = "呼......終於肯停下來了嗎？痛痛痛。",
  ui_story_5028_50280201_86_dialog_content = "凱羅，這是B計畫的路線嗎？",
  ui_story_5028_50280201_87_dialog_content = "囉囉？",
  ui_story_5028_50280201_88_dialog_content = "你該不會就只是胡亂跑進森林裡吧？",
  ui_story_5028_50280201_89_dialog_content = "囉......",
  ui_story_5028_50280201_90_dialog_content = "已經看不到過來的路了......四周都是樹木。",
  ui_story_5028_50280201_91_dialog_content = "你，你們太亂來了！這個森林裡可是有暗鬼啊！",
  ui_story_5028_50280201_92_dialog_content = "暗鬼？",
  ui_story_5028_50280201_93_dialog_content = "吼——！！",
  ui_story_5028_50280201_94_dialog_content = "真的出現了！！",
  ui_story_5028_50280201_95_dialog_content = "怎麼會......有暗鬼啊！",
  ui_story_5028_50280201_96_dialog_content = "愣著幹什麼！快跑啊！",
  ui_story_5028_50280201_97_dialog_content = "嘎！！",
  ui_story_5028_50280201_98_dialog_content = "凱羅！",
  ui_story_5028_50280201_99_dialog_content = "囉！",
  ui_story_5028_50280201_100_dialog_content = "怎麼會有暗鬼啊，怎麼會有暗鬼啊！",
  ui_story_5028_50280201_101_dialog_content = "不要想那麼多了！先跑再說！",
  ui_story_5028_50280201_102_dialog_content = "不行，要跑不動了，嗚......",
  ui_story_5028_50280201_103_dialog_content = "菲雅雖然很擅長和神奇動物相處，但是暗鬼什麼的好討厭呀！",
  ui_story_5028_50280201_104_dialog_content = "菲雅不要，菲雅不要在成為神奇動物專家之前就被暗鬼吃掉啊！",
  ui_story_5028_50280201_105_dialog_content = "想想辦法，一定有什麼辦法的......",
  ui_story_5028_50280201_106_dialog_content = "師父說過，面對危險絕對不能哭，要動腦筋！",
  ui_story_5028_50280201_107_dialog_content = "或者菲雅來爭取時間，讓凱羅和空裔趕快逃走。",
  ui_story_5028_50280201_108_dialog_content = "但是就憑菲雅的力氣......不管了，不能讓他們受我牽連！",
  ui_story_5028_50280201_109_dialog_content = "那個，那個妳冷靜點呀，妳會戰鬥技巧嗎？",
  ui_story_5028_50280201_110_dialog_content = "嗚......雖然會一些，但是只是防身用的而已。",
  ui_story_5028_50280201_111_dialog_content = "沒關係！一段冒險剛開始的時候敵人往往都很弱的！",
  ui_story_5028_50280201_112_dialog_content = "命運嘛，說到底就是這種東西啦。",
  ui_story_5028_50280201_113_dialog_content = "我可以用我的力量來協助妳！",
  ui_story_5028_50280201_114_dialog_content = "我們繼續在森林裡跑來跑去只會招惹更多暗鬼。",
  ui_story_5028_50280201_114X_dialog_content = "不如先擊敗眼前的追兵，再討論對策吧！",
  ui_story_5028_50280201_115_dialog_content = "但是暗鬼數量那麼多......",
  ui_story_5028_50280201_116_dialog_content = "相信我！",
  ui_story_5028_50280201_117_dialog_content = "不光是我們兩個，還有妳這位朋友對吧！我們合作一定能贏的！",
  ui_story_5028_50280201_118_dialog_content = "囉！",
  ui_story_5028_50280201_119_dialog_content = "嗚！好吧！",
  ui_story_5028_50280201_120_dialog_content = "不要再用「妳」來稱呼我了！我可是世界第一的神奇動物專家！",
  ui_story_5028_50280201_121_dialog_content = "你們這些臭暗鬼，居然敢突然跑出來嚇到本小姐！",
  ui_story_5028_50280201_122_dialog_content = "給我一個個排好隊準備挨揍吧！",
  ui_story_5028_50280202_1_dialog_content = "居然，居然真的贏了！",
  ui_story_5028_50280202_2_dialog_content = "太棒了！凱羅，你看到了嗎！",
  ui_story_5028_50280202_3_dialog_content = "囉！囉！",
  ui_story_5028_50280202_4_dialog_content = "嘿嘿～想不到你還滿厲害的嘛，凱羅！菲雅對你刮目相看了！",
  ui_story_5028_50280202_5_dialog_content = "囉～",
  ui_story_5028_50280202_6_dialog_content = "（不如就趁他們兩個摟在一起慶祝的時候走掉吧。）",
  ui_story_5028_50280202_7_dialog_content = "那個......",
  ui_story_5028_50280202_8_dialog_content = "（不過這裡都是暗鬼，這樣一走了之也很危險吧。）",
  ui_story_5028_50280202_9_dialog_content = "（唉。）",
  ui_story_5028_50280202_10_dialog_content = "那個，空裔先生？",
  ui_story_5028_50280202_11_dialog_content = "啊，我在。",
  ui_story_5028_50280202_12_dialog_content = "謝謝你剛剛......幫助了菲雅和凱羅。",
  ui_story_5028_50280202_13_dialog_content = "沒關係沒關係，都是小事而已。",
  ui_story_5028_50280202_14_dialog_content = "完全不用感謝我的，不如我就這樣回去吧，也不給兩位添麻煩了。",
  ui_story_5028_50280202_15_dialog_content = "怎麼可能呢，空裔先生。",
  ui_story_5028_50280202_16_dialog_content = "你該不會以為看到了淑女出醜時的模樣，還能一聲不吭地全身而退吧？",
  ui_story_5028_50280202_17_dialog_content = "我，我失憶了！這是哪裡？剛才發生了什麼？",
  ui_story_5028_50280202_18_dialog_content = "裝作失憶也沒用喔。",
  ui_story_5028_50280202_19_dialog_content = "乖乖和凱羅一樣變成我的夥伴和寵物，跟在我身邊幫忙吧！",
  ui_story_5028_50280202_20_dialog_content = "（嘿嘿，這裡就用上菲雅最甜美的笑容，一舉拿下空裔先生吧！）",
  ui_story_5028_50280202_21_dialog_content = "不行！我拒絕！",
  ui_story_5028_50280202_22_dialog_content = "欸？？",
  ui_story_5028_50280202_23_dialog_content = "我剛剛是出於好意幫助妳的，並不是說我就要聽從妳的話。",
  ui_story_5028_50280202_24_dialog_content = "何況我還沒跟妳計較妳讓這個叫凱羅的生物撞我，然後強行把我帶到這裡的事呢。",
  ui_story_5028_50280202_25_dialog_content = "我們先一起離開森林，然後人情兩清，各走一方！",
  ui_story_5028_50280202_26_dialog_content = "嗚……",
  ui_story_5028_50280202_27_dialog_content = "（我說話太兇了嗎？）",
  ui_story_5028_50280202_28_dialog_content = "（不，不對，這個小姑娘也有可能是在騙我，她身邊那個凱羅也很可疑。）",
  ui_story_5028_50280202_29_dialog_content = "嗚嗚……",
  ui_story_5028_50280202_30_dialog_content = "菲雅只是......菲雅只是想要一個朋友而已......",
  ui_story_5028_50280202_31_dialog_content = "囉......",
  ui_story_5028_50280202_32_dialog_content = "別人都說只有神奇動物會喜歡菲雅，菲雅也想證明自己能和光靈、空裔成為朋友......",
  ui_story_5028_50280202_33_dialog_content = "只是想完成師父的「遺願」而已......",
  ui_story_5028_50280202_34_dialog_content = "（師父？剛剛她提到過的人嗎？遺願？他已經去世了嗎？）",
  ui_story_5028_50280202_35_dialog_content = "哈啾——",
  ui_story_5028_50280202_36_dialog_content = "我沒事，小毛球，可能只是感冒了。",
  ui_story_5028_50280202_37_dialog_content = "你很擔心我？那讓我用你擦一下鼻子可以嗎？",
  ui_story_5028_50280202_38_dialog_content = "啊哈哈，當然是開玩笑啦，我還要用你脫下的毛去換酒喝呢。",
  ui_story_5028_50280202_39_dialog_content = "（不會真的要哭了吧，眼眶紅紅的。）",
  ui_story_5028_50280202_40_dialog_content = "（這個小姑娘看起來年紀比雷文頓還小很多，而且不擅長戰鬥。）",
  ui_story_5028_50280202_40X_dialog_content = "（自己在外面很辛苦吧。）",
  ui_story_5028_50280202_41_dialog_content = "所以菲雅才......才想綁架空裔先生，和你做朋友......",
  ui_story_5028_50280202_42_dialog_content = "（不要哭，不要哭，千萬不要哭......）",
  ui_story_5028_50280202_43_dialog_content = "真的......真的很對不起，對你做了那麼過分的事情，菲雅真的很後悔。",
  ui_story_5028_50280202_44_dialog_content = "如果空裔先生那麼討厭菲雅，就留菲雅一個人在這裡......",
  ui_story_5028_50280202_45_dialog_content = "自生自滅吧......",
  ui_story_5028_50280202_46_dialog_content = "嗚啊啊啊！！",
  ui_story_5028_50280202_47_dialog_content = "我錯了！！",
  ui_story_5028_50280202_48_dialog_content = "對不起，對不起，我不該對妳那麼兇的。",
  ui_story_5028_50280202_49_dialog_content = "妳要做朋友是吧，我很願意和妳做朋友，我叫PlayerName。",
  ui_story_5028_50280202_50_dialog_content = "真......真的嗎？我叫菲雅！",
  ui_story_5028_50280202_51_dialog_content = "好，菲雅，那麼我們就是朋友了！",
  ui_story_5028_50280202_52_dialog_content = "真的嗎？",
  ui_story_5028_50280202_53_dialog_content = "真的！千真萬確！",
  ui_story_5028_50280202_54_dialog_content = "囉！",
  ui_story_5028_50280202_55_dialog_content = "嘿嘿......那PlayerName，你就是我的第一位朋友啦！",
  ui_story_5028_50280202_56_dialog_content = "PlayerName你願意做菲雅的朋友，菲雅太高興啦！",
  ui_story_5028_50280202_57_dialog_content = "師父你看著吧，菲雅可是交到朋友了！",
  ui_story_5028_50280202_58_dialog_content = "囉囉～",
  ui_story_5028_50280202_59_dialog_content = "（可惡！先是眼淚攻擊然後又露出這麼可愛的笑容嗎？）",
  ui_story_5028_50280202_60_dialog_content = "（不過，她就像是曾經一個人的我一樣沒有朋友嗎？不，我至少還有臨空者號。）",
  ui_story_5028_50280202_61_dialog_content = "（但她也有這隻叫凱羅的生物陪著吧。）",
  ui_story_5028_50280202_62_dialog_content = "（就算她在演戲，我也不可能這樣丟下一個小姑娘自己在深山裡哭。）",
  ui_story_5028_50280202_63_dialog_content = "PlayerName，PlayerName，你在想什麼呀？",
  ui_story_5028_50280202_64_dialog_content = "啊，沒什麼，我在想我們該回去了，然後用巨像送妳回家。",
  ui_story_5028_50280202_65_dialog_content = "對了！我想起來空裔是有巨像的。",
  ui_story_5028_50280202_66_dialog_content = "那麼我們之後的旅行就用巨像代步吧，一定會很快完成師父的考驗！",
  ui_story_5028_50280202_67_dialog_content = "走吧走吧，PlayerName哥哥～",
  ui_story_5028_50280202_68_dialog_content = "啊？妳在說什麼考驗，不要拉著我的手啊。",
  ui_story_5028_50280202_69_dialog_content = "痛痛，腰還在痛，不要拽了！",
  ui_story_5028_50280202_70_dialog_content = "我還要，我還要和雷文頓說一聲才行啊——！",
  ui_story_5028_50280202_71_dialog_content = "998......嘿！999......嘿！",
  ui_story_5028_50280202_72_dialog_content = "1000......嘿！",
  ui_story_5028_50280202_73_dialog_content = "PlayerName，還沒回來嗎？我已經完成練習了。",
  ui_story_5028_50280202_74_dialog_content = "算了，說不定PlayerName回巨像上了，我回去看看吧。",
  ui_story_5028_50280202_75_dialog_content = "欸？",
  ui_story_5028_50280202_76_dialog_content = "巨像呢？",
  ui_story_5028_50280202_77_dialog_content = "PlayerName呢？",
  ui_story_5028_50280202_78_dialog_content = "人呢？",
  ui_story_5028_50280202_79_dialog_content = "這封信又是啥？",
  ui_story_5028_50280301_1_dialog_content = "試煉：為蒼獅龍接生",
  ui_story_5028_50280301_2_dialog_content = "<color=#FFB400>蒼獅龍</color>，頭部好似神話中發怒巨龍的頭顱。",
  ui_story_5028_50280301_3_dialog_content = "擁有獅子般強健的軀體與鷹鷲般壯碩的雙翼......",
  ui_story_5028_50280301_4_dialog_content = "可以輕鬆一擊抽倒犀牛的強壯尾巴......",
  ui_story_5028_50280301_5_dialog_content = "更可怕的是牠那強而有力的雙腿。",
  ui_story_5028_50280301_5X_dialog_content = "讓蒼獅龍在地面上也可以追上任何獵物並無情地將其制服。",
  ui_story_5028_50280301_6_dialog_content = "不過所幸，比起如同列車般在地上橫衝直撞，牠更喜歡飛在天空中。",
  ui_story_5028_50280301_6X_dialog_content = "極少進入一般人的視野。",
  ui_story_5028_50280301_7_dialog_content = "而這次......我們的目標就是被尊為<color=#FFB400>「珍奇物種」</color>的牠。",
  ui_story_5028_50280301_8_dialog_content = "那個，菲雅妳在那裡嘟囔什麼呢？",
  ui_story_5028_50280301_9_dialog_content = "妳手裡那本看起來很厲害的書，可以借我看看嗎？",
  ui_story_5028_50280301_10_dialog_content = "噓——！",
  ui_story_5028_50280301_11_dialog_content = "啊，真是的！菲雅完美的開場白都被你打斷了。",
  ui_story_5028_50280301_12_dialog_content = "囉～",
  ui_story_5028_50280301_13_dialog_content = "什麼旁白不旁白的，就只有妳和我在這裡啊。",
  ui_story_5028_50280301_14_dialog_content = "為什麼要這樣說話？",
  ui_story_5028_50280301_15_dialog_content = "哼哼，做我們這行可是很講究規矩的喔。",
  ui_story_5028_50280301_16_dialog_content = "在接觸目標神奇動物之前，必須再複習一遍牠的相關生態。",
  ui_story_5028_50280301_17_dialog_content = "特別是蒼獅龍這樣珍稀的神奇動物，更要對牠可能出現的地方進行周密調查。",
  ui_story_5028_50280301_18_dialog_content = "這樣工作起來就會更有儀式感，遇到突發情況也能臨危不亂！",
  ui_story_5028_50280301_19_dialog_content = "囉囉！",
  ui_story_5028_50280301_20_dialog_content = "......我現在有點害怕，是不是妳單純不夠熟悉想要複習一下。",
  ui_story_5028_50280301_21_dialog_content = "咳，你不用擔心，菲雅已經周密調查過了，蒼獅龍有九成九的把握會出現喔。",
  ui_story_5028_50280301_22_dialog_content = "鷹鷲般壯碩的雙翼......",
  ui_story_5028_50280301_23_dialog_content = "這個剛剛講過了，不用再複習一次吧？",
  ui_story_5028_50280301_24_dialog_content = "噓！噓！請不要一直打擾菲雅。",
  ui_story_5028_50280301_25_dialog_content = "要解讀師父這個蚯蚓爬行一樣的字跡可是很耗費精力的！",
  ui_story_5028_50280301_26_dialog_content = "啊......那個筆記本是師父的「遺物」......？",
  ui_story_5028_50280301_27_dialog_content = "「伊唔」？總之稍微安靜一下啦，我正準備講到重點呢。",
  ui_story_5028_50280301_28_dialog_content = "蒼獅龍非常神奇，牠們對天空有著異常的迷戀。",
  ui_story_5028_50280301_29_dialog_content = "即使在生產時也不會輕易降落，除非周圍出現威脅孩子的生物。",
  ui_story_5028_50280301_30_dialog_content = "當威脅出現，牠們會招來怒雷，並以利爪將任何膽敢冒犯的敵人撕碎。",
  ui_story_5028_50280301_31_dialog_content = "但牠們並不會在意自己從空中產下的蛋是否能順利降落並成長。",
  ui_story_5028_50280301_32_dialog_content = "讓孩子獨自面對充滿危險的世界，也許這就是蒼空之王對自己後代的一種篩選吧。",
  ui_story_5028_50280301_33_dialog_content = "也正因如此，蒼獅龍的數量十分稀少。",
  ui_story_5028_50280301_34_dialog_content = "怪不得，這次的試煉是幫助蒼獅龍的蛋安全孵化。",
  ui_story_5028_50280301_35_dialog_content = "雖然有時要尊重神奇動物本身的習性，但有時也必須伸出援手，讓牠們能茁壯成長。",
  ui_story_5028_50280301_36_dialog_content = "嗯嗯！這樣的試煉果然很有神奇動物專家的感覺呀！",
  ui_story_5028_50280301_37_dialog_content = "囉～",
  ui_story_5028_50280301_38_dialog_content = "這也太危險了吧！告辭了！",
  ui_story_5028_50280301_39_dialog_content = "等......等等啊！不要扭頭就走！",
  ui_story_5028_50280301_40_dialog_content = "囉囉囉！",
  ui_story_5028_50280301_41_dialog_content = "啊哈哈，按照師父的筆記，那顆蛋只要能安全落地轉瞬間就會孵化。",
  ui_story_5028_50280301_42_dialog_content = "我們只要幫助牠的蛋安全降落就可以啦！",
  ui_story_5028_50280301_43_dialog_content = "就這麼簡單嗎......？在妳剛剛的旁白里，那條龍可非常不好惹啊。",
  ui_story_5028_50280301_44_dialog_content = "那隻蒼獅龍的危險程度，用你們專業的評價來打分，大概是多少分？",
  ui_story_5028_50280301_45_dialog_content = "大概，大概50分左右吧？",
  ui_story_5028_50280301_46_dialog_content = "嗯，那也就是只有中等的危險程度吧。稍微安心一些了。",
  ui_story_5028_50280301_47_dialog_content = "（欸？沒想到PlayerName一下子就相信了，這樣菲雅的負罪感好強呀。）",
  ui_story_5028_50280301_48_dialog_content = "滿分......10分......",
  ui_story_5028_50280301_49_dialog_content = "……",
  ui_story_5028_50280301_50_dialog_content = "囉......",
  ui_story_5028_50280301_51_dialog_content = "我聽到了！我要回去了！",
  ui_story_5028_50280301_52_dialog_content = "不要走不要走，拜託了！",
  ui_story_5028_50280301_53_dialog_content = "我還有道具啦，我有可以清除我們身上氣味的道具啦！",
  ui_story_5028_50280301_54_dialog_content = "只要用了就絕對不會有問題的，筆記里說過蒼獅龍視力非常差，肯定發現不了我們！",
  ui_story_5028_50280301_55_dialog_content = "唉......",
  ui_story_5028_50280301_56_dialog_content = "就沒有其他安全一點的方法嗎？",
  ui_story_5028_50280301_57_dialog_content = "比如我們乘著臨空者號在下面接著？",
  ui_story_5028_50280301_58_dialog_content = "理論上是可以啦，但是有個小問題。",
  ui_story_5028_50280301_59_dialog_content = "如果想蒼獅龍不攻擊的話，我首先得知道，臨空者號牠......是雄性還是雌性啊？",
  ui_story_5028_50280301_60_dialog_content = "……",
  ui_story_5028_50280301_61_dialog_content = "……",
  ui_story_5028_50280301_62_dialog_content = "......囉？",
  ui_story_5028_50280301_63_dialog_content = "妳這個問題很難回答......",
  ui_story_5028_50280301_64_dialog_content = "就當我沒說過吧。",
  ui_story_5028_50280301_65_dialog_content = "既然妳是專家，那麼這裡估計恐怕大概也只能按妳的方法來了。",
  ui_story_5028_50280301_66_dialog_content = "放心吧！讓你看看神奇動物研究專家菲雅的高明手法！",
  ui_story_5028_50280301_67_dialog_content = "囉～",
  ui_story_5028_50280301_68_dialog_content = "呼——呼——哈啾！",
  ui_story_5028_50280301_69_dialog_content = "這個消除氣味藥劑的味道，好像有點熟悉呀。",
  ui_story_5028_50280301_70_dialog_content = "不過驅蟲效果倒是挺好的，雖然躲在草叢裡，但是周圍的小蟲子都在躲著我們。",
  ui_story_5028_50280301_71_dialog_content = "囉～",
  ui_story_5028_50280301_72_dialog_content = "嘿嘿，那個可是用凱羅的分泌物做的喔～很有效吧！",
  ui_story_5028_50280301_73_dialog_content = "噗——！！",
  ui_story_5028_50280301_74_dialog_content = "妳怎麼不早說！",
  ui_story_5028_50280301_75_dialog_content = "我現在感覺渾身發癢，這東西該不會有毒吧。",
  ui_story_5028_50280301_76_dialog_content = "不會的不會的，我身上也塗了很多嘛。",
  ui_story_5028_50280301_77_dialog_content = "你看，這東西黏糊糊的非常保溼，對皮膚也有很多好處喔。",
  ui_story_5028_50280301_78_dialog_content = "我平時也會用凱羅的分泌物做一些護膚品喔。",
  ui_story_5028_50280301_78X_dialog_content = "所以即使整天在到處調查，皮膚的狀態也非常棒喔。",
  ui_story_5028_50280301_79_dialog_content = "囉囉～",
  ui_story_5028_50280301_80_dialog_content = "噓......！有動靜。",
  ui_story_5028_50280301_81_dialog_content = "是蒼獅龍來了嗎？",
  ui_story_5028_50280301_82_dialog_content = "嗯，牠們會在馬上生產的時候儘量壓低發出的聲音，並飛到認為安全的地方。",
  ui_story_5028_50280301_83_dialog_content = "但我還是能聽到，這扇動空氣的聲音一定屬於牠......",
  ui_story_5028_50280301_84_dialog_content = "<color=#e8d9bb>沙沙......</color>",
  ui_story_5028_50280301_85_dialog_content = "嗯，我雖然沒聽過蒼獅龍搧動翅膀的聲音，但也有可能是那邊草叢裡的聲音吧？",
  ui_story_5028_50280301_86_dialog_content = "真討厭，可能又是什麼愛搗亂的小動物吧。",
  ui_story_5028_50280301_87_dialog_content = "凱羅，去幫我趕走牠們！",
  ui_story_5028_50280301_88_dialog_content = "囉！",
  ui_story_5028_50280301_89_dialog_content = "PlayerName，你真的聽不到嗎？這個像是撥動琴弦一樣的聲音。",
  ui_story_5028_50280301_90_dialog_content = "<color=#e8d9bb>沙沙，沙沙，沙沙。</color>",
  ui_story_5028_50280301_91_dialog_content = "......囉！",
  ui_story_5028_50280301_92_dialog_content = "什麼琴弦，聽不見呀，只有凱羅和草叢的聲音。",
  ui_story_5028_50280301_93_dialog_content = "囉！囉囉！",
  ui_story_5028_50280301_94_dialog_content = "笨死了，讓我拔根頭髮彈給你聽聽！",
  ui_story_5028_50280301_95_dialog_content = "<size=45>囉——！！</size>",
  ui_story_5028_50280301_96_dialog_content = "凱羅好吵！",
  ui_story_5028_50280301_97_dialog_content = "吼——！！",
  ui_story_5028_50280301_98_dialog_content = "暗鬼！",
  ui_story_5028_50280301_99_dialog_content = "怎麼偏偏這種時候......如果被快生產的蒼獅龍發現，我們一個都跑不掉啦！",
  ui_story_5028_50280301_100_dialog_content = "PlayerName，我們速戰速決！",
  ui_story_5028_50280301_101_dialog_content = "明白了，上吧！",
  ui_story_5028_50280301_102_dialog_content = "囉！！",
  ui_story_5028_50280302_1_dialog_content = "總算收拾掉了。",
  ui_story_5028_50280302_2_dialog_content = "明明都用了除味藥劑，照理說暗鬼不會找上門呀。",
  ui_story_5028_50280302_3_dialog_content = "哎，PlayerName你莫非是某種吸引暗鬼的裝置嗎？",
  ui_story_5028_50280302_4_dialog_content = "在暗鬼眼裡，你是不是就像是燈塔一樣光彩奪目又誘人？",
  ui_story_5028_50280302_5_dialog_content = "讓牠們都像是飛蛾撲火一樣向你衝過來。",
  ui_story_5028_50280302_6_dialog_content = "仔細想想可能真的是這樣。",
  ui_story_5028_50280302_7_dialog_content = "海邊、雪山、沙漠、遺跡，不管我去哪裡都會有暗鬼突然出現。",
  ui_story_5028_50280302_8_dialog_content = "就好像有名的偵探出場時都會伴隨著離奇命案一樣。",
  ui_story_5028_50280302_9_dialog_content = "<size=30>師父果然沒安好心......</size>",
  ui_story_5028_50280302_10_dialog_content = "嗯？",
  ui_story_5028_50280302_11_dialog_content = "算了！不管那個了，還好蒼獅龍沒發現我們，我估計牠馬上就要生產了。",
  ui_story_5028_50280302_12_dialog_content = "牠在下降，我們快點躲好。",
  ui_story_5028_50280302_13_dialog_content = "能看到牠了！但是從那個高度掉下來的話，蛋肯定會碎掉吧？",
  ui_story_5028_50280302_14_dialog_content = "這到底是什麼古怪的習性啊？這樣生孩子不滅絕才怪吧！",
  ui_story_5028_50280302_15_dialog_content = "艾斯特拉的所有動物學家也有著和你一樣的疑問。",
  ui_story_5028_50280302_16_dialog_content = "但神奇動物就是這樣，牠們的習性可不會管到底合不合理喔！",
  ui_story_5028_50280302_17_dialog_content = "所以說現在......這樣下去不行，必須想個辦法。",
  ui_story_5028_50280302_18_dialog_content = "囉！",
  ui_story_5028_50280302_19_dialog_content = "菲雅？妳要幹什麼？",
  ui_story_5028_50280302_20_dialog_content = "我......我要爬上這棵樹去接蛋！",
  ui_story_5028_50280302_21_dialog_content = "別傻了！雖然這樹非常高，但就算爬到頂上也根本不行的！",
  ui_story_5028_50280302_22_dialog_content = "而且妳爬上去也沒辦法用網兜接住蛋啊！",
  ui_story_5028_50280302_23_dialog_content = "唉，到底要怎麼辦，我們這樣根本幫不上牠。",
  ui_story_5028_50280302_24_dialog_content = "牠們十幾年才會生產一次，已經是十分稀少瀕危的種群了。",
  ui_story_5028_50280302_25_dialog_content = "明明從師父那裡得到了確切的情報卻沒能保護牠，師父......",
  ui_story_5028_50280302_26_dialog_content = "囉......",
  ui_story_5028_50280302_27_dialog_content = "有了！",
  ui_story_5028_50280302_28_dialog_content = "哎？難道你說的是？",
  ui_story_5028_50280302_29_dialog_content = "真的可以嗎？",
  ui_story_5028_50280302_30_dialog_content = "沒辦法，只能試試看了！",
  ui_story_5028_50280302_31_dialog_content = "PlayerName，謝謝你願意讓臨空者號幫我！",
  ui_story_5028_50280302_32_dialog_content = "總不可能眼睜睜看著一條生命還沒睜開眼見到這個世界就離去吧！",
  ui_story_5028_50280302_33_dialog_content = "雖然不知道蒼獅龍會不會喜歡臨空者號，但試試看！",
  ui_story_5028_50280302_34_dialog_content = "嗷吼——",
  ui_story_5028_50280302_35_dialog_content = "PlayerName！蒼獅龍好像對臨空者號非常感興趣呢！",
  ui_story_5028_50280302_36_dialog_content = "似乎把臨空者號當成朋友一樣，在不斷靠近臨空者號。",
  ui_story_5028_50280302_37_dialog_content = "好，還差一點，再接近一點......我就可以用網兜......",
  ui_story_5028_50280302_38_dialog_content = "（等等，牠腳腕上的是什麼？算了，沒時間管那麼多了。）",
  ui_story_5028_50280302_39_dialog_content = "囉！囉！",
  ui_story_5028_50280302_40_dialog_content = "嗷——",
  ui_story_5028_50280302_41_dialog_content = "菲雅！蒼獅龍貼過來了！",
  ui_story_5028_50280302_42_dialog_content = "知道了，請讓距離再拉近一些，剩下的交給我和凱羅吧！",
  ui_story_5028_50280302_43_dialog_content = "三。",
  ui_story_5028_50280302_44_dialog_content = "二。",
  ui_story_5028_50280302_45_dialog_content = "一。",
  ui_story_5028_50280302_46_dialog_content = "菲雅！",
  ui_story_5028_50280302_47_dialog_content = "囉！！",
  ui_story_5028_50280302_48_dialog_content = "！",
  ui_story_5028_50280302_49_dialog_content = "成功了！！",
  ui_story_5028_50280302_50_dialog_content = "好亮，牠在我懷裡孵化了？",
  ui_story_5028_50280302_51_dialog_content = "啵......",
  ui_story_5028_50280302_52_dialog_content = "啵嗶？",
  ui_story_5028_50280302_53_dialog_content = "囉囉～",
  ui_story_5028_50280302_54_dialog_content = "好，好可愛！",
  ui_story_5028_50280302_55_dialog_content = "牠看起來小小的，居然能夠長到那麼大嗎？",
  ui_story_5028_50280302_56_dialog_content = "太不可思議了，不愧是被稱為<color=#FFB400>珍奇物種</color>的存在......蒼獅龍。",
  ui_story_5028_50280302_57_dialog_content = "菲雅！情況順利嗎？",
  ui_story_5028_50280302_58_dialog_content = "嗯！多虧PlayerName和臨空者號，小蒼獅龍已經順利孵化了呢。",
  ui_story_5028_50280302_59_dialog_content = "囉～",
  ui_story_5028_50280302_60_dialog_content = "也要謝謝凱羅呢～",
  ui_story_5028_50280302_61_dialog_content = "囉囉～",
  ui_story_5028_50280302_62_dialog_content = "啵嗶～！",
  ui_story_5028_50280302_63_dialog_content = "慶祝的話等一下再說吧！",
  ui_story_5028_50280302_64_dialog_content = "現在蒼獅龍好像緊緊纏著臨空者號不放，我們沒法降落了！",
  ui_story_5028_50280302_65_dialog_content = "啊，我忘記說了。",
  ui_story_5028_50280302_65X_dialog_content = "牠們對已經存活的個體會產生非常強的保護欲，很可能是認為我們偷了幼崽吧！",
  ui_story_5028_50280302_66_dialog_content = "什麼！？那我們豈不是死定了？？",
  ui_story_5028_50280302_67_dialog_content = "不對，這個叫聲並不是充滿敵意的。",
  ui_story_5028_50280302_68_dialog_content = "聽牠的叫聲，該不會是愛上臨空者號了吧？",
  ui_story_5028_50280302_69_dialog_content = "妳說什麼！？",
  ui_story_5028_50280302_70_dialog_content = "......這裡也沒有PlayerName。",
  ui_story_5028_50280302_71_dialog_content = "嗯？妳是雷文頓吧？怎麼在這裡亂晃？",
  ui_story_5028_50280302_72_dialog_content = "哦，斯莫奇。",
  ui_story_5028_50280302_73_dialog_content = "我在找空裔。",
  ui_story_5028_50280302_74_dialog_content = "我和PlayerName之前在這附近玩棒球。",
  ui_story_5028_50280302_75_dialog_content = "玩著玩著他就不見了，只留下一封信，我懷疑他被綁架了。",
  ui_story_5028_50280302_76_dialog_content = "嗯？",
  ui_story_5028_50280302_77_dialog_content = "妳說什麼？PlayerName那小子被綁架了？",
  ui_story_5028_50280302_78_dialog_content = "妳說的信呢？",
  ui_story_5028_50280302_79_dialog_content = "在過來的路上揍暗鬼的時候弄丟了。",
  ui_story_5028_50280302_80_dialog_content = "真有意思。",
  ui_story_5028_50280302_81_dialog_content = "我很好奇，這次又是誰劫走了那個倒楣蛋空裔。",
  ui_story_5028_50280302_82_dialog_content = "幫我找找空裔吧。",
  ui_story_5028_50280302_83_dialog_content = "人丟了，薇絲和老克會兇我的。",
  ui_story_5028_50280302_84_dialog_content = "嗯，反正手頭也沒什麼事，就一起找找那個倒楣蛋吧。",
  ui_story_5028_50280401_1_dialog_content = "試煉：葡萄園的危機",
  ui_story_5028_50280401_2_dialog_content = "呼！呼！哈！",
  ui_story_5028_50280401_3_dialog_content = "我說，我說菲雅妳走慢點。",
  ui_story_5028_50280401_4_dialog_content = "我們究竟要去哪啊？",
  ui_story_5028_50280401_5_dialog_content = "這四周都種著葡萄，難道我們這次要給哪條葡萄龍接生嗎？",
  ui_story_5028_50280401_6_dialog_content = "囉。",
  ui_story_5028_50280401_7_dialog_content = "噓，菲雅在整理對蒼獅龍幼崽的觀察筆記呢。",
  ui_story_5028_50280401_8_dialog_content = "想不到牠成長得那麼快，一下子就比凱羅還大，能夠自己獨立生存了。",
  ui_story_5028_50280401_9_dialog_content = "唉，沒想到牠馬上就去尋找屬於自己的棲息地了。",
  ui_story_5028_50280401_9X_dialog_content = "我還沒看夠牠幼崽時期可愛的樣子呢。",
  ui_story_5028_50280401_10_dialog_content = "我們兩個能從蒼獅龍的糾纏下偷偷溜走已經謝天謝地了好吧！",
  ui_story_5028_50280401_11_dialog_content = "我實在走不動了，休息一下吧。",
  ui_story_5028_50280401_12_dialog_content = "欸～這麼快就要休息了呀？我們馬上就要到委託地點了喔。",
  ui_story_5028_50280401_13_dialog_content = "真是拿PlayerName沒辦法，來，快點張嘴把這個喝了～",
  ui_story_5028_50280401_14_dialog_content = "妳，妳要幹嘛，我才不喝！",
  ui_story_5028_50280401_15_dialog_content = "來～乖乖的～",
  ui_story_5028_50280401_16_dialog_content = "別過來！",
  ui_story_5028_50280401_17_dialog_content = "凱羅也來按住PlayerName～",
  ui_story_5028_50280401_18_dialog_content = "囉囉～",
  ui_story_5028_50280401_19_dialog_content = "唔！咕嚕咕嚕！",
  ui_story_5028_50280401_20_dialog_content = "好辣！不對......嘴巴里又有一股奶香，等一下，又變得涼颼颼了！",
  ui_story_5028_50280401_21_dialog_content = "妳究竟給我喝了什麼啊！",
  ui_story_5028_50280401_22_dialog_content = "這個可是用火凜牛的乳汁，再配上栗栗草的根莖汁製成的菲雅特調精力飲料喔。",
  ui_story_5028_50280401_23_dialog_content = "菲雅還特地加了北境才有的霜薄荷調味呢，所以才會感覺涼颼颼的，非常提神。",
  ui_story_5028_50280401_24_dialog_content = "對了，我是把這些餵給凱羅之後讓牠在肚子裡調配的～要比手工調合更充分喔。",
  ui_story_5028_50280401_25_dialog_content = "只要喝了這個，PlayerName一定就能立刻變得生龍活虎啦！",
  ui_story_5028_50280401_25X_dialog_content = "這些材料可是很珍貴的唷。",
  ui_story_5028_50280401_26_dialog_content = "囉～",
  ui_story_5028_50280401_27_dialog_content = "嘔！凱羅你為什麼要幫她做這種事！",
  ui_story_5028_50280401_28_dialog_content = "囉？",
  ui_story_5028_50280401_29_dialog_content = "還有妳！菲雅！",
  ui_story_5028_50280401_30_dialog_content = "咦？",
  ui_story_5028_50280401_31_dialog_content = "妳私自製藥還利用我進行實驗，這可是嚴重的違法行為喔！",
  ui_story_5028_50280401_32_dialog_content = "什，什麼？怎麼可能啦！",
  ui_story_5028_50280401_33_dialog_content = "你，你不許告訴別人這藥的事喔！菲雅可不想這麼小年紀就被抓去監獄......",
  ui_story_5028_50280401_34_dialog_content = "要是不想的話，以後就不要突然餵我喝怪東西了。",
  ui_story_5028_50280401_35_dialog_content = "知道啦，菲雅明明是好心......",
  ui_story_5028_50280401_36_dialog_content = "嗯？不過這東西好像真的挺有效的。",
  ui_story_5028_50280401_37_dialog_content = "我感覺體力已經恢復八成了。",
  ui_story_5028_50280401_38_dialog_content = "效果果然很好嗎！等我記一下這次的配方。",
  ui_story_5028_50280401_39_dialog_content = "喂！？妳是第一次給別人喝嗎？我可是僅存的空裔欸！",
  ui_story_5028_50280401_40_dialog_content = "我要是在這種地方因為吃了奇奇怪怪的東西而倒下的話——！",
  ui_story_5028_50280401_41_dialog_content = "簡直就像是被腰斬的小說里的主角一樣可悲啊！",
  ui_story_5028_50280401_42_dialog_content = "啊哈哈，怎麼可能是第一次，那個，身體感覺怎麼樣？",
  ui_story_5028_50280401_42X_dialog_content = "要不要抱著凱羅再吸一點試試？",
  ui_story_5028_50280401_43_dialog_content = "囉！？",
  ui_story_5028_50280401_44_dialog_content = "絕對不要，妳自己留著喝吧！",
  ui_story_5028_50280401_45_dialog_content = "妳休想再靠近我給我餵什麼奇怪的東西！",
  ui_story_5028_50280401_46_dialog_content = "堂堂空裔居然害怕精力飲料欸，PlayerName好丟人喔～",
  ui_story_5028_50280401_47_dialog_content = "我要不是之後還要妳幫忙救臨空者號，現在就先教訓妳一頓。",
  ui_story_5028_50280401_48_dialog_content = "嘿嘿，你放心吧。我們不是已經安全從蒼獅龍手底下逃出來了嗎？",
  ui_story_5028_50280401_49_dialog_content = "牠雖然迷戀臨空者號，但也不會做出什麼過分的事。",
  ui_story_5028_50280401_50_dialog_content = "說得輕鬆，臨空者號要被迫和牠一直在我們頭上的高空飛來飛去還不算過分嗎？",
  ui_story_5028_50280401_51_dialog_content = "咳咳。",
  ui_story_5028_50280401_52_dialog_content = "嗚哇！！",
  ui_story_5028_50280401_53_dialog_content = "誰，誰啊，暗鬼嗎，野獸嗎？妖怪嗎？",
  ui_story_5028_50280401_54_dialog_content = "抱歉啦......老夫可是光靈啊。",
  ui_story_5028_50280401_55_dialog_content = "想必這位就是維克先生的高徒吧？",
  ui_story_5028_50280401_56_dialog_content = "維克？",
  ui_story_5028_50280401_57_dialog_content = "（竟然被慈眉善目的老伯伯嚇了一跳。這樣可不行呀菲雅，打起精神來！）",
  ui_story_5028_50280401_58_dialog_content = "咳，您好老伯，我就是維克的徒弟，神奇動物專家菲雅。",
  ui_story_5028_50280401_59_dialog_content = "菲雅妳不是還在修行中嗎？",
  ui_story_5028_50280401_60_dialog_content = "修行中的專家也是專家啦！",
  ui_story_5028_50280401_61_dialog_content = "哦哦！抱歉抱歉，老夫有眼不識泰山了。",
  ui_story_5028_50280401_62_dialog_content = "那個，師父他——",
  ui_story_5028_50280401_63_dialog_content = "其實老夫以前是一位白夜城衛兵啊，我可是參加過好多次戰爭。",
  ui_story_5028_50280401_64_dialog_content = "你看看老夫這膝蓋，就是當初與舒瓦茲殿下共同迎戰暗鬼時所留下的傷。",
  ui_story_5028_50280401_65_dialog_content = "老伯您——",
  ui_story_5028_50280401_66_dialog_content = "唉！可惜老夫始終有個當小說家的夢想，後來因為在工作時間偷偷寫小說。",
  ui_story_5028_50280401_67_dialog_content = "被長官發現之後提前退休，之後就被安排到這裡種葡萄了。",
  ui_story_5028_50280401_68_dialog_content = "請聽我——",
  ui_story_5028_50280401_69_dialog_content = "老夫可是寫過很多出名的書喔！",
  ui_story_5028_50280401_69X_dialog_content = "比如《騎士已死》、《審判官扮家家酒》、《無面戰士VICE》等等等等。",
  ui_story_5028_50280401_70_dialog_content = "大叔！拜託先把委託的事給我說清楚！",
  ui_story_5028_50280401_71_dialog_content = "哦哦哦哦哦！委託是吧，抱歉抱歉，老夫馬上向兩位講述詳情。",
  ui_story_5028_50280401_72_dialog_content = "可惡，可惡可惡可惡，臭師父。",
  ui_story_5028_50280401_73_dialog_content = "居然用一隻破信鴿就讓我半夜幫那個笨蛋老伯看守葡萄棚！",
  ui_story_5028_50280401_74_dialog_content = "菲雅以後可是堂堂神奇動物專家，又不是抓小偷的治安員！",
  ui_story_5028_50280401_75_dialog_content = "喂，不要睡啦。輪班到你啦。",
  ui_story_5028_50280401_76_dialog_content = "怎麼睡得流口水了。",
  ui_story_5028_50280401_77_dialog_content = "起——來——啦——！",
  ui_story_5028_50280401_78_dialog_content = "唔！？有，有小偷嗎？",
  ui_story_5028_50280401_79_dialog_content = "是是，有小偷把你的臨空者號從你頭上的雲朵中間偷走了喔。",
  ui_story_5028_50280401_80_dialog_content = "啊？真的？",
  ui_story_5028_50280401_81_dialog_content = "假的！輪到你值班啦，菲雅要睏死了。",
  ui_story_5028_50280401_82_dialog_content = "<color=#e8d9bb>過了很久</color>",
  ui_story_5028_50280401_83_dialog_content = "......呼。",
  ui_story_5028_50280401_84_dialog_content = "嗨～",
  ui_story_5028_50280401_85_dialog_content = "嗯......嗯嗯？",
  ui_story_5028_50280401_86_dialog_content = "嗨～咕嚕咕嚕。",
  ui_story_5028_50280401_87_dialog_content = "菲雅！！",
  ui_story_5028_50280401_88_dialog_content = "嗚，嗚喵？",
  ui_story_5028_50280401_89_dialog_content = "囉嗚......？",
  ui_story_5028_50280401_90_dialog_content = "快起來，別睡了！",
  ui_story_5028_50280401_91_dialog_content = "葡萄都被偷吃光了！！",
  ui_story_5028_50280401_92_dialog_content = "什喵！？",
  ui_story_5028_50280401_93_dialog_content = "犯人往那邊去了！我們快追！",
  ui_story_5028_50280401_94_dialog_content = "這傢伙也太狡猾了！",
  ui_story_5028_50280401_95_dialog_content = "一轉眼就鑽進森林裡不見了。",
  ui_story_5028_50280401_96_dialog_content = "沒辦法了，根本追不上。",
  ui_story_5028_50280401_97_dialog_content = "說不定犯人有同夥，我們還是趕快回去看守葡萄園吧。",
  ui_story_5028_50280401_98_dialog_content = "噗，哈哈哈——",
  ui_story_5028_50280401_99_dialog_content = "菲雅？妳沒事吧，雖然沒抓到犯人，也不用著急到突然傻笑吧。",
  ui_story_5028_50280401_100_dialog_content = "不，不是，我剛剛突然想到一個冷笑話。",
  ui_story_5028_50280401_101_dialog_content = "啊？",
  ui_story_5028_50280401_102_dialog_content = "有人說：「如果說到艷陽高照的紅油沙漠深處，就一定會遇到沙蟲的話......」",
  ui_story_5028_50280401_103_dialog_content = "那下一句一定是：「那麼說到夜深人靜鑽進樹林裡的空裔就一定會遇到......」",
  ui_story_5028_50280401_104_dialog_content = "吼——！！",
  ui_story_5028_50280401_105_dialog_content = "什麼破笑話啊！？又冷又無聊還會招來暗鬼，快跑！！",
  ui_story_5028_50280401_106_dialog_content = "嗚啊！！怎麼成真了啊，臭空裔，臭空裔跑得太快了吧！！",
  ui_story_5028_50280401_107_dialog_content = "等等菲雅啊！",
  ui_story_5028_50280402_1_dialog_content = "呼，呼！",
  ui_story_5028_50280402_2_dialog_content = "這群臭暗鬼，怎麼窮追不捨的。",
  ui_story_5028_50280402_3_dialog_content = "嘎——！！",
  ui_story_5028_50280402_4_dialog_content = "小心！",
  ui_story_5028_50280402_5_dialog_content = "呀！",
  ui_story_5028_50280402_6_dialog_content = "我，我沒事，謝謝你PlayerName。",
  ui_story_5028_50280402_7_dialog_content = "不好了！筆記被暗鬼打飛了。",
  ui_story_5028_50280402_8_dialog_content = "菲雅！妳趁更多暗鬼追來之前趕快去撿筆記！這裡交給我。",
  ui_story_5028_50280402_9_dialog_content = "可是……",
  ui_story_5028_50280402_10_dialog_content = "快點！",
  ui_story_5028_50280402_11_dialog_content = "嘎——！",
  ui_story_5028_50280402_12_dialog_content = "這暗鬼直接就去追菲雅了，完全不把我放在眼裡嗎。",
  ui_story_5028_50280402_13_dialog_content = "（找准機會，只要能瞄準暗鬼身上的軟肋。）",
  ui_story_5028_50280402_14_dialog_content = "嘎——！",
  ui_story_5028_50280402_15_dialog_content = "（不行，再拖下去菲雅被包圍就危險了！不能等機會了！）",
  ui_story_5028_50280402_16_dialog_content = "嘿！！",
  ui_story_5028_50280402_17_dialog_content = "沒想到我會撞過來吧，你們這群可惡的暗鬼。",
  ui_story_5028_50280402_18_dialog_content = "疼疼疼，怎麼跟石頭一樣硬。",
  ui_story_5028_50280402_19_dialog_content = "嘎！",
  ui_story_5028_50280402_20_dialog_content = "嗚啊！果然還是太魯莽了，得趕快帶著菲雅逃命了。",
  ui_story_5028_50280402_21_dialog_content = "我拿到了！PlayerName，我們快跑！",
  ui_story_5028_50280402_22_dialog_content = "哈——終於甩開了。",
  ui_story_5028_50280402_23_dialog_content = "PlayerName你沒事吧！手臂怎麼都腫起來了？",
  ui_story_5028_50280402_24_dialog_content = "沒事沒事，是我撞暗鬼的時候弄的，那傢伙也太硬了。",
  ui_story_5028_50280402_25_dialog_content = "都怪我不小心，嗚......對不起，我馬上給你塗藥！",
  ui_story_5028_50280402_26_dialog_content = "沒關係的，只要能把菲雅師父的遺物拿回來就好了。",
  ui_story_5028_50280402_27_dialog_content = "欸，遺物？",
  ui_story_5028_50280402_28_dialog_content = "啊，那個那個，是說裝哭時候的事吧。",
  ui_story_5028_50280402_29_dialog_content = "抱歉！其實啊，師父他還好好地活著呢。",
  ui_story_5028_50280402_30_dialog_content = "啊？",
  ui_story_5028_50280402_31_dialog_content = "藥塗好了，也包紮好了，應該很快會消腫的。",
  ui_story_5028_50280402_32_dialog_content = "<size=30>總之......對不起。</size>",
  ui_story_5028_50280402_33_dialog_content = "什麼？",
  ui_story_5028_50280402_34_dialog_content = "<size=30>我說，對不起。</size>",
  ui_story_5028_50280402_35_dialog_content = "菲雅妳聲音好小，我聽不清妳在說什麼。",
  ui_story_5028_50280402_36_dialog_content = "呼……",
  ui_story_5028_50280402_37_dialog_content = "<size=45>對不起對不起對不起！菲雅在道歉啦！！！</size>",
  ui_story_5028_50280402_38_dialog_content = "嗚哇！怎，怎麼突然這樣？",
  ui_story_5028_50280402_39_dialog_content = "對不起，是菲雅說謊了，菲雅會道歉，會認真檢討。",
  ui_story_5028_50280402_40_dialog_content = "但是，那個臭師父就只會給我挖坑和使喚我。",
  ui_story_5028_50280402_41_dialog_content = "完全不會像PlayerName這樣真誠又熱情地幫助我。",
  ui_story_5028_50280402_42_dialog_content = "菲雅當時一時著急，就說了謊話，但菲雅真的很想交一個朋友，真的！",
  ui_story_5028_50280402_43_dialog_content = "希望你能原諒菲雅......",
  ui_story_5028_50280402_44_dialog_content = "不過，臭師父就轟地一下原地爆炸算了！哼！",
  ui_story_5028_50280402_45_dialog_content = "哈啾——！",
  ui_story_5028_50280402_46_dialog_content = "怎麼好像又有人在惦記我了，會是哪個老朋友呢。",
  ui_story_5028_50280402_47_dialog_content = "有點不妙的預感啊。",
  ui_story_5028_50280402_48_dialog_content = "唉，我知道了，雖然當時就察覺到妳可能在裝哭，但也沒辦法置之不理啊。",
  ui_story_5028_50280402_49_dialog_content = "不過菲雅，妳這樣的說法也有些過分了吧。",
  ui_story_5028_50280402_50_dialog_content = "不管怎麼樣都不可以對人說這種話，就算開玩笑也不可以。",
  ui_story_5028_50280402_51_dialog_content = "這本筆記雖然字跡潦草，但是內容非常豐富，可以看出來是主人的心血。",
  ui_story_5028_50280402_52_dialog_content = "能把這麼重要的筆記交給妳，師父肯定也非常器重妳吧。",
  ui_story_5028_50280402_53_dialog_content = "唔，好，好啦......大概你說得對。",
  ui_story_5028_50280402_54_dialog_content = "即使是對臭師父，說什麼去死也的確很過分，菲雅也會對著遠方的師父道歉。",
  ui_story_5028_50280402_55_dialog_content = "菲雅保證以後不會再說了！所以......",
  ui_story_5028_50280402_56_dialog_content = "所以可以別一直摸菲雅的頭了嗎，雖然我們是朋友也很害羞欸，凱羅還看著呢！",
  ui_story_5028_50280402_57_dialog_content = "啊，抱歉抱歉，這個身高差，不自覺就......",
  ui_story_5028_50280402_58_dialog_content = "嗯？你是在暗示菲雅很矮嗎？",
  ui_story_5028_50280402_59_dialog_content = "咳咳，那個，總之，關於剛剛偷葡萄的賊，妳有什麼線索嗎？",
  ui_story_5028_50280402_60_dialog_content = "唔，如果我沒看錯的話，那種應該是一種叫<color=#FFB400>「比卡」</color>的神奇動物。",
  ui_story_5028_50280402_61_dialog_content = "筆記上說牠們喜歡球形的食物，而且不管多大都能一口吞下。",
  ui_story_5028_50280402_62_dialog_content = "而且牠們的身體非常有彈性，甚至可以隨著吞下的食物變大變小。",
  ui_story_5028_50280402_63_dialog_content = "雖然牠們腳力很強，逃脫速度飛快。",
  ui_story_5028_50280402_64_dialog_content = "但牠們實際上不怎麼聰明，甚至可以說是比較笨的神奇動物。",
  ui_story_5028_50280402_65_dialog_content = "球形的食物嗎？讓我想想。",
  ui_story_5028_50280402_66_dialog_content = "<size=30>這樣真的可以嗎？</size>",
  ui_story_5028_50280402_67_dialog_content = "<size=30>就找來了個籠子，在裡面放了一個大西瓜？雖然這西瓜看起來很好吃</size>。",
  ui_story_5028_50280402_68_dialog_content = "<size=30>比卡真的會那麼容易上當嗎？</size>",
  ui_story_5028_50280402_69_dialog_content = "<size=30>放心好了，如果筆記的記載屬實，那麼比卡根本不可能抗拒這麼大的球形食物。</size>",
  ui_story_5028_50280402_70_dialog_content = "<size=30>就相信師父的記載，也相信我的判斷吧。</size>",
  ui_story_5028_50280402_71_dialog_content = "<size=30>好吧，好像有東西接近了。</size>",
  ui_story_5028_50280402_72_dialog_content = "嗨——嗨——",
  ui_story_5028_50280402_73_dialog_content = "嗨？",
  ui_story_5028_50280402_74_dialog_content = "嗨～～",
  ui_story_5028_50280402_75_dialog_content = "吃下去了！",
  ui_story_5028_50280402_76_dialog_content = "囉！",
  ui_story_5028_50280402_77_dialog_content = "居然真的吃了，這孩子真是不太聰明啊。",
  ui_story_5028_50280402_78_dialog_content = "嗨！？嗨！？",
  ui_story_5028_50280402_79_dialog_content = "別怕別怕，我不是壞人。",
  ui_story_5028_50280402_80_dialog_content = "嗨？",
  ui_story_5028_50280402_81_dialog_content = "啊，就是能不能麻煩你不要來偷吃彭伯伯種的葡萄了？",
  ui_story_5028_50280402_82_dialog_content = "嗨嗨？",
  ui_story_5028_50280402_83_dialog_content = "我來吧。",
  ui_story_5028_50280402_84_dialog_content = "別害怕，我們不會傷害你的。",
  ui_story_5028_50280402_85_dialog_content = "嗨......？",
  ui_story_5028_50280402_86_dialog_content = "PlayerName，麻煩你把籠子打開吧，牠不會逃走的。",
  ui_story_5028_50280402_87_dialog_content = "真的沒問題嗎？那我開了喔。",
  ui_story_5028_50280402_88_dialog_content = "嗨......",
  ui_story_5028_50280402_89_dialog_content = "什麼？西瓜很好吃？這種時候還在關心這個嗎？",
  ui_story_5028_50280402_90_dialog_content = "嗨嗨！",
  ui_story_5028_50280402_91_dialog_content = "牠說牠是從一個很可怕的怪物手中逃出來的。",
  ui_story_5028_50280402_92_dialog_content = "一定嚇壞了吧，真可憐。就算是這樣也不能跑到這裡偷吃葡萄喔。",
  ui_story_5028_50280402_93_dialog_content = "菲雅，妳難道能......",
  ui_story_5028_50280402_94_dialog_content = "嗨～",
  ui_story_5028_50280402_95_dialog_content = "哦？跟著我很安全？還能吃很多西瓜？",
  ui_story_5028_50280402_96_dialog_content = "你的嘴可真甜呀。",
  ui_story_5028_50280402_97_dialog_content = "PlayerName，我們收養牠吧，只有這樣牠才不會繼續破壞農作物，也不會被別的動物欺負。",
  ui_story_5028_50280402_98_dialog_content = "好的，既然妳都這麼說了，我沒意見。",
  ui_story_5028_50280402_99_dialog_content = "凱羅一定也願意讓牠和我們一起旅行吧？",
  ui_story_5028_50280402_100_dialog_content = "囉～",
  ui_story_5028_50280402_101_dialog_content = "好，那麼牠也是我們的新夥伴啦！",
  ui_story_5028_50280402_102_dialog_content = "我把這邊貼好了。",
  ui_story_5028_50280402_103_dialog_content = "我這邊也貼好了。",
  ui_story_5028_50280402_104_dialog_content = "雖然尋人啟事八成沒什麼用，但運氣好了也能得到些情報。",
  ui_story_5028_50280402_105_dialog_content = "誰？",
  ui_story_5028_50280402_106_dialog_content = "呵呵呵，我可都看到了喔，斯莫奇。",
  ui_story_5028_50280402_107_dialog_content = "沒想到妳竟然墮落到到處貼小廣告了啊。",
  ui_story_5028_50280402_108_dialog_content = "而且還和這位啟光的小朋友在一起打零工。",
  ui_story_5028_50280402_109_dialog_content = "很缺錢的話，要不要我借妳一點？",
  ui_story_5028_50280402_110_dialog_content = "利息的話，可以給妳一個「感·情·價」。",
  ui_story_5028_50280402_111_dialog_content = "嘖，話真多。",
  ui_story_5028_50280402_112_dialog_content = "喂，雷文頓，你們啟光的槍是不是都沒有這傢伙的嘴巴快？",
  ui_story_5028_50280402_113_dialog_content = "我不用槍，不清楚。",
  ui_story_5028_50280402_114_dialog_content = "是PlayerName丟了，斯莫奇在幫我找人。",
  ui_story_5028_50280402_115_dialog_content = "哦？該說稀奇還是不稀奇呢，意外但又覺得合情合理了。",
  ui_story_5028_50280402_116_dialog_content = "不過既然妳要去找PlayerName，我也要一起，絕對不會讓妳先得逞的。",
  ui_story_5028_50280402_117_dialog_content = "妳別來。",
  ui_story_5028_50280402_118_dialog_content = "建議妳先找醫生看看這個爭強好勝的毛病，治療幾個月再說。",
  ui_story_5028_50280402_119_dialog_content = "妳只要一跟來就肯定有一堆麻煩事，而且妳和空裔也沒那麼熟吧？",
  ui_story_5028_50280402_120_dialog_content = "難道妳還對空裔有所企圖？想拉他進妳的狗屁後援團嗎？",
  ui_story_5028_50280402_121_dialog_content = "這點妳大可放心，我所企圖的另有他人。",
  ui_story_5028_50280402_122_dialog_content = "呵，也不知道是誰這麼「幸運」又「幸福」啊。",
  ui_story_5028_50280402_123_dialog_content = "唉，我去垃圾桶後面找找PlayerName。",
  ui_story_5028_50280501_1_dialog_content = "試煉：海岸邊的祕密",
  ui_story_5028_50280501_2_dialog_content = "這熱辣又刺眼的驕陽。",
  ui_story_5028_50280501_3_dialog_content = "潮濕又充滿活力的海風。",
  ui_story_5028_50280501_4_dialog_content = "熙熙攘攘的人群！",
  ui_story_5028_50280501_5_dialog_content = "沒想到，我又回來了！",
  ui_story_5028_50280501_6_dialog_content = "熱死了，人也太多了。",
  ui_story_5028_50280501_7_dialog_content = "囉～",
  ui_story_5028_50280501_8_dialog_content = "果然這個時候，就該來海邊轉轉啊～",
  ui_story_5028_50280501_9_dialog_content = "唉唷！",
  ui_story_5028_50280501_10_dialog_content = "啊，你沒事吧？",
  ui_story_5028_50280501_11_dialog_content = "沒事沒事，謝謝你。",
  ui_story_5028_50280501_12_dialog_content = "嗯？你剛剛是不是在想，如果是個女孩子摔進懷裡就好了？",
  ui_story_5028_50280501_13_dialog_content = "才不是！",
  ui_story_5028_50280501_14_dialog_content = "哦？那你更喜歡剛剛那個壯碩的小哥嗎？",
  ui_story_5028_50280501_15_dialog_content = "也沒有！別鬧了。",
  ui_story_5028_50280501_16_dialog_content = "不過，沒想到妳的那位師父還滿疼愛妳。",
  ui_story_5028_50280501_17_dialog_content = "到海邊來放鬆度假也算是試煉的一環嗎？",
  ui_story_5028_50280501_18_dialog_content = "怎麼可能，那個臭師父怎麼會有這種好心。",
  ui_story_5028_50280501_19_dialog_content = "這裡人也太多了，討厭。他到底派我來幹嘛，也不說清楚。",
  ui_story_5028_50280501_20_dialog_content = "他就只會使喚我給那群小毛球梳毛，剃毛。蒐集好了之後用那些毛換錢。",
  ui_story_5028_50280501_21_dialog_content = "然後他就會拿著那些錢去吃喝玩樂......",
  ui_story_5028_50280501_22_dialog_content = "我還要留在家裡，用穀物給肥肥啾做飼料，給椰寶鹿清理排泄物，被風馳狗牽出去散步。",
  ui_story_5028_50280501_23_dialog_content = "菲雅這樣可愛的女孩子竟然要每天被他當做傭人一樣使喚。",
  ui_story_5028_50280501_24_dialog_content = "甚至連外出執行考察任務，也要被他不靠譜的手記坑慘。",
  ui_story_5028_50280501_25_dialog_content = "囉，囉。",
  ui_story_5028_50280501_26_dialog_content = "唔，那妳為什麼還要讓他做師父呀？",
  ui_story_5028_50280501_27_dialog_content = "而且雖然妳嘴上抱怨不停，但也一直在認真執行他交給妳的工作吧？",
  ui_story_5028_50280501_28_dialog_content = "跟師父的相遇感覺完全是一段孽緣！",
  ui_story_5028_50280501_29_dialog_content = "我從小就非常喜歡一本叫做<color=#FFB400>《千奇百怪的小動物》</color>的書。",
  ui_story_5028_50280501_30_dialog_content = "可以說那本書點亮了我的整個童年。",
  ui_story_5028_50280501_30X_dialog_content = "我也是因為它才與這些小動物開始交流，並深深喜歡上了牠們。",
  ui_story_5028_50280501_31_dialog_content = "但在影鎮，光靈多，神奇動物卻非常稀少。不滿足於此的我便做出一個決定。",
  ui_story_5028_50280501_32_dialog_content = "我要去找這本書的作者，讓他告訴我書中那些無數個日夜讓我魂牽夢縈的神奇動物究竟在何處。",
  ui_story_5028_50280501_33_dialog_content = "我獨自一人告別父母，收拾行李走入了傳聞中作者所居住的山林之中。",
  ui_story_5028_50280501_34_dialog_content = "經過一連數天的搜尋，我一無所獲，正在帳篷前烤栗栗果實吃時一個男性的身影突然出現。",
  ui_story_5028_50280501_35_dialog_content = "他從草叢裡現身，緩緩向我爬來，好像馬上要餓死了一樣。",
  ui_story_5028_50280501_36_dialog_content = "他該不會就是......",
  ui_story_5028_50280501_37_dialog_content = "是的，但當時的我無論如何也想不到是他。",
  ui_story_5028_50280501_38_dialog_content = "在吃飽之後，他突然又說什麼「我是全大陸唯一的神奇動物專家，正在這附近做生態調查」。",
  ui_story_5028_50280501_39_dialog_content = "這種完全像是騙子一樣的發言讓我差點直接一路逃到城鎮里去叫衛兵。",
  ui_story_5028_50280501_40_dialog_content = "不過接著他向我展示了那些潦草卻非常用心的手記，還有身上種種奇奇怪怪的道具。",
  ui_story_5028_50280501_41_dialog_content = "而且，他只用了一個口哨，就把附近的許多神奇動物都呼喚了過來。",
  ui_story_5028_50280501_42_dialog_content = "PlayerName還記得上次遇到比卡的時候嗎？",
  ui_story_5028_50280501_43_dialog_content = "你應該已經猜到了，我能和神奇動物心靈溝通，就類似於你能和光靈感應。",
  ui_story_5028_50280501_44_dialog_content = "所以我能聽懂小蒼獅龍和比卡的叫聲，而且比起和光靈......我更喜歡和神奇動物相處。",
  ui_story_5028_50280501_45_dialog_content = "我當時一定是被神奇動物環繞著所帶來的幸福感沖昏了頭腦。",
  ui_story_5028_50280501_46_dialog_content = "加上他一直說「妳能和神奇動物溝通嗎，這麼有天賦的話一定會成為偉大的神奇動物專家」！",
  ui_story_5028_50280501_47_dialog_content = "成為神奇動物專家什麼的，對那時的我來說誘惑力太強了。",
  ui_story_5028_50280501_48_dialog_content = "不，即使是現在的我，恐怕也會選擇成為他的弟子吧。",
  ui_story_5028_50280501_49_dialog_content = "因為那一刻，我已經堅定地相信他就是那本書的作者，神奇動物專家維克。",
  ui_story_5028_50280501_50_dialog_content = "雖然是我自己選的路，我還是要說師父是個壞師父——！",
  ui_story_5028_50280501_51_dialog_content = "哈哈哈，那麼其實妳一直在做自己喜歡的事呀。",
  ui_story_5028_50280501_52_dialog_content = "呀——！",
  ui_story_5028_50280501_53_dialog_content = "小心！",
  ui_story_5028_50280501_54_dialog_content = "對，對不起！腳底突然滑了一下。",
  ui_story_5028_50280501_55_dialog_content = "沒關係、沒關係，妳沒事就好。",
  ui_story_5028_50280501_56_dialog_content = "（怎麼又來？）",
  ui_story_5028_50280501_57_dialog_content = "抱歉，那個啊，其實我認為。",
  ui_story_5028_50280501_58_dialog_content = "人生就是這樣喔，怎麼可能一切都順心如意嘛，妳已經比大多數的人要幸福多了！",
  ui_story_5028_50280501_59_dialog_content = "大哥哥，你努力裝成大人說話的樣子給人的感覺真是一言難盡呢。",
  ui_story_5028_50280501_60_dialog_content = "是不是剛剛身材很好的姐姐摔過來時把你的頭撞暈了？",
  ui_story_5028_50280501_61_dialog_content = "咳，她根本沒撞過來，我直接扶住了她好嗎。",
  ui_story_5028_50280501_62_dialog_content = "而且菲雅，妳這種語氣......其實是在嫉妒吧？",
  ui_story_5028_50280501_63_dialog_content = "哼，菲雅才不會在意這種庸俗又無聊的事呢！有這麼多神奇動物陪著我就夠啦。",
  ui_story_5028_50280501_64_dialog_content = "明明就醋意都快溢出來了。",
  ui_story_5028_50280501_65_dialog_content = "你——！",
  ui_story_5028_50280501_66_dialog_content = "好好，回歸正題，妳既然能和神奇動物溝通，那麼的確很有成為神奇動物專家的天賦。",
  ui_story_5028_50280501_67_dialog_content = "就像我能指揮和幫助光靈戰鬥，也就很有指揮者的天賦嘛。",
  ui_story_5028_50280501_68_dialog_content = "哼，的確是這樣啦，但也有例外，菲雅沒辦法和凱羅交流呢。",
  ui_story_5028_50280501_69_dialog_content = "囉～",
  ui_story_5028_50280501_70_dialog_content = "為什麼？",
  ui_story_5028_50280501_71_dialog_content = "不知道......師父解釋說牠是某種特別的珍奇物種。",
  ui_story_5028_50280501_72_dialog_content = "囉！",
  ui_story_5028_50280501_73_dialog_content = "珍奇物種？但蒼獅龍那種才能算是珍奇物種吧？",
  ui_story_5028_50280501_74_dialog_content = "是吧，就連你也不會相信師父這種鬼話。",
  ui_story_5028_50280501_75_dialog_content = "囉......囉......",
  ui_story_5028_50280501_76_dialog_content = "別不開心啦，凱羅。",
  ui_story_5028_50280501_77_dialog_content = "雖然沒法讀懂你的想法，但菲雅相信你一定是個善良的孩子。",
  ui_story_5028_50280501_78_dialog_content = "囉～",
  ui_story_5028_50280501_79_dialog_content = "雖然可能很沒用，也幫不上忙就是了。",
  ui_story_5028_50280501_80_dialog_content = "囉！！",
  ui_story_5028_50280501_81_dialog_content = "呀——！！",
  ui_story_5028_50280501_82_dialog_content = "怎麼又有人摔倒了？",
  ui_story_5028_50280501_83_dialog_content = "這地方果然不太對，我們去摔倒那人旁邊看看！",
  ui_story_5028_50280501_84_dialog_content = "喂！菲雅妳別匆匆忙忙的——",
  ui_story_5028_50280501_85_dialog_content = "哇啊——",
  ui_story_5028_50280501_86_dialog_content = "嘿！",
  ui_story_5028_50280501_87_dialog_content = "謝，謝謝你，PlayerName。",
  ui_story_5028_50280501_88_dialog_content = "真是的，明明知道容易摔倒幹嘛還衝那麼快。",
  ui_story_5028_50280501_89_dialog_content = "抱歉......我一著急就，麻煩你先放我下來吧。",
  ui_story_5028_50280501_90_dialog_content = "啊，好的。",
  ui_story_5028_50280501_91_dialog_content = "原來如此，果然是這個。",
  ui_story_5028_50280501_92_dialog_content = "嗯？",
  ui_story_5028_50280501_93_dialog_content = "你看不到嗎？在我腳上粘著的這個。",
  ui_story_5028_50280501_94_dialog_content = "這個透明的東西就是<color=#FFB400>糯糯粘</color>喔。",
  ui_story_5028_50280501_95_dialog_content = "咕嘰。",
  ui_story_5028_50280501_96_dialog_content = "牠們雖然平時生活在水裡，但也需要爬到岸上呼吸。",
  ui_story_5028_50280501_97_dialog_content = "因為身體一般情況下都是透明的，所以很容易被踩到。",
  ui_story_5028_50280501_98_dialog_content = "看來這個地方因為光靈活動太多，已經不適合牠們居住了。",
  ui_story_5028_50280501_99_dialog_content = "牠們傾巢出動，應該就是在準備遷徙到別處。",
  ui_story_5028_50280501_100_dialog_content = "不過牠們移動的速度太慢了，又總是被人踩來踩去，這樣糯糯粘和遊客都很容易受傷。",
  ui_story_5028_50280501_101_dialog_content = "（只要一談到神奇動物相關的話題，菲雅就變得非常認真了。）",
  ui_story_5028_50280501_102_dialog_content = "對了，我們試煉的內容，應該就是幫助牠們順利遷徙吧！",
  ui_story_5028_50280501_103_dialog_content = "應該是，那我們就把被人群衝散的糯糯粘一一找到，然後護送牠們遷徙。",
  ui_story_5028_50280501_104_dialog_content = "凱羅，不要和糯糯粘玩個不停了，來一起幫忙啦！",
  ui_story_5028_50280501_105_dialog_content = "囉！",
  ui_story_5028_50280501_106_dialog_content = "呼，這就是最後一隻了吧？",
  ui_story_5028_50280501_107_dialog_content = "咕嘰......",
  ui_story_5028_50280501_108_dialog_content = "嗯，牠們都在朝著一個方向爬過去呢。",
  ui_story_5028_50280501_109_dialog_content = "牠們會尋找新的海岸，適合的棲息地，我們只要一路護送牠們過去就行了。",
  ui_story_5028_50280501_110_dialog_content = "稍等一下，那個方向好像有暗鬼，能不能和牠們說一下繞路走啊？",
  ui_story_5028_50280501_111_dialog_content = "不可能的，牠們都是些一根筋，不然也不可能一直被人踩來踩去也不躲開了。",
  ui_story_5028_50280501_112_dialog_content = "不就是幾隻臭暗鬼，我不會再躲著牠們了！",
  ui_story_5028_50280501_113_dialog_content = "這次就讓本菲雅小姐，把這些臭暗鬼全部揍跑！",
  ui_story_5028_50280502_1_dialog_content = "<color=#e8d9bb>嘩啦啦......</color>",
  ui_story_5028_50280502_2_dialog_content = "這處海岸非常安靜呢，甚至連海鷗的聲音都很少聽到。",
  ui_story_5028_50280502_3_dialog_content = "糯糯粘牠們應該能很舒適地生活在這裡吧。",
  ui_story_5028_50280502_4_dialog_content = "咕嘰～咕嘰～",
  ui_story_5028_50280502_5_dialog_content = "要多注意安全喔，下次人群聚集來之前就先遷徙走吧～",
  ui_story_5028_50280502_6_dialog_content = "喂喂，那些摔倒的也只是無辜的遊客吧！",
  ui_story_5028_50280502_7_dialog_content = "但是因為暗鬼大量出現和環境的急劇變化，神奇動物的棲息之所就變得愈來愈少了嘛。",
  ui_story_5028_50280502_8_dialog_content = "你知道嗎，很多神奇動物，其實一直在默默地保護著光靈喔。",
  ui_story_5028_50280502_9_dialog_content = "有許多城鎮附近都生活著神奇動物，牠們往往是最先發現和抵禦暗鬼的第一線唷。",
  ui_story_5028_50280502_10_dialog_content = "這個我還是第一次聽說。",
  ui_story_5028_50280502_11_dialog_content = "不管怎麼說，又一樁試煉完成啦！今天也是幫了神奇動物們的一天呢！",
  ui_story_5028_50280502_12_dialog_content = "（欸？腿上黏黏的觸感？）",
  ui_story_5028_50280502_13_dialog_content = "咕嘰......",
  ui_story_5028_50280502_14_dialog_content = "你說之前遇到過一隻可怕的怪物在附近出現，但大家都不相信，所以你想留在菲雅身邊嗎？",
  ui_story_5028_50280502_15_dialog_content = "嘿嘿，你這種搭訕的說法可真老套呢。",
  ui_story_5028_50280502_16_dialog_content = "不過可以喔，就和大家一起留在我身邊吧！",
  ui_story_5028_50280502_17_dialog_content = "PlayerName，你看你看，我們又有新的夥伴了！",
  ui_story_5028_50280502_18_dialog_content = "囉～",
  ui_story_5028_50280502_19_dialog_content = "居然又來了一隻？妳平時也是這麼受神奇動物歡迎嗎？",
  ui_story_5028_50280502_20_dialog_content = "嗨～",
  ui_story_5028_50280502_21_dialog_content = "當然啦，我可是將要成為神奇動物專家的人，當然要和所有神奇動物都成為朋友！",
  ui_story_5028_50280502_22_dialog_content = "不過數量太多的話，我還是會把牠們送到師父那邊照顧的，畢竟在我身邊也會遇到危險。",
  ui_story_5028_50280502_23_dialog_content = "明白了明白了，那麼專家大人距離試煉完成還差多少呢？",
  ui_story_5028_50280502_24_dialog_content = "唔，我看看筆記。",
  ui_story_5028_50280502_25_dialog_content = "太棒了！不對，慘了！",
  ui_story_5028_50280502_26_dialog_content = "囉？",
  ui_story_5028_50280502_27_dialog_content = "嗯？",
  ui_story_5028_50280502_28_dialog_content = "試煉可以說都完成了，但又可能永遠都無法完成了。",
  ui_story_5028_50280502_29_dialog_content = "妳在說什麼傻話啦？",
  ui_story_5028_50280502_30_dialog_content = "那個！有危險性的試煉都已經完成了！",
  ui_story_5028_50280502_31_dialog_content = "但是難度最高的！背下師父寫的《神奇動物大全》的試煉還遙遙無期呢！",
  ui_story_5028_50280502_32_dialog_content = "可惡，明明已經背一週了，好像才背下來兩頁半。",
  ui_story_5028_50280502_33_dialog_content = "囉......",
  ui_story_5028_50280502_34_dialog_content = "唉，這種事光靠打架和蠻力可解決不了。",
  ui_story_5028_50280502_35_dialog_content = "就算我是空裔，也沒辦法把記憶塞進你的小腦袋瓜里喔。",
  ui_story_5028_50280502_36_dialog_content = "......囉！",
  ui_story_5028_50280502_37_dialog_content = "嗚……",
  ui_story_5028_50280502_38_dialog_content = "囉！囉！",
  ui_story_5028_50280502_39_dialog_content = "嗚？凱羅你幹嘛啦。",
  ui_story_5028_50280502_40_dialog_content = "不要一直拉著筆記，會撕破的！",
  ui_story_5028_50280502_41_dialog_content = "囉！",
  ui_story_5028_50280502_42_dialog_content = "我都說了不要——呀！",
  ui_story_5028_50280502_43_dialog_content = "菲雅，沒事吧。",
  ui_story_5028_50280502_44_dialog_content = "臭凱羅，你是想打架嗎！",
  ui_story_5028_50280502_45_dialog_content = "等一下，凱羅在翻筆記。",
  ui_story_5028_50280502_46_dialog_content = "嗯？",
  ui_story_5028_50280502_47_dialog_content = "囉！囉！",
  ui_story_5028_50280502_48_dialog_content = "這頁筆記？是一隻兔子？",
  ui_story_5028_50280502_49_dialog_content = "兔子？",
  ui_story_5028_50280502_50_dialog_content = "我們到了。",
  ui_story_5028_50280502_51_dialog_content = "嗯？這就是妳重金求來的線索嗎？",
  ui_story_5028_50280502_52_dialog_content = "沒想到在影鎮混了這麼多年的斯莫奇大姐也會被騙啊。",
  ui_story_5028_50280502_53_dialog_content = "還是說妳是故意想約我來海邊玩？不過抱歉，我可沒準備泳衣喔。",
  ui_story_5028_50280502_54_dialog_content = "哈哈，不好意思我穿著呢。",
  ui_story_5028_50280502_55_dialog_content = "怎麼樣，惱火嗎？沒能換上妳那件一點防禦力都沒有的破泳裝。",
  ui_story_5028_50280502_56_dialog_content = "現在就只能穿得這麼厚，像個笨蛋一樣站在海邊。",
  ui_story_5028_50280502_57_dialog_content = "我可是一直想看看你這幅表情，這幅嫉妒我的表情啊。",
  ui_story_5028_50280502_58_dialog_content = "妳，妳！我先抱著妳跳海再去找空裔！",
  ui_story_5028_50280502_59_dialog_content = "哈哈哈，其實空裔怎麼樣都無所謂吧，我就是好奇跟著湊個熱鬧，順便打發一下時間。",
  ui_story_5028_50280502_60_dialog_content = "妳不也是因為這個才來的嗎？",
  ui_story_5028_50280502_61_dialog_content = "我的理由可沒這麼膚淺，請不要把我和妳混為一談。",
  ui_story_5028_50280502_62_dialog_content = "這次就是我吉納維芙能堂堂正正超過妳的偉大機會！",
  ui_story_5028_50280502_63_dialog_content = "不是靠什麼泳裝，而是靠我身為賞金獵人的超凡職業素養！",
  ui_story_5028_50280502_64_dialog_content = "哦？說的那麼熱鬧，還不是連件泳衣都沒拿嗎——",
  ui_story_5028_50280502_65_dialog_content = "真好啊，我也想要泳衣。",
  ui_story_5028_50280502_66_dialog_content = "那邊的幾位，請看鏡頭——",
  ui_story_5028_50280502_67_dialog_content = "<color=#e8d9bb>喀嚓！</color>",
  ui_story_5028_50280502_68_dialog_content = "萊斯特？",
  ui_story_5028_50280502_69_dialog_content = "唷，这不是斯莫奇嘛。",
  ui_story_5028_50280502_70_dialog_content = "妳怎麼在這裡？還在旅行嗎？",
  ui_story_5028_50280502_71_dialog_content = "這還用說，兩位看著也眼熟啊，你們一起來海邊玩嗎？",
  ui_story_5028_50280502_72_dialog_content = "喏，剛拍的全家福。",
  ui_story_5028_50280502_73_dialog_content = "喔，謝謝。",
  ui_story_5028_50280502_74_dialog_content = "......給我也看看。",
  ui_story_5028_50280502_75_dialog_content = "大概算是出來玩吧，再順便找找一個好像被綁架或者失蹤了的朋友。",
  ui_story_5028_50280502_76_dialog_content = "喔對，妳應該知道的，就是那個空裔。",
  ui_story_5028_50280502_77_dialog_content = "空裔丟了？您說全大陸唯一一隻空裔不見了嗎？",
  ui_story_5028_50280502_78_dialog_content = "對，一隻、一個、一匹什麼的。總之他不見了。",
  ui_story_5028_50280502_79_dialog_content = "知道了，接下來的旅行中幫妳們留意一下。",
  ui_story_5028_50280502_80_dialog_content = "下次再碰到他，我就給妳們直接抓回來。",
  ui_story_5028_50280601_1_dialog_content = "試煉：背下整本《神奇動物大全》",
  ui_story_5028_50280601_2_dialog_content = "<color=#e8d9bb>砰！</color>",
  ui_story_5028_50280601_3_dialog_content = "<color=#e8d9bb>砰砰！</color>",
  ui_story_5028_50280601_4_dialog_content = "夠了！別亂開槍。",
  ui_story_5028_50280601_5_dialog_content = "你這樣會嚇跑獵物的。",
  ui_story_5028_50280601_6_dialog_content = "嘖，我們就放任那兩個小子跑了嗎？",
  ui_story_5028_50280601_7_dialog_content = "沒時間糾纏了，得趕快幫<color=#FFB400>蓋里</color>老闆抓住那隻<color=#FFB400>「佩可兔」</color>。",
  ui_story_5028_50280601_8_dialog_content = "惹怒了老闆，我們倆都得吃不了兜著走。",
  ui_story_5028_50280601_9_dialog_content = "嗚。",
  ui_story_5028_50280601_10_dialog_content = "哈，哈——",
  ui_story_5028_50280601_11_dialog_content = "哈啾！！",
  ui_story_5028_50280601_12_dialog_content = "噓。",
  ui_story_5028_50280601_13_dialog_content = "他們走掉了。",
  ui_story_5028_50280601_14_dialog_content = "囉。",
  ui_story_5028_50280601_15_dialog_content = "還好凱羅聰明，帶著我們躲進了被雪覆蓋的樹叢里。",
  ui_story_5028_50280601_16_dialog_content = "囉～",
  ui_story_5028_50280601_17_dialog_content = "哈啾——！",
  ui_story_5028_50280601_18_dialog_content = "哈啾！哈啾！哈啾！",
  ui_story_5028_50280601_19_dialog_content = "妳沒事吧，用這個擦擦。",
  ui_story_5028_50280601_20_dialog_content = "呼，謝謝。",
  ui_story_5028_50280601_21_dialog_content = "這究竟是什麼鬼地方，凍得人手腳都硬邦邦的。",
  ui_story_5028_50280601_22_dialog_content = "如果不是要抓手冊里提到的「佩可兔」，菲雅真的不想直接衝來這麼冷的地方。",
  ui_story_5028_50280601_23_dialog_content = "我的外套借給妳穿吧，對了，我還有一條隨身攜帶的備用頭巾。",
  ui_story_5028_50280601_24_dialog_content = "算了吧，給我穿你也撐不了太久的。",
  ui_story_5028_50280601_25_dialog_content = "你把這個吃了。",
  ui_story_5028_50280601_26_dialog_content = "唔！？",
  ui_story_5028_50280601_27_dialog_content = "這個是用沙蟲粉末和燃油，還有日輪草混合在一起的藥丸。",
  ui_story_5028_50280601_28_dialog_content = "可以在極端寒冷的環境下維持軀體的溫度。",
  ui_story_5028_50280601_29_dialog_content = "不過因為最近沒怎麼弄到沙蟲粉，就只剩下這一顆了。",
  ui_story_5028_50280601_30_dialog_content = "感覺暖和多了，那妳怎麼辦？",
  ui_story_5028_50280601_31_dialog_content = "菲雅會讓糯糯粘貼在身體上儘量幫我保暖。",
  ui_story_5028_50280601_32_dialog_content = "咕嘰......",
  ui_story_5028_50280601_33_dialog_content = "如果菲雅倒下了，你就扛著我下山求救。",
  ui_story_5028_50280601_34_dialog_content = "但如果你倒下了，菲雅可很難把你弄下山呀。",
  ui_story_5028_50280601_35_dialog_content = "是這樣嗎？我知道了，如果真有什麼萬一，我一定會把妳扛下山的！",
  ui_story_5028_50280601_36_dialog_content = "嗯，不過仔細想想，你這幅孱弱的身體可能不太靠譜啊。不如把藥吐出來，我餵給凱羅吧。",
  ui_story_5028_50280601_37_dialog_content = "現在說也太晚了，已經消化掉了！",
  ui_story_5028_50280601_38_dialog_content = "哈哈哈，怎麼可能真的讓你吐出來啦。",
  ui_story_5028_50280601_39_dialog_content = "囉？",
  ui_story_5028_50280601_40_dialog_content = "既然恢復精神了，我們就繼續出發吧。",
  ui_story_5028_50280601_41_dialog_content = "要搶在那群獵人之前找到「佩可兔」。",
  ui_story_5028_50280601_42_dialog_content = "那隻兔子真的有這麼稀有嗎？居然要讓如此多的獵人深入這種不毛之地。",
  ui_story_5028_50280601_43_dialog_content = "看他們訓練有素的樣子也不是等閒之輩，他們的主顧一定下了大手筆吧。",
  ui_story_5028_50280601_44_dialog_content = "哼，那群笨蛋就算來再多也沒用的。",
  ui_story_5028_50280601_45_dialog_content = "人數優勢，獵槍獵犬，就算在山上布滿了陷阱也沒用。",
  ui_story_5028_50280601_46_dialog_content = "那隻狡猾的兔子根本不會上當的。",
  ui_story_5028_50280601_47_dialog_content = "既然這麼多老練的獵人都沒辦法，就靠我們真的能抓住牠嗎？",
  ui_story_5028_50280601_48_dialog_content = "放心好了，菲雅可是擁有豐富實戰經驗的神奇動物專家哦！",
  ui_story_5028_50280601_49_dialog_content = "對付區區佩可兔當然是手到擒來。",
  ui_story_5028_50280601_50_dialog_content = "手，手到擒來。手又凍僵了！",
  ui_story_5028_50280601_51_dialog_content = "找到師父的筆記了嗎？要不要我幫妳一起找？",
  ui_story_5028_50280601_52_dialog_content = "不用！菲雅找到了。",
  ui_story_5028_50280601_53_dialog_content = "牠們生性機敏聰慧，非常難以捕捉，但有著喜歡吃書的天性。",
  ui_story_5028_50280601_54_dialog_content = "太好了！那我們就用書做誘餌——",
  ui_story_5028_50280601_55_dialog_content = "但如果想當然地用書作為誘餌來捕捉牠們，恐怕只能無功而返。",
  ui_story_5028_50280601_56_dialog_content = "當我沒說過。",
  ui_story_5028_50280601_57_dialog_content = "因為牠們非常狡猾，突然出現作為誘餌的書會引起牠們強烈的警惕心。",
  ui_story_5028_50280601_58_dialog_content = "但也許可以利用牠們的好奇心，畢竟「別人碗裡的飯才最香」。",
  ui_story_5028_50280601_59_dialog_content = "利用好奇心？PlayerName，把你這兩天在讀的那本書借菲雅一下！",
  ui_story_5028_50280601_60_dialog_content = "你這是什麼書啊？《鄰桌的舒同學偶爾會用日蝕語悄悄撒嬌》？",
  ui_story_5028_50280601_61_dialog_content = "這標題怎麼這麼長啊？",
  ui_story_5028_50280601_62_dialog_content = "啊，這個是之前種葡萄的彭伯伯送給我的，說是他自己出版的小說。",
  ui_story_5028_50280601_63_dialog_content = "上面還有簽名呢，他說過幾年能賣出天價。",
  ui_story_5028_50280601_64_dialog_content = "啊，是嗎，好吧，那就這樣。至少不用拿師父的筆記去冒險。",
  ui_story_5028_50280601_65_dialog_content = "......唉。",
  ui_story_5028_50280601_66_dialog_content = "妳明明什麼也沒說，但好像深深地刺傷了我和遠在天邊的彭伯伯。",
  ui_story_5028_50280601_67_dialog_content = "別閒聊了，我們還要搶在獵人們之前抓到兔子呢。",
  ui_story_5028_50280601_68_dialog_content = "你先躲起來，我要開始讀書了。",
  ui_story_5028_50280601_69_dialog_content = "等兔子過來你就按下按鈕。",
  ui_story_5028_50280601_70_dialog_content = "那不會把妳和兔子都網在一起嗎？",
  ui_story_5028_50280601_71_dialog_content = "怕什麼，牠又不會咬菲雅。",
  ui_story_5028_50280601_72_dialog_content = "牠敢咬菲雅，菲雅就狠狠咬牠。",
  ui_story_5028_50280601_73_dialog_content = "<color=#e8d9bb>片刻後</color>",
  ui_story_5028_50280601_74_dialog_content = "佩可？",
  ui_story_5028_50280601_75_option_content = "与菲雅感應",
  ui_story_5028_50280601_76_dialog_content = "感覺到有東西過來了，沉住氣，菲雅。",
  ui_story_5028_50280601_77_dialog_content = "知道了，你也把握好時機。",
  ui_story_5028_50280601_78_dialog_content = "囉......",
  ui_story_5028_50280601_79_dialog_content = "佩可佩可......",
  ui_story_5028_50280601_80_dialog_content = "（哼哼哼，就是這樣，過來吧，受好奇心驅使來到菲雅身邊吧。）",
  ui_story_5028_50280601_81_dialog_content = "佩可......",
  ui_story_5028_50280601_82_dialog_content = "不行，這兔子太多疑了。牠一直在網子的邊緣跳來跳去，就是不肯進去。",
  ui_story_5028_50280601_83_dialog_content = "現在收網的話很容易被牠逃掉，我們再找下次機會就很難了！",
  ui_story_5028_50280601_84_dialog_content = "沒辦法了，我主動出擊，PlayerName你隨機應變。",
  ui_story_5028_50280601_85_dialog_content = "給我——",
  ui_story_5028_50280601_86_dialog_content = "佩可？",
  ui_story_5028_50280601_87_dialog_content = "給我老實點！！！",
  ui_story_5028_50280601_88_dialog_content = "佩可！！",
  ui_story_5028_50280601_89_dialog_content = "看我的！",
  ui_story_5028_50280601_90_dialog_content = "抓到了！我抓到了！",
  ui_story_5028_50280601_91_dialog_content = "佩可佩可佩可佩可！！",
  ui_story_5028_50280601_92_dialog_content = "居然用突然大吼的方式把佩可兔一瞬間嚇傻了。",
  ui_story_5028_50280601_93_dialog_content = "關鍵時刻能想出這種方法，該說妳聰明呢，還是說妳滿腦子奇思妙想。",
  ui_story_5028_50280601_94_dialog_content = "嘿嘿，菲雅就當你在夸菲雅啦。我說你就別在那裡愣著了，快把我和兔子撈出來吧。",
  ui_story_5028_50280601_95_dialog_content = "嘿嘿嘿嘿，這樣最後的試煉就有辦法啦。",
  ui_story_5028_50280601_96_dialog_content = "佩......佩可......",
  ui_story_5028_50280601_97_dialog_content = "囉～",
  ui_story_5028_50280601_98_dialog_content = "這隻兔子對妳的試煉有什麼幫助嗎？",
  ui_story_5028_50280601_99_dialog_content = "根據書上的記載，佩可兔可以攝入大量書籍內容，並把這些內容全部轉移給他人。",
  ui_story_5028_50280601_100_dialog_content = "我居然已經對這種奇奇怪怪的說法不感到驚訝了，總之具體要怎麼做呢？",
  ui_story_5028_50280601_101_dialog_content = "我看看，先把需要轉移的內容，也就是書籍餵給牠。",
  ui_story_5028_50280601_102_dialog_content = "嗯，既然是神奇動物，這種事倒也能接受。",
  ui_story_5028_50280601_103_dialog_content = "然後呢？",
  ui_story_5028_50280601_104_dialog_content = "然後......適量油燒熱......加入蔥姜蒜炒香。",
  ui_story_5028_50280601_105_dialog_content = "？",
  ui_story_5028_50280601_106_dialog_content = "佩可！！",
  ui_story_5028_50280601_107_dialog_content = "囉！！",
  ui_story_5028_50280601_108_dialog_content = "加入少量糖，炒出焦糖色把去毛之後的......",
  ui_story_5028_50280601_109_dialog_content = "等等，該不會是要紅燒？",
  ui_story_5028_50280601_110_dialog_content = "清蒸應該也可以吧，怎麼可能！這個臭師父。",
  ui_story_5028_50280601_111_dialog_content = "要不要試試只吃一條腿呢，說不定也有效果。",
  ui_story_5028_50280601_112_dialog_content = "佩可佩可佩可！！",
  ui_story_5028_50280601_113_dialog_content = "這種玩笑還是算啦，佩可兔已經快被妳嚇壞了。",
  ui_story_5028_50280601_114_dialog_content = "等一下，牠好像在提醒我們小心。",
  ui_story_5028_50280601_115_dialog_content = "小心什麼？我們已經甩開那群獵人了吧。",
  ui_story_5028_50280601_116_dialog_content = "牠說......<color=#FFB400>小心暗鬼</color>！",
  ui_story_5028_50280602_1_dialog_content = "這群難纏的傢伙。",
  ui_story_5028_50280602_2_dialog_content = "怎麼到處都有暗鬼啊，我看還是別當神奇動物專家了，當個暗鬼專家要輕鬆得多。",
  ui_story_5028_50280602_3_dialog_content = "不過幸好有這孩子提醒，不然我們就被包圍了。",
  ui_story_5028_50280602_4_dialog_content = "佩可佩可～",
  ui_story_5028_50280602_5_dialog_content = "這下更沒法下嘴了吧，那妳的試煉怎麼辦？",
  ui_story_5028_50280602_6_dialog_content = "再想想辦法吧，隨便因為自己的私慾而傷害神奇動物，還算什麼神奇動物專家。",
  ui_story_5028_50280602_7_dialog_content = "就算菲雅通過不了試煉，也不想......",
  ui_story_5028_50280602_8_dialog_content = "嗚，到底要怎麼辦嘛。",
  ui_story_5028_50280602_9_dialog_content = "佩可......",
  ui_story_5028_50280602_10_dialog_content = "囉......",
  ui_story_5028_50280602_11_dialog_content = "咕嘰......",
  ui_story_5028_50280602_12_dialog_content = "謝謝你們安慰菲雅。",
  ui_story_5028_50280602_13_dialog_content = "唉，就沒什麼其他辦法了嗎？",
  ui_story_5028_50280602_14_dialog_content = "應該也有不傷害到牠，也能讓牠幫上忙的方法吧。",
  ui_story_5028_50280602_15_dialog_content = "菲雅想到了！",
  ui_story_5028_50280602_16_dialog_content = "佩可兔，你願意聽聽菲雅完美無缺的計畫嗎？",
  ui_story_5028_50280602_17_dialog_content = "佩可！",
  ui_story_5028_50280602_17X1_dialog_content = "呀——",
  ui_story_5028_50280602_18_dialog_content = "嗯？牠在很高興地蹭妳呢。",
  ui_story_5028_50280602_19_dialog_content = "嘿嘿，這就是菲雅強大的親和力呀。",
  ui_story_5028_50280602_19X1_dialog_content = "知道啦知道啦，所以妳想到的辦法是什麼？",
  ui_story_5028_50280602_19X2_dialog_content = "對別人來說可能很難，但這件事對菲雅來說可是很簡單呢。",
  ui_story_5028_50280602_19X3_dialog_content = "還記得嗎，菲雅能聽懂神奇動物的叫聲。",
  ui_story_5028_50280602_19X4_dialog_content = "那麼只要在測試的時候，讓佩可兔躲在我的懷裡或者口袋裡。",
  ui_story_5028_50280602_19X5_dialog_content = "接著小聲告訴我正確答案就可以啦。",
  ui_story_5028_50280602_19X6_dialog_content = "這樣菲雅一定能順利通過試煉，嚇那個笨蛋師父一大跳！",
  ui_story_5028_50280602_19X7_dialog_content = "有這麼容易嗎，我總感覺有點懸啊。",
  ui_story_5028_50280602_20_dialog_content = "佩可佩可～",
  ui_story_5028_50280602_20X1_dialog_content = "能不能拜託你到時候躲進我的口袋裡......",
  ui_story_5028_50280602_20X2_dialog_content = "然後偷偷把正確答案告訴我呢？",
  ui_story_5028_50280602_20X3_dialog_content = "佩可佩可～",
  ui_story_5028_50280602_20X4_dialog_content = "嘿嘿，太好啦。",
  ui_story_5028_50280602_21_dialog_content = "牠說願意幫我的忙，還希望能和我們一起旅行呢！",
  ui_story_5028_50280602_22_dialog_content = "佩可～",
  ui_story_5028_50280602_22X1_dialog_content = "這樣就大功告成了！我們可以回去找師父啦！",
  ui_story_5028_50280602_23_dialog_content = "反正已經有這麼多動物跟著妳了，也不差這一位了吧。",
  ui_story_5028_50280602_24_dialog_content = "嘿嘿，PlayerName你真是善良呢。",
  ui_story_5028_50280602_25_dialog_content = "哦？你說自己是佩可兔中的幸運兒？上次被一個可怕的怪物抓到後也被安全放生了嗎？",
  ui_story_5028_50280602_26_dialog_content = "真是了不起，菲雅相信你一定能給我們的旅途帶來更多幸運，以後就拜託你了喔～",
  ui_story_5028_50280602_27_dialog_content = "佩可～",
  ui_story_5028_50280602_28_dialog_content = "雷文頓，衝鋒！",
  ui_story_5028_50280602_29_dialog_content = "<color=#e8d9bb>砰砰！</color>",
  ui_story_5028_50280602_30_dialog_content = "點燃大地吧！蠍尾獅！",
  ui_story_5028_50280602_31_dialog_content = "快、快撤，這群傢伙不好惹！",
  ui_story_5028_50280602_32_dialog_content = "妳們給我記住，我們<color=#FFB400>蓋里老大</color>和<color=#FFB400>鐵鞭團</color>絕對不會放過妳們的！",
  ui_story_5028_50280602_33_dialog_content = "跑掉了。",
  ui_story_5028_50280602_34_dialog_content = "沒找到空裔，結果意外遇到一群充滿敵意的獵人啊。",
  ui_story_5028_50280602_35_dialog_content = "他們是來這裡找什麼嗎？和PlayerName捲入的麻煩會有關嗎？",
  ui_story_5028_50280602_36_dialog_content = "嘖，早知道就抓一個人問清楚了。",
  ui_story_5028_50280602_37_dialog_content = "唷吼～這不是PlayerName的夥伴們嘛。",
  ui_story_5028_50280602_38_dialog_content = "愛洛拉？妳怎麼在這裡。",
  ui_story_5028_50280602_39_dialog_content = "我在送信途中聽到槍聲，以為是有什麼情況就過來了。妳們沒受傷吧？",
  ui_story_5028_50280602_40_dialog_content = "我們在找空裔的時候碰到一群主動攻擊我們的獵人。",
  ui_story_5028_50280602_41_dialog_content = "沒受傷，已經打跑了。",
  ui_story_5028_50280602_42_dialog_content = "欸欸欸？妳說空裔？PlayerName失蹤了嗎？",
  ui_story_5028_50280602_43_dialog_content = "對了，我過來的路上好像看到了露營的痕跡，說不定會有什麼線索。",
  ui_story_5028_50280602_44_dialog_content = "我先帶諸位一起過去看看吧，之後再去送信。",
  ui_story_5028_50280602_45_dialog_content = "總感覺，變成了某種旅行團一樣。",
  ui_story_5028_50280602_46_dialog_content = "這不是還滿有趣的嗎？出來看看不同的景色，順便收拾收拾不同的暗鬼和光靈。",
  ui_story_5028_50280602_47_dialog_content = "確實，可太有趣了。",
  ui_story_5028_50280701_1_dialog_content = "試煉：抵禦甜蜜的誘惑",
  ui_story_5028_50280701_2_dialog_content = "白白的雲～青青的嫩枝～♪",
  ui_story_5028_50280701_3_dialog_content = "菲雅和她的朋友走在路上～♫",
  ui_story_5028_50280701_4_dialog_content = "還有她快樂的同伴～空裔呀～♪",
  ui_story_5028_50280701_5_dialog_content = "囉囉囉～♫",
  ui_story_5028_50280701_6_dialog_content = "看起來妳心情非常好呢。",
  ui_story_5028_50280701_7_dialog_content = "嘿嘿，沒想到我們離完成試煉只剩一步之遙了呢。",
  ui_story_5028_50280701_8_dialog_content = "多虧了有PlayerName和凱羅牠們的幫助，才能這麼順利。",
  ui_story_5028_50280701_9_dialog_content = "我也很意外。",
  ui_story_5028_50280701_10_dialog_content = "本來我以為菲雅吃不了多少苦，就會主動放棄，我也不用跟著一起受罪了。",
  ui_story_5028_50280701_11_dialog_content = "沒想到吧，菲雅可是對神奇動物充滿了熱情唷！",
  ui_story_5028_50280701_12_dialog_content = "如果妳的態度不是兇兇的就更好了。",
  ui_story_5028_50280701_13_dialog_content = "那可不行，這是菲雅的個人特色哦，如果缺少了這個魅力就會下降很多！",
  ui_story_5028_50280701_14_dialog_content = "也有道理，這樣菲雅才是菲雅。",
  ui_story_5028_50280701_15_dialog_content = "嘿嘿——",
  ui_story_5028_50280701_16_dialog_content = "（是啊，我知道那只是她的偽裝，真實的菲雅內心十分溫柔。）",
  ui_story_5028_50280701_16X_dialog_content = "（這些精通人性的小傢伙們也都很清楚。）",
  ui_story_5028_50280701_17_dialog_content = "（單純又聰明的牠們能分辨出誰是真誠的、誰是虛偽的、誰是溫柔的、誰又是殘暴的。）",
  ui_story_5028_50280701_18_dialog_content = "（牠們與她的親密關係足以證明菲雅是個善良又溫柔的孩子。）",
  ui_story_5028_50280701_19_dialog_content = "......嗯？在發呆想些什麼呢？",
  ui_story_5028_50280701_20_dialog_content = "口渴了嗎？菲雅把水壺借給你。",
  ui_story_5028_50280701_21_dialog_content = "差不多再走半天就能到師父家了，稍微堅持一下吧。",
  ui_story_5028_50280701_22_dialog_content = "不，不用了，我不渴。",
  ui_story_5028_50280701_23_dialog_content = "我是在想，妳順利出師之後有什麼打算嗎？",
  ui_story_5028_50280701_24_dialog_content = "打算呀，大概就是四處旅行，結識和記錄更多神奇動物，然後寫出比師父那本還要厲害的書吧。",
  ui_story_5028_50280701_25_dialog_content = "真像是菲雅會說的話呀......",
  ui_story_5028_50280701_26_dialog_content = "嘿嘿，那PlayerName有什麼打算呢。",
  ui_story_5028_50280701_27_dialog_content = "先想辦法把蒼獅龍的事解決了吧。",
  ui_story_5028_50280701_28_dialog_content = "我可不想以後到哪裡突然鑽出一隻那麼大的飛龍。",
  ui_story_5028_50280701_29_dialog_content = "放心吧。菲雅會幫你解決的。",
  ui_story_5028_50280701_30_dialog_content = "其實蒼獅龍只要過了交配期，八成就不會來找巨像了。",
  ui_story_5028_50280701_31_dialog_content = "但願如此吧。",
  ui_story_5028_50280701_32_dialog_content = "臨空者號這段時間都在我們頭頂上的高空中盤旋，估計累得夠嗆了。",
  ui_story_5028_50280701_33_dialog_content = "要對菲雅淵博的學識充滿信心才行喔——",
  ui_story_5028_50280701_34_dialog_content = "囉～",
  ui_story_5028_50280701_35_dialog_content = "是是。",
  ui_story_5028_50280701_36_dialog_content = "......欸？那是什麼？",
  ui_story_5028_50280701_37_dialog_content = "好像是尊<color=#FFB400>神像</color>？",
  ui_story_5028_50280701_38_dialog_content = "我還是第一次見到這種神像呢。",
  ui_story_5028_50280701_39_dialog_content = "（這種奇妙的感覺......這尊神像給我一種非常親切又舒適的感覺。）",
  ui_story_5028_50280701_40_dialog_content = "那個，我們要不要去拜一拜神像，祈求神明保佑妳能順利通過試煉呢。",
  ui_story_5028_50280701_41_dialog_content = "可以倒是可以，也沒什麼壞處吧。",
  ui_story_5028_50280701_42_dialog_content = "（愈是接近神像，我愈是能感覺到那種幾乎要讓人眩暈的舒適。）",
  ui_story_5028_50280701_43_dialog_content = "雖然不知道你是哪位神明大人，但請你保佑菲雅能順利通過試煉。",
  ui_story_5028_50280701_44_dialog_content = "請你保佑蒼獅龍能找到自己的新歡，讓臨空者號回到PlayerName身邊。",
  ui_story_5028_50280701_45_dialog_content = "請你保佑凱羅......",
  ui_story_5028_50280701_46_dialog_content = "請......",
  ui_story_5028_50280701_47_dialog_content = "…………",
  ui_story_5028_50280701_48_dialog_content = "嗯？怎麼感覺哪裡怪怪的？",
  ui_story_5028_50280701_49_dialog_content = "恭喜妳！菲雅！",
  ui_story_5028_50280701_50_dialog_content = "恭喜妳通過了試煉，成為了最偉大的神奇動物專家！",
  ui_story_5028_50280701_51_dialog_content = "欸？師父？我是最偉大的？",
  ui_story_5028_50280701_52_dialog_content = "是的，您快請坐。",
  ui_story_5028_50280701_53_dialog_content = "您的偉大功績已經遠遠超過了我，這個世界上論對神奇動物的瞭解，您排第二沒人敢排第一。",
  ui_story_5028_50280701_54_dialog_content = "而在下與你相比，簡直有著天壤之別，請您務必收我為徒，以後讓我跟隨您學習！",
  ui_story_5028_50280701_55_dialog_content = "嘿嘿嘿，也沒這麼厲害吧，菲雅考慮一下喔！",
  ui_story_5028_50280701_56_dialog_content = "菲雅小姐。",
  ui_story_5028_50280701_57_dialog_content = "欸？你是誰？",
  ui_story_5028_50280701_58_dialog_content = "您的偉大事跡在大陸上赫赫有名，而我則是眾多仰慕您才華者中的一個。",
  ui_story_5028_50280701_59_dialog_content = "您的追隨者們已經整裝待發，希望為您的下一次冒險提供後勤工作。",
  ui_story_5028_50280701_60_dialog_content = "菲雅！菲雅！菲雅！",
  ui_story_5028_50280701_61_dialog_content = "嗚哇！這麼多人都是我的崇拜者嗎？",
  ui_story_5028_50280701_62_dialog_content = "嘿嘿，果然偉大的事業，總會吸引眾人追隨呀。",
  ui_story_5028_50280701_63_dialog_content = "等等，好像忘記了什麼重要的人。",
  ui_story_5028_50280701_64_dialog_content = "PlayerName！PlayerName他呢？",
  ui_story_5028_50280701_65_dialog_content = "<color=#e8d9bb>與此同時</color>",
  ui_story_5028_50280701_66_dialog_content = "唔？我怎麼回到巨像上了，這裡是？",
  ui_story_5028_50280701_67_dialog_content = "居然還有這麼多的光珀！太棒了，我該不會是在做夢吧？",
  ui_story_5028_50280701_68_dialog_content = "管他是不是做夢，今天我就要把光珀都用來召集光靈！總之讓我先拉它一百下！！",
  ui_story_5028_50280701_69_dialog_content = "<color=#e8d9bb>砰——！</color>",
  ui_story_5028_50280701_70_dialog_content = "<color=#e8d9bb>砰、砰——！</color>",
  ui_story_5028_50280701_71_dialog_content = "唔！！怎麼好像聽見了打鬥聲？",
  ui_story_5028_50280701_72_dialog_content = "別睡了——笨蛋！！",
  ui_story_5028_50280701_73_dialog_content = "怎麼好像還聽到了有人罵我的聲音？",
  ui_story_5028_50280701_74_dialog_content = "再，再最後拉十下就去看看！",
  ui_story_5028_50280701_75_dialog_content = "嘎！",
  ui_story_5028_50280701_76_dialog_content = "呀！！",
  ui_story_5028_50280701_77_dialog_content = "暗，暗鬼！？",
  ui_story_5028_50280701_78_dialog_content = "發......發生什麼事了？",
  ui_story_5028_50280701_79_dialog_content = "菲雅？這是哪？怎麼會有暗鬼？妳又是誰？",
  ui_story_5028_50280701_80_dialog_content = "哪來那麼多廢話，起來戰鬥。",
  ui_story_5028_50280701_81_dialog_content = "<size=45>嘎！！！</size>",
  ui_story_5028_50280701_82_dialog_content = "菲雅！",
  ui_story_5028_50280701_83_dialog_content = "知......知道了，PlayerName，我們上！凱羅！",
  ui_story_5028_50280702_1_dialog_content = "居然遇到暗鬼。",
  ui_story_5028_50280702_2_dialog_content = "怎麼回事，我記得我們剛剛還在拜一尊神像。",
  ui_story_5028_50280702_3_dialog_content = "然後好像迷迷糊糊地夢到自己成為了神奇動物專家。",
  ui_story_5028_50280702_4_dialog_content = "我也是，我夢到了自己眼前都是金色和紫色的東西，閃閃發光......",
  ui_story_5028_50280702_5_dialog_content = "然後就有好多認識的光靈來到我身邊，甚至一些已經不在了的光靈也都和我成為了夥伴。",
  ui_story_5028_50280702_6_dialog_content = "你們兩個白日做夢的水平還不錯。",
  ui_story_5028_50280702_7_dialog_content = "妳剛剛提到了自己拜了一尊神像？",
  ui_story_5028_50280702_8_dialog_content = "是的，怎麼了？",
  ui_story_5028_50280702_9_dialog_content = "連那是什麼都不知道就敢隨便去拜。",
  ui_story_5028_50280702_10_dialog_content = "以妳這種吊兒郎當的態度，就別幻想著什麼神奇動物專家了。",
  ui_story_5028_50280702_11_dialog_content = "趁著啟光那邊有義務教育，抓緊去多讀兩年書，然後進軍工廠裡擰螺絲。",
  ui_story_5028_50280702_12_dialog_content = "妳說什麼！！！",
  ui_story_5028_50280702_13_dialog_content = "妳到底是誰啊，突然就冒出來對菲雅冷嘲熱諷的。",
  ui_story_5028_50280702_14_dialog_content = "別以為剛剛妳幫了菲雅，就可以對菲雅一直兇個不停！",
  ui_story_5028_50280702_15_dialog_content = "凱羅，我們上！",
  ui_story_5028_50280702_16_dialog_content = "……",
  ui_story_5028_50280702_17_dialog_content = "凱羅？",
  ui_story_5028_50280702_18_dialog_content = "那些神奇動物沒和我們在一起，我感應不到牠們。",
  ui_story_5028_50280702_19_dialog_content = "笨蛋。",
  ui_story_5028_50280702_20_dialog_content = "沒必要告訴妳我是誰。",
  ui_story_5028_50280702_21_dialog_content = "但要是妳還想以天真玩鬧的態度去成為神奇動物專家的話。",
  ui_story_5028_50280702_22_dialog_content = "不會吧？凱羅牠不見了？",
  ui_story_5028_50280702_23_dialog_content = "我勸妳還是馬上放棄吧！",
  ui_story_5028_50280702_24_dialog_content = "牠們不是妳的玩物，不是妳扮家家酒的玩伴，不是任妳擺布的溫順小動物。",
  ui_story_5028_50280702_25_dialog_content = "沒有決心和毅力，妳根本無法渡過苦海，只會在成長為神奇動物專家的半路上溺死。",
  ui_story_5028_50280702_26_dialog_content = "凱羅......凱羅......",
  ui_story_5028_50280702_27_dialog_content = "不光是妳，妳還會連累所有人，包括那些和妳扮家家酒的「夥伴」。",
  ui_story_5028_50280702_28_dialog_content = "妳，妳果然知道牠們在哪裡對吧？",
  ui_story_5028_50280702_29_dialog_content = "求求妳了，告訴我凱羅和大家在哪裡吧。",
  ui_story_5028_50280702_30_dialog_content = "妳這個笨蛋是不是聽不懂話——",
  ui_story_5028_50280702_31_dialog_content = "這四處都找不到凱羅牠們的身影，我們身上的裝備行李也都沒了。",
  ui_story_5028_50280702_32_dialog_content = "現在沒時間管那種事了......！拜託妳告訴我牠們在哪裡！",
  ui_story_5028_50280702_33_dialog_content = "牠們是師父交給我的......我重要的夥伴，如果妳哪怕知道牠們一點點下落，也求妳告訴我吧！",
  ui_story_5028_50280702_34_dialog_content = "......這幅蠢相真是讓人不舒服。",
  ui_story_5028_50280702_35_dialog_content = "我要走了，妳想站在這裡就請便吧。",
  ui_story_5028_50280702_36_dialog_content = "妳那群麻煩的夥伴可不會在山腳下等妳哭一整天。",
  ui_story_5028_50280702_37_dialog_content = "小孩子真是煩死了......",
  ui_story_5028_50280702_38_dialog_content = "菲雅！",
  ui_story_5028_50280702_39_dialog_content = "嗯！",
  ui_story_5028_50280702_40_dialog_content = "行李和裝備丟了就丟了吧，當務之急是馬上去找凱羅牠們！",
  ui_story_5028_50280702_41_dialog_content = "等一下，菲雅。",
  ui_story_5028_50280702_42_dialog_content = "剛剛那個女孩子好像掉了點東西？",
  ui_story_5028_50280702_43_dialog_content = "這是野外探險的指南針和一些必需的裝備。",
  ui_story_5028_50280702_44_dialog_content = "不是我丟失的那套，但看起來很新，應該是她的備用裝備，故意留下給我們的。",
  ui_story_5028_50280702_45_dialog_content = "雖然嘴巴很兇，但其實是個好人呢。",
  ui_story_5028_50280702_46_dialog_content = "嗯！下次見面了一定要好好感謝她。",
  ui_story_5028_50280702_47_dialog_content = "而且她，似乎有點眼熟，總感覺在哪裡見過。",
  ui_story_5028_50280702_48_dialog_content = "凱羅——！",
  ui_story_5028_50280702_49_dialog_content = "囉——！",
  ui_story_5028_50280702_50_dialog_content = "咕嘰......",
  ui_story_5028_50280702_51_dialog_content = "嗨嗨～",
  ui_story_5028_50280702_52_dialog_content = "佩可～",
  ui_story_5028_50280702_53_dialog_content = "太好了，大家都還在神像這裡等著呢。",
  ui_story_5028_50280702_54_dialog_content = "不過我們剛才為什麼會睡著，然後跑到那裡去呢？",
  ui_story_5028_50280702_55_dialog_content = "囉！囉囉！",
  ui_story_5028_50280702_56_dialog_content = "凱羅好像在指著這尊神像？",
  ui_story_5028_50280702_57_dialog_content = "果然是這尊神像有問題嗎？",
  ui_story_5028_50280702_58_dialog_content = "咕......",
  ui_story_5028_50280702_59_dialog_content = "神，神像動了？",
  ui_story_5028_50280702_60_dialog_content = "不對，這根本不是什麼神像！",
  ui_story_5028_50280702_61_dialog_content = "這是一種叫做<color=#FFB400>泥尊鷹</color>的神奇動物！沒想到能在這裡遇到牠。",
  ui_story_5028_50280702_62_dialog_content = "師父說牠因為數量稀少很可能已經滅絕了，甚至連神奇動物大全對牠的記載都非常少。",
  ui_story_5028_50280702_63_dialog_content = "只知道這傢伙會偽裝成神像，用催眠的方式讓人去參拜牠。",
  ui_story_5028_50280702_63X_dialog_content = "然後趁著人睡過去，搶走他們身上的財物。",
  ui_story_5028_50280702_64_dialog_content = "咕……咕……",
  ui_story_5028_50280702_65_dialog_content = "財物？牠要財物有什麼用？",
  ui_story_5028_50280702_66_dialog_content = "應該只是喜歡亮晶晶的貨幣之類的吧，很多動物都有這種習性。",
  ui_story_5028_50280702_67_dialog_content = "咕！！",
  ui_story_5028_50280702_68_dialog_content = "不好，牠要跑了！",
  ui_story_5028_50280702_69_dialog_content = "囉！",
  ui_story_5028_50280702_70_dialog_content = "幹得好凱羅！抓住牠別讓牠跑了！",
  ui_story_5028_50280702_71_dialog_content = "我抓住了！",
  ui_story_5028_50280702_72_dialog_content = "咕！",
  ui_story_5028_50280702_73_option_content = "用力抖泥尊鷹",
  ui_story_5028_50280702_74_dialog_content = "PlayerName！我們的東西從牠身上掉下來了。",
  ui_story_5028_50280702_75_option_content = "再多抖抖",
  ui_story_5028_50280702_76_dialog_content = "咕咕！",
  ui_story_5028_50280702_77_dialog_content = "<color=#e8d9bb>抖抖！</color>",
  ui_story_5028_50280702_78_dialog_content = "咕！",
  ui_story_5028_50280702_79_dialog_content = "愈來愈多了！這是啟光那邊的罐頭，白夜幣，還有北境的寶石？",
  ui_story_5028_50280702_80_dialog_content = "沒想到這個傢伙害了不少人呀，其他人的東西咱們就留在這裡吧。",
  ui_story_5028_50280702_81_dialog_content = "嘿嘿，我給你一個選擇的機會。",
  ui_story_5028_50280702_82_dialog_content = "咕？",
  ui_story_5028_50280702_83_dialog_content = "你是想被我就地正法呢？",
  ui_story_5028_50280702_84_dialog_content = "咕咕咕！！",
  ui_story_5028_50280702_85_dialog_content = "還是老老實實跟我一起上路？",
  ui_story_5028_50280702_86_dialog_content = "咕......",
  ui_story_5028_50280702_87_dialog_content = "咕！",
  ui_story_5028_50280702_88_dialog_content = "嘿嘿，那就老老實實跟我走吧！",
  ui_story_5028_50280702_89_dialog_content = "菲雅要帶著你去見師父，讓他見識見識本小姐的本事有多高超！",
  ui_story_5028_50280702_90_dialog_content = "呼……",
  ui_story_5028_50280702_91_dialog_content = "呼嚕……",
  ui_story_5028_50280702_92_dialog_content = "呼......老克，再來一碗！！",
  ui_story_5028_50280702_93_dialog_content = "我怎麼，睡著了？",
  ui_story_5028_50280702_94_dialog_content = "都別睡了，快醒醒！",
  ui_story_5028_50280702_95_dialog_content = "我們中招了！",
  ui_story_5028_50280702_96_dialog_content = "呵，所以說我們一幫人是被剛剛那尊破爛石像給坑了。",
  ui_story_5028_50280702_97_dialog_content = "我都說了不要拜不要拜。",
  ui_story_5028_50280702_98_dialog_content = "什麼婚戀順利，都是騙人的，妳這個人怎麼年紀愈大愈迷信了。",
  ui_story_5028_50280702_99_dialog_content = "這下全部家當都沒了。",
  ui_story_5028_50280702_100_dialog_content = "我，我只是想拜託神明讓我贏過妳。",
  ui_story_5028_50280702_101_dialog_content = "有挖苦我的閒工夫，還不如快點去找找丟失的東西！",
  ui_story_5028_50280702_102_dialog_content = "那個欠揍的神像呢？",
  ui_story_5028_50280702_103_dialog_content = "不見了？",
  ui_story_5028_50280702_104_dialog_content = "等一下，我發現了點東西。",
  ui_story_5028_50280702_105_dialog_content = "喂，斯莫奇，這該不會是妳以前用的金屬吉他撥片吧？",
  ui_story_5028_50280702_106_dialog_content = "還真是，咳，這可是我開瓶蓋的寶貝。",
  ui_story_5028_50280702_107_dialog_content = "其他東西還在嗎？",
  ui_story_5028_50280702_108_dialog_content = "神像不見了，東西還在。",
  ui_story_5028_50280702_109_dialog_content = "而且我還，聞到空裔的味道了。",
  ui_story_5028_50280801_1_dialog_content = "臭師父，菲雅回來了！",
  ui_story_5028_50280801_2_dialog_content = "你交給我的那些亂七八糟的試煉，菲雅都已經完成了！",
  ui_story_5028_50280801_X2_dialog_content = "但是凱羅怎麼好像並沒有進化呀？",
  ui_story_5028_50280801_3_dialog_content = "打擾了——",
  ui_story_5028_50280801_4_dialog_content = "（這裡好亂？！）",
  ui_story_5028_50280801_5_dialog_content = "（書籍亂七八糟地堆在各處，這裡的主人生活習慣太差了吧？）",
  ui_story_5028_50280801_6_dialog_content = "菲雅可以出師了吧？臭師父，師——",
  ui_story_5028_50280801_7_dialog_content = "怎麼回事？屋子裡變亂了！",
  ui_story_5028_50280801_8_dialog_content = "呃......這裡難道不是一直這麼亂嗎？",
  ui_story_5028_50280801_9_dialog_content = "不，臭師父家裡的亂是亂中有序的亂。",
  ui_story_5028_50280801_10_dialog_content = "表面上看，東西只是雜亂無章地堆放著，但實際上很有條理。",
  ui_story_5028_50280801_11_dialog_content = "師父會把每一本書都分門別類地放進同一堆裡。",
  ui_story_5028_50280801_12_dialog_content = "他的收納習慣很差，有一些沒讀完的書就會直接打開著放在最上面，所以顯得亂。",
  ui_story_5028_50280801_13_dialog_content = "你看，這堆書放的是昆蟲類生物相關，最上面的這兩本卻是關於水生動物的書。",
  ui_story_5028_50280801_14_dialog_content = "那個中年禿頂臭師父雖然不怎麼可靠，但他絕對不會做出亂放書籍這種事！",
  ui_story_5028_50280801_15_dialog_content = "那就意味著，有人動過維克先生的書？",
  ui_story_5028_50280801_16_dialog_content = "或許吧。現在最重要的是找到他！",
  ui_story_5028_50280801_17_dialog_content = "臭師父，你跑哪裡去了？快出來！",
  ui_story_5028_50280801_18_dialog_content = "<size=45>喂——！！！</size>",
  ui_story_5028_50280801_19_option_content = "維克先生！",
  ui_story_5028_50280801_20_dialog_content = "……",
  ui_story_5028_50280801_21_dialog_content = "看起來不在啊。",
  ui_story_5028_50280801_22_dialog_content = "桌子抽屜沒有合上，椅子不在原位，連他平時不讓我碰的收藏櫃的櫃門都敞著。",
  ui_story_5028_50280801_23_dialog_content = "看起來維克先生離開的時候非常匆忙。",
  ui_story_5028_50280801_24_dialog_content = "房間變亂，難道說......",
  ui_story_5028_50280801_25_dialog_content = "嗯，很可能是的。維克先生一定是被綁......",
  ui_story_5028_50280801_26_dialog_content = "他害怕我發現他是個騙子，所以趁我回來之前，連忙逃跑了！！！",
  ui_story_5028_50280801_27_dialog_content = "什麼？",
  ui_story_5028_50280801_28_dialog_content = "一定是這樣沒錯。",
  ui_story_5028_50280801_29_dialog_content = "妳難道不應該先懷疑維克先生是遭到了綁架嗎？",
  ui_story_5028_50280801_30_dialog_content = "咦？！",
  ui_story_5028_50280801_31_dialog_content = "咳咳，我......我早就想到這種可能性了！",
  ui_story_5028_50280801_32_dialog_content = "我只是在懷疑，真的有人會綁架他那種人嗎？",
  ui_story_5028_50280801_33_dialog_content = "一事無成，還是個酒鬼，口袋裡連半個白夜幣都存不住......",
  ui_story_5028_50280801_34_dialog_content = "他好歹也是妳師父，要不要那麼嫌棄......",
  ui_story_5028_50280801_35_dialog_content = "接下來該怎麼辦？",
  ui_story_5028_50280801_36_dialog_content = "不找到師父的話，我也沒辦法順利出師成為神奇動物專家。",
  ui_story_5028_50280801_37_dialog_content = "所以，還是先找到他吧。",
  ui_story_5028_50280801_38_dialog_content = "那就先在附近找找線索，看看能不能發現維克先生的行蹤。",
  ui_story_5028_50280801_39_dialog_content = "哼，師父這個傢伙，真不讓人省心。",
  ui_story_5028_50280801_40_dialog_content = "讓我來找找線索吧！",
  ui_story_5028_50280801_41_dialog_content = "<color=#e8d9bb>匡啷——！</color>",
  ui_story_5028_50280801_42_dialog_content = "<color=#e8d9bb>啪——！喀嚓——！</color>",
  ui_story_5028_50280801_43_dialog_content = "停停停，快停下！",
  ui_story_5028_50280801_44_dialog_content = "妳這哪是找線索，分明是在破壞現場！",
  ui_story_5028_50280801_45_dialog_content = "我......我不就是在尋找線索的時候不小心摔壞了幾樣東西嗎？",
  ui_story_5028_50280801_46_dialog_content = "再這樣下去，我怕妳會把整個房子都拆了。",
  ui_story_5028_50280801_47_dialog_content = "菲雅才不會做那種粗暴的事呢！",
  ui_story_5028_50280801_48_dialog_content = "還是我來吧......",
  ui_story_5028_50280801_49_dialog_content = "不然整座屋子都要被妳拆掉。",
  ui_story_5028_50280801_50_dialog_content = "你——！",
  ui_story_5028_50280801_51_dialog_content = "到頭來還是要再多忙一陣。",
  ui_story_5028_50280801_52_dialog_content = "該從哪裡開始找呢？",
  ui_story_5028_50280801_53_option_content = "看看書桌附近",
  ui_story_5028_50280801_54_dialog_content = "書桌的抽屜全都拉開了，裡面的東西也被翻得亂糟糟的......",
  ui_story_5028_50280801_55_dialog_content = "雖然平時師父也會把東西隨手塞進抽屜裡，但他會按照抽屜進行分類。",
  ui_story_5028_50280801_56_dialog_content = "這個空著的抽屜是裝什麼的？",
  ui_story_5028_50280801_57_dialog_content = "我想想，好像是一些關於神奇動物的手稿。",
  ui_story_5028_50280801_58_dialog_content = "之前師父把凱羅交給我時，也是先拿出那些手稿看了一會，才最終作出決定的。",
  ui_story_5028_50280801_59_dialog_content = "那些手稿現在都不見了......",
  ui_story_5028_50280801_60_dialog_content = "等等，書桌下面有一張紙條？",
  ui_story_5028_50280801_61_dialog_content = "快讓我看看！",
  ui_story_5028_50280801_62_dialog_content = "上面畫了一個圈，圈裡打了一個叉......",
  ui_story_5028_50280801_63_dialog_content = "筆跡倉促，墨水還沒有干透，是不久之前畫的！",
  ui_story_5028_50280801_64_dialog_content = "這是某種暗號嗎？",
  ui_story_5028_50280801_65_dialog_content = "我不清楚......",
  ui_story_5028_50280801_66_option_content = "看看書架附近",
  ui_story_5028_50280801_67_dialog_content = "書架上的書倒是還整整齊齊地放著。",
  ui_story_5028_50280801_68_dialog_content = "不過，師父並不經常看這裡放著的書，也不喜歡打掃，所以書上落了不少灰。",
  ui_story_5028_50280801_69_dialog_content = "你看，最上層那本書上沒有灰塵，像是被經常翻閱的樣子。",
  ui_story_5028_50280801_70_dialog_content = "我來把它拿下來看看。",
  ui_story_5028_50280801_71_dialog_content = "可惡，夠不到！",
  ui_story_5028_50280801_72_dialog_content = "噗！",
  ui_story_5028_50280801_73_dialog_content = "不許笑！",
  ui_story_5028_50280801_74_dialog_content = "那個誰，PlayerName，你個子高，把它拿下來看看。",
  ui_story_5028_50280801_75_dialog_content = "嘿咻——！",
  ui_story_5028_50280801_76_dialog_content = "咦？這本書裡竟然夾著一張舊照片。",
  ui_story_5028_50280801_77_dialog_content = "這張照片上是維克師父，但是另一半被撕掉了......",
  ui_story_5028_50280801_78_dialog_content = "師父那傢伙一直留著它，說明它很重要。",
  ui_story_5028_50280801_79_dialog_content = "照片上的另一個人感覺很可疑啊......到底是誰呢？",
  ui_story_5028_50280801_80_dialog_content = "找了半天，我的腿都要站麻了，線索卻只有這麼一點......",
  ui_story_5028_50280801_81_dialog_content = "怎麼辦呢？",
  ui_story_5028_50280801_82_dialog_content = "……",
  ui_story_5028_50280801_83_dialog_content = "那個，菲雅......",
  ui_story_5028_50280801_84_dialog_content = "妳有沒有覺得背後發涼？",
  ui_story_5028_50280801_85_dialog_content = "我......好像感受到了......",
  ui_story_5028_50280801_86_dialog_content = "妳們……",
  ui_story_5028_50280801_87_dialog_content = "噫！！！",
  ui_story_5028_50280801_88_dialog_content = "是，是那個怪傢伙！",
  ui_story_5028_50280801_89_dialog_content = "想要盜竊的話，儘管把值錢的物品拿走就好了，雖然這裡並沒有貴重的東西。",
  ui_story_5028_50280801_90_dialog_content = "但是，把屋子弄成這樣，簡直不可饒恕。",
  ui_story_5028_50280801_91_dialog_content = "要把弄亂的書籍按照類別歸位，非常麻煩。",
  ui_story_5028_50280801_92_dialog_content = "收藏櫃的門敞著，藏品都落了灰，想要清理乾淨至少要花幾天。",
  ui_story_5028_50280801_93_dialog_content = "更可惡的是，連我耗費幾年整理的神奇動物分布圖和珍貴的手稿都不見了。",
  ui_story_5028_50280801_94_dialog_content = "是，是很可惡！",
  ui_story_5028_50280801_95_dialog_content = "這位......女士，妳冷靜一點！",
  ui_story_5028_50280801_96_dialog_content = "我們一定會找出——",
  ui_story_5028_50280801_97_dialog_content = "不。",
  ui_story_5028_50280801_98_dialog_content = "這些珍貴的資料是無價的，你們賠償不起。",
  ui_story_5028_50280801_99_dialog_content = "等一下？！不是我們幹的！",
  ui_story_5028_50280801_100_dialog_content = "沒錯，我們回來的時候發現維克師父不見了，這裡也變得亂七八糟！",
  ui_story_5028_50280801_101_dialog_content = "我只是在找線索的時候不小心弄壞了一把椅子、兩個花瓶、三個玻璃杯......",
  ui_story_5028_50280801_102_dialog_content = "我求求妳少說兩句！",
  ui_story_5028_50280801_103_dialog_content = "人贓俱獲，你們還是不要浪費精力狡辯了。",
  ui_story_5028_50280801_104_dialog_content = "我本來以為你們只是普通的神奇動物愛好者，但沒想到你們竟然是罪犯。",
  ui_story_5028_50280801_105_dialog_content = "老老實實地賠償我的損失。",
  ui_story_5028_50280801_110_dialog_content = "你這暴力女倒是好好聽人說話啊，都說過不是我們了！",
  ui_story_5028_50280801_112_dialog_content = "咿呀——？！",
  ui_story_5028_50280801_113_dialog_content = "幹什麼呀！怎麼一言不合就開打？",
  ui_story_5028_50280801_114_dialog_content = "我也不想打，畢竟就算只是動動手指和觸手也很累。",
  ui_story_5028_50280801_X114_dialog_content = "所以請你們快點交代吧。",
  ui_story_5028_50280801_115_dialog_content = "真的不是我們——",
  ui_story_5028_50280801_116_dialog_content = "噫！！！",
  ui_story_5028_50280801_117_dialog_content = "<color=#e8d9bb>轟——！</color>",
  ui_story_5028_50280801_118_dialog_content = "被，被觸手砸過的地板上，出現了一個大坑......",
  ui_story_5028_50280801_119_dialog_content = "要是被打中，命都沒了吧！",
  ui_story_5028_50280801_120_dialog_content = "是啊，會非常痛。",
  ui_story_5028_50280801_121_dialog_content = "快停下啊，我們沒有想偷東西！",
  ui_story_5028_50280801_122_dialog_content = "我們只是想尋找線索，找到失蹤的維克先生！",
  ui_story_5028_50280801_123_dialog_content = "師父失蹤了？但如果不是你們，還能是誰呢？",
  ui_story_5028_50280801_124_dialog_content = "我們也不知道......",
  ui_story_5028_50280801_125_dialog_content = "但是我們有線索！",
  ui_story_5028_50280801_126_dialog_content = "線索？找線索很麻煩，推理更麻煩，但我不介意聽聽看。",
  ui_story_5028_50280801_127_dialog_content = "說吧，你們都找到了什麼？",
  ui_story_5028_50280801_128_dialog_content = "師父在一張紙條上畫了一個裡面打叉的圈，而且是不久前才畫的！",
  ui_story_5028_50280801_129_dialog_content = "是的，我們還在一本書裡發現了這張照片。",
  ui_story_5028_50280801_130_dialog_content = "等等，妳管維克叫「師父」？",
  ui_story_5028_50280801_131_dialog_content = "沒錯！",
  ui_story_5028_50280801_132_dialog_content = "我跟著他學習了一段時間，現在已經做完了他交代的任務，馬上就可以出師了！",
  ui_story_5028_50280801_133_dialog_content = "證據就是這隻凱羅喔，是臭師父將牠交給我並讓我照顧牠的！",
  ui_story_5028_50280801_134_dialog_content = "凱羅呢？",
  ui_story_5028_50280801_135_dialog_content = "囉？囉囉......",
  ui_story_5028_50280801_136_dialog_content = "原來在這裡，你怎麼在書堆裡睡著了，快出來呀！",
  ui_story_5028_50280801_137_dialog_content = "確實是維克養的凱羅，而且並沒有對妳表現出排斥......",
  ui_story_5028_50280801_138_dialog_content = "既然神奇動物都相信妳，那我也沒有再懷疑妳的必要了。",
  ui_story_5028_50280801_139_dialog_content = "這回相信了吧！",
  ui_story_5028_50280801_140_dialog_content = "唉，看來我外出尋找神奇動物的這段時間裡，他又沒少惹麻煩。",
  ui_story_5028_50280801_141_dialog_content = "明明照顧孩子最麻煩了。",
  ui_story_5028_50280801_142_dialog_content = "我已經不是小孩子了！",
  ui_story_5028_50280801_143_dialog_content = "妳到底是誰？為什麼一副對维克師父很瞭解的樣子？",
  ui_story_5028_50280801_144_dialog_content = "我是誰？是啊，我是誰呢......",
  ui_story_5028_50280801_145_dialog_content = "人際關係太複雜了，記起來很累......",
  ui_story_5028_50280801_146_dialog_content = "但是，如果維克是你的師父，那我應該算是你的師姐。",
  ui_story_5028_50280801_147_dialog_content = "我的名字，叫做<color=#FFB400>詩燁</color>。",
  ui_story_5028_50280801_148_dialog_content = "詩燁",
  ui_story_5028_50280801_X148_dialog_content = "21歲",
  ui_story_5028_50280801_X149_dialog_content = "神祕的章鱼少女",
  ui_story_5028_50280801_149_dialog_content = "師姐？！為什麼師父從來沒告訴過我。",
  ui_story_5028_50280801_150_dialog_content = "那個人一向如此，從來不把事情說清楚。",
  ui_story_5028_50280801_151_dialog_content = "有時候我也無法確定，他教給我的知識和他瞞著我的事情，究竟哪個更多一些。",
  ui_story_5028_50280801_152_dialog_content = "與他相處，是一件非常麻煩的事情。",
  ui_story_5028_50280801_153_dialog_content = "真是辛苦妳了。",
  ui_story_5028_50280801_154_dialog_content = "沒關係，我已經習慣了。",
  ui_story_5028_50280801_155_dialog_content = "說回正題吧，我不太清楚這張照片的意思。",
  ui_story_5028_50280801_156_dialog_content = "或許維克說過有關於它的事情，但是我已經忘記了。",
  ui_story_5028_50280801_157_dialog_content = "喂，妳不是記憶力很好嗎？",
  ui_story_5028_50280801_158_dialog_content = "明明面對那麼多罕見的神奇動物，妳都能記住牠們的習性和特點！",
  ui_story_5028_50280801_159_dialog_content = "記住關於神奇動物之外的事，很麻煩。",
  ui_story_5028_50280801_160_dialog_content = "喂！",
  ui_story_5028_50280801_161_dialog_content = "但是，這個符號我認得。",
  ui_story_5028_50280801_162_dialog_content = "這是維克留下的暗號，代表他被綁架了。",
  ui_story_5028_50280801_163_dialog_content = "附近經常有強盜光顧，所以維克有時候會留下暗號，讓我去救他。",
  ui_story_5028_50280801_164_dialog_content = "果然是綁架！",
  ui_story_5028_50280801_165_dialog_content = "完了，一會不會有綁架信送過來吧？",
  ui_story_5028_50280801_166_dialog_content = "「想要救妳師父，就交出一千萬白夜幣」什麼的，我可付不起......",
  ui_story_5028_50280801_167_dialog_content = "萬一師父被撕票，我豈不是永遠也沒辦法出師了！",
  ui_story_5028_50280801_168_dialog_content = "重點不在於能不能出師吧！！！",
  ui_story_5028_50280801_169_dialog_content = "很奇怪，我想不通。",
  ui_story_5028_50280801_170_dialog_content = "平時也有不少強盜來搶劫維克，但是他很窮，一分錢都沒有。",
  ui_story_5028_50280801_171_dialog_content = "他們一般都只會大鬧一通然後離開，再過分一點也不過是把維克揍上一頓。",
  ui_story_5028_50280801_172_dialog_content = "這一次，闖進這裡的人卻把維克劫走了？",
  ui_story_5028_50280801_173_dialog_content = "為什麼要做這種吃力不討好的事情呢？",
  ui_story_5028_50280801_174_dialog_content = "明明維克只會消耗食物和水，值錢的東西什麼都拿不出來。",
  ui_story_5028_50280801_175_dialog_content = "我是該心疼一下那些綁架犯，還是應該心疼一下妳們的師父？",
  ui_story_5028_50280801_176_dialog_content = "你啊......遇到這麼多麻煩的事情，我建議你還是先心疼一下自己。",
  ui_story_5028_50280801_177_dialog_content = "說，說得也對。",
  ui_story_5028_50280801_178_dialog_content = "到底會是誰呢，難不成......",
  ui_story_5028_50280801_179_dialog_content = "糟了。",
  ui_story_5028_50280801_180_dialog_content = "喂！等一下！",
  ui_story_5028_50280801_181_dialog_content = "維克師父到底是被誰抓走了？喂！！！",
  ui_story_5028_50280801_182_dialog_content = "這麼短的時間內，竟然消失了......",
  ui_story_5028_50280801_183_dialog_content = "臭師父失蹤，師姐又丟下一句話跑走了。",
  ui_story_5028_50280801_184_dialog_content = "這兩個人真是的，為什麼總是不好好把話說清楚啊！",
  ui_story_5028_50280801_185_dialog_content = "先追上詩燁再說吧。",
  ui_story_5028_50280801_186_dialog_content = "她似乎向著城鎮的方向跑去了，我們跟上。",
  ui_story_5028_50280801_187_dialog_content = "城裡人多，總有人能看見她的行蹤。",
  ui_story_5028_50280801_188_dialog_content = "嗯！",
  ui_story_5028_50280901_1_dialog_content = "請問，你看見過一個白色頭髮、長著章魚腕足的年輕女性嗎？",
  ui_story_5028_50280901_4_dialog_content = "哎呀，這不是菲雅嗎？",
  ui_story_5028_50280901_5_dialog_content = "妳身邊的這位是？",
  ui_story_5028_50280901_6_dialog_content = "嗯？這不是那個賣報紙的小傢伙嗎？",
  ui_story_5028_50280901_7_dialog_content = "我身邊的這個人是PlayerName，是本「神奇動物專家」的搭檔。",
  ui_story_5028_50280901_8_dialog_content = "我們正在找人喔，你有什麼線索嗎？",
  ui_story_5028_50280901_12_dialog_content = "年輕女性的話我不清楚，但是你的師父維克好像遇到麻煩了！",
  ui_story_5028_50280901_13_dialog_content = "是的，本「神奇動物專家」已經知道他失蹤了，我們正在到處找他。",
  ui_story_5028_50280901_14_dialog_content = "果然……",
  ui_story_5028_50280901_15_dialog_content = "不久之前，我看到一個長得很高的男人把他劫走了。",
  ui_story_5028_50280901_16_dialog_content = "我已經將這件事告訴給影主的手下，不知道他們有沒有做些什麼......",
  ui_story_5028_50280901_17_dialog_content = "你還記得那個人長什麼樣嗎？",
  ui_story_5028_50280901_18_dialog_content = "抱歉，我只看到一個很高的背影扛著妳的師父往城外走去，沒看清他的樣子。",
  ui_story_5028_50280901_19_dialog_content = "但他穿的衣服我有印象，很像在附近出沒的強盜。",
  ui_story_5028_50280901_20_dialog_content = "強盜？",
  ui_story_5028_50280901_21_dialog_content = "本「神奇動物專家」知道了，剩下的事情，就交給我吧。",
  ui_story_5028_50280901_22_dialog_content = "千萬不要莽撞啊，菲雅。",
  ui_story_5028_50280901_23_dialog_content = "實在不行的話，就出一些錢，請影主幫忙吧......",
  ui_story_5028_50280901_24_dialog_content = "別擔心，我們能搞定這一切的。",
  ui_story_5028_50280901_25_dialog_content = "那就好，我先走了。",
  ui_story_5028_50280901_26_dialog_content = "唉，我也想找人幫忙啊......",
  ui_story_5028_50280901_27_dialog_content = "可是，師父根本一分錢都拿不出來。",
  ui_story_5028_50280901_28_dialog_content = "僅憑我們兩個，真的能對付那些強盜嗎？",
  ui_story_5028_50280901_29_dialog_content = "什麼叫「僅憑我們兩個」？",
  ui_story_5028_50280901_30_dialog_content = "別忘了，我可是「神奇動物專家」，有這麼多神奇動物夥伴！",
  ui_story_5028_50280901_31_dialog_content = "佩可佩可！",
  ui_story_5028_50280901_32_dialog_content = "咕嘰——",
  ui_story_5028_50280901_33_dialog_content = "嗯，嗯！我知道啦，你們也想救師父！",
  ui_story_5028_50280901_34_dialog_content = "只要有你們幫忙，就一定會成功的。",
  ui_story_5028_50280901_35_dialog_content = "囉囉——",
  ui_story_5028_50280901_36_dialog_content = "雖然我聽不懂你在說什麼，但我一定會努力救出師父！",
  ui_story_5028_50280901_37_dialog_content = "執著於知識的奇怪強盜，拐走了窮困潦倒的維克先生......",
  ui_story_5028_50280901_38_dialog_content = "怎麼才能發現他們的行蹤呢？",
  ui_story_5028_50280901_39_dialog_content = "難道真的要去求助影主嗎？",
  ui_story_5028_50280901_40_dialog_content = "一定有更好的辦法。",
  ui_story_5028_50280901_41_dialog_content = "我想想......",
  ui_story_5028_50280901_42_dialog_content = "如果是強盜的話，除了搶劫目標，應該也會關注其他強盜的情報。",
  ui_story_5028_50280901_43_dialog_content = "畢竟這些傢伙不會遵守法律，只會爭搶地盤。",
  ui_story_5028_50280901_44_dialog_content = "如果能抓到一個強盜，審問一番，應該能夠得到線索！",
  ui_story_5028_50280901_45_dialog_content = "可是，要怎麼才能找一個強盜來呢？",
  ui_story_5028_50280901_46_dialog_content = "啊？找強盜？",
  ui_story_5028_50280901_47_dialog_content = "那簡單！",
  ui_story_5028_50280901_48_dialog_content = "菲雅和PlayerName只要假扮成好騙的有錢人就可以了！",
  ui_story_5028_50280901_49_dialog_content = "比如——",
  ui_story_5028_50280901_50_dialog_content = "妳，妳該不會想......",
  ui_story_5028_50280901_51_dialog_content = "不可以！我不同意！",
  ui_story_5028_50280901_52_dialog_content = "我從出土至今才攢夠這麼多白夜幣啊！！！",
  ui_story_5028_50280901_53_dialog_content = "PlayerName哥哥，你難道不想救維克師父了嗎？",
  ui_story_5028_50280901_54_dialog_content = "……",
  ui_story_5028_50280901_55_dialog_content = "你希望菲雅永遠也無法出師成為神奇動物專家嗎？",
  ui_story_5028_50280901_56_dialog_content = "…………",
  ui_story_5028_50280901_57_dialog_content = "嗚嗚，菲雅知道了，菲雅這就走。",
  ui_story_5028_50280901_58_dialog_content = "菲雅一個人去救師父，就算被強盜抓起來也不會來求助PlayerName的！",
  ui_story_5028_50280901_X58_dialog_content = "嗚哇！！！",
  ui_story_5028_50280901_X59_dialog_content = "…………",
  ui_story_5028_50280901_X60_dialog_content = "可惡啊！！！",
  ui_story_5028_50280901_59_dialog_content = "<color=#e8d9bb>一段時間後</color>",
  ui_story_5028_50280901_60_dialog_content = "雲島特產、蘋果糖、鯛魚燒——",
  ui_story_5028_50280901_61_dialog_content = "這位客官，要來點什麼？",
  ui_story_5028_50280901_62_dialog_content = "你這裡的所有小吃，每樣來十份，他出錢！",
  ui_story_5028_50280901_63_dialog_content = "嗯，我，我出......！",
  ui_story_5028_50280901_64_dialog_content = "客官爽快！這就給您準備！",
  ui_story_5028_50280901_65_dialog_content = "哇，這麼多好吃的！",
  ui_story_5028_50280901_66_dialog_content = "（為什麼我要同意她假裝有錢人的計畫！）",
  ui_story_5028_50280901_67_dialog_content = "（花這麼多錢，回去一定會被薇絲審問的！）",
  ui_story_5028_50280901_68_dialog_content = "唔姆唔姆，這個真好吃！",
  ui_story_5028_50280901_69_dialog_content = "再來一份！",
  ui_story_5028_50280901_70_dialog_content = "馬上就來！",
  ui_story_5028_50280901_71_dialog_content = "（啊......又要多打十天工了......）",
  ui_story_5028_50280901_72_dialog_content = "……",
  ui_story_5028_50280901_73_dialog_content = "（這個人，好像在盯著我們？）",
  ui_story_5028_50280901_74_dialog_content = "有人在盯著我們看，好像是強盜上鈎了。",
  ui_story_5028_50280901_75_dialog_content = "正好我也吃飽啦，那就執行下一步計畫。",
  ui_story_5028_50280901_76_dialog_content = "咳咳！",
  ui_story_5028_50280901_77_dialog_content = "真是不錯的美食，接下來我們去逛街吧？",
  ui_story_5028_50280901_78_dialog_content = "當然啦，如果我有什麼想買的東西，你也會付錢吧？",
  ui_story_5028_50280901_79_dialog_content = "有，有這項計畫嗎？！",
  ui_story_5028_50280901_80_dialog_content = "<size=45>咳咳——！</size>",
  ui_story_5028_50280901_81_dialog_content = "好痛！別踢了，別踢了！",
  ui_story_5028_50280901_82_dialog_content = "我，我知道了，我會的——！",
  ui_story_5028_50280901_83_dialog_content = "不管妳喜歡什麼，我都會買給妳！",
  ui_story_5028_50280901_84_dialog_content = "嗯，這樣才對嘛！",
  ui_story_5028_50280901_85_dialog_content = "（這下徹底解釋不清了！）",
  ui_story_5028_50280901_86_dialog_content = "（薇絲，對不起，我的錢又要花光了......）",
  ui_story_5028_50280901_87_dialog_content = "（臨空者號，對不起，你下個月的維修經費又沒有著落了......）",
  ui_story_5028_50280901_88_dialog_content = "……",
  ui_story_5028_50280901_89_dialog_content = "妳們看，遠處的那個身影，是不是很像PlayerName？",
  ui_story_5028_50280901_90_dialog_content = "那可不只是「很像」，而是「就是」喔。",
  ui_story_5028_50280901_91_dialog_content = "不過他離得太遠了，沒辦法直接套過來，真是可惜。",
  ui_story_5028_50280901_93_dialog_content = "導——航——員——",
  ui_story_5028_50280901_94_dialog_content = "等等我們——",
  ui_story_5028_50280901_95_dialog_content = "這個距離有點遠，隔著這麼一條繁華的街道，他恐怕聽不見吧。",
  ui_story_5028_50280901_96_dialog_content = "廢那麼多話幹什麼，還是直接追上去好了。",
  ui_story_5028_50280901_97_dialog_content = "<color=#e8d9bb>鎮外</color>",
  ui_story_5028_50280901_98_dialog_content = "（雖然說是要逛街，但菲雅卻逐漸走到鎮外人跡罕至的地方了呢......）",
  ui_story_5028_50280901_99_dialog_content = "哼哼，這裡還滿合適。",
  ui_story_5028_50280901_100_dialog_content = "PlayerName，我累了，我們在這裡休息吧！",
  ui_story_5028_50280901_101_dialog_content = "欸，好，好的。",
  ui_story_5028_50280901_102_dialog_content = "不過在這個地方會不會有點危險？",
  ui_story_5028_50280901_103_dialog_content = "有我在，你還怕什麼？",
  ui_story_5028_50280901_104_dialog_content = "你們好像聊得很開心啊。",
  ui_story_5028_50280901_105_dialog_content = "是剛才一直跟著我們的那個傢伙！",
  ui_story_5028_50280901_106_dialog_content = "既然你已經發現，那我也不多說什麼了。",
  ui_story_5028_50280901_107_dialog_content = "看起來很有錢的少爺和小姐，請跟我回去坐坐吧。",
  ui_story_5028_50280901_108_dialog_content = "沒辦法了，PlayerName，我們跟他們走一趟吧。",
  ui_story_5028_50280901_109_dialog_content = "咦？！",
  ui_story_5028_50280901_110_dialog_content = "還是這位小姐識相，來，自己把手背過去讓我們綁好。",
  ui_story_5028_50280901_111_dialog_content = "（這到底是怎麼一回事？我得問清楚！）",
  ui_story_5028_50280901_112_option_content = "（強制感應！）",
  ui_story_5028_50280901_113_dialog_content = "（菲雅，能聽見嗎？到底是怎麼回事！）",
  ui_story_5028_50280901_114_dialog_content = "（唔哇！又，又來這招？！）",
  ui_story_5028_50280901_115_dialog_content = "（你別緊張啊，我只是想搭個順風車，讓這群強盜直接把我們帶到老巢裡去。）",
  ui_story_5028_50280901_116_dialog_content = "（這樣就省得我們再費力氣找了。）",
  ui_story_5028_50280901_117_dialog_content = "（這樣也行？！）",
  ui_story_5028_50280901_118_dialog_content = "（你就等著看我表現吧。現在，我們只需要耐心等待......）",
  ui_story_5028_50280901_119_dialog_content = "今天運氣真不錯，剛才盯上的目標被別的傢伙搶了先。",
  ui_story_5028_50280901_120_dialog_content = "但沒想到後面釣上了大魚，哈哈！",
  ui_story_5028_50280901_121_dialog_content = "都綁好了？那我們就......",
  ui_story_5028_50280901_122_dialog_content = "呃！！！",
  ui_story_5028_50280901_123_dialog_content = "找人真的很麻煩。",
  ui_story_5028_50280901_124_dialog_content = "如果不是必須這麼做，我一點也不想在本該休息的時間出門尋找一群強盜。",
  ui_story_5028_50280901_125_dialog_content = "詩燁？！怎麼又是妳！",
  ui_story_5028_50280901_126_dialog_content = "怎麼又是妳？是啊，怎麼又是你們呢？",
  ui_story_5028_50280901_127_dialog_content = "明明我已經說過，不要再給我找麻煩了。",
  ui_story_5028_50280901_128_dialog_content = "但你們還是自顧自的跟了來，甚至還和強盜混在一起。",
  ui_story_5028_50280901_129_option_content = "我們這明顯是被綁架了吧！",
  ui_story_5028_50280901_130_option_content = "我們這明顯不是「混在一起」吧！",
  ui_story_5028_50280901_131_dialog_content = "這是我們的計畫啦，全都被妳給破壞了！",
  ui_story_5028_50280901_133_dialog_content = "計畫？算了，不管你們做什麼，我還是要繼續做我的事情。",
  ui_story_5028_50280901_134_dialog_content = "只希望你們不會再給我添麻煩。",
  ui_story_5028_50280901_136_dialog_content = "咳......咳咳......該死的，這個女人怎麼這麼強？！",
  ui_story_5028_50280901_137_dialog_content = "弟兄們，我們上，把她給我打趴下！",
  ui_story_5028_50280901_138_dialog_content = "請你們不要給我添麻煩。",
  ui_story_5028_50280901_139_dialog_content = "老老實實地交代維克的下落不好嗎？",
  ui_story_5028_50280901_140_dialog_content = "呃——！",
  ui_story_5028_50280901_141_dialog_content = "說吧，維克到底在哪裡？",
  ui_story_5028_50280901_142_dialog_content = "請快點告訴我，像這樣掐著你的脖子，真的很累。",
  ui_story_5028_50280901_143_dialog_content = "呃......是，是<color=#FFB400>蓋里</color>，還有他手底下的獵人「鐵鞭團」！",
  ui_story_5028_50280901_144_dialog_content = "竟然是他。",
  ui_story_5028_50280901_145_dialog_content = "蓋里？怎麼聽起來那麼耳熟......",
  ui_story_5028_50280901_146_dialog_content = "沒時間糾纏了，得趕快幫蓋里老闆抓住那隻「佩可兔」。",
  ui_story_5028_50280901_147_dialog_content = "我想起來了，之前找佩可兔的時候，遇到的那兩個強盜說的就是這個名字！",
  ui_story_5028_50280901_148_dialog_content = "啊？有嗎？菲雅怎麼一點都不記得了？",
  ui_story_5028_50280901_149_dialog_content = "蓋里......他竟然是導致神奇動物數量減少的罪魁禍首。",
  ui_story_5028_50280901_150_dialog_content = "妳認識那個傢伙？",
  ui_story_5028_50280901_151_dialog_content = "這件事解釋起來很麻煩，況且本來也不關你的事。",
  ui_story_5028_50280901_152_dialog_content = "蓋里藏在哪裡？",
  ui_story_5028_50280901_153_dialog_content = "往，往北走十公里，有一個山洞，那是他的老巢......",
  ui_story_5028_50280901_154_dialog_content = "呃——！！！",
  ui_story_5028_50280901_155_dialog_content = "真是麻煩。",
  ui_story_5028_50280901_156_dialog_content = "喂！妳倒是等等啊！",
  ui_story_5028_50280901_157_dialog_content = "PlayerName，我們跟上！",
  ui_story_5028_50280901_158_dialog_content = "這次可不能跟丟了！",
  ui_story_5028_50280901_159_dialog_content = "好，好的！",
  ui_story_5028_50280901_160_dialog_content = "<color=#e8d9bb>幾分鐘後</color>",
  ui_story_5028_50280901_161_dialog_content = "這裡有好多昏過去的人呢。",
  ui_story_5028_50280901_162_dialog_content = "哈？這些傢伙怎麼會倒在這裡？",
  ui_story_5028_50280901_163_dialog_content = "斯莫奇認識他們？",
  ui_story_5028_50280901_164_dialog_content = "這些傢伙都是些遊蕩在影鎮附近的強盜，一個兩個都應該送去燒成灰。",
  ui_story_5028_50280901_165_dialog_content = "嗯，這些戰鬥痕跡是剛剛才留下的。",
  ui_story_5028_50280901_166_dialog_content = "如果我們加快速度，應該就能追上PlayerName了。",
  ui_story_5028_50280901_168_dialog_content = "我們也快點走吧。",
  ui_story_5028_50280901_169_dialog_content = "PlayerName，到底在做什麼呢？",
  ui_story_5028_50280901_170_dialog_content = "<color=#e8d9bb>強盜據點外</color>",
  ui_story_5028_50280901_171_dialog_content = "應該就是這裡了吧。",
  ui_story_5028_50280901_172_dialog_content = "呼......妳跑得還真快！",
  ui_story_5028_50280901_173_dialog_content = "那邊那個洞口應該就是強盜據點的入口了吧？",
  ui_story_5028_50280901_174_dialog_content = "等等我們！",
  ui_story_5028_50280901_175_dialog_content = "囉！囉囉！",
  ui_story_5028_50280901_176_dialog_content = "詩燁，妳為什麼指著<color=#FFB400>那邊</color>？",
  ui_story_5028_50280901_177_dialog_content = "那邊有好多神奇動物？！",
  ui_story_5028_50280901_178_dialog_content = "在哪裡？我看看。",
  ui_story_5028_50280901_179_dialog_content = "不只是神奇動物，還有很多暗鬼！",
  ui_story_5028_50280901_180_dialog_content = "嘎嗷！！ ！",
  ui_story_5028_50280901_181_dialog_content = "糟糕，被發現了！",
  ui_story_5028_50280901_182_dialog_content = "去吧，凱羅！",
  ui_story_5028_50280901_183_dialog_content = "唉......又要打架。",
  ui_story_5028_50280902_1_dialog_content = "凱羅！",
  ui_story_5028_50280902_2_dialog_content = "囉囉囉——囉！",
  ui_story_5028_50280902_3_dialog_content = "嘎！",
  ui_story_5028_50280902_4_dialog_content = "小心點，別打到那些神奇動物。",
  ui_story_5028_50280902_5_dialog_content = "牠們是無辜的。",
  ui_story_5028_50280902_6_dialog_content = "佩可——",
  ui_story_5028_50280902_7_dialog_content = "別怕，我不會傷害你的。到這邊來。",
  ui_story_5028_50280902_8_dialog_content = "佩可佩可！！！",
  ui_story_5028_50280902_9_dialog_content = "喂，妳怎麼把牠嚇跑了？！",
  ui_story_5028_50280902_10_dialog_content = "我並不想嚇跑牠，我只是......",
  ui_story_5028_50280902_11_dialog_content = "嘎嗷！！ ！",
  ui_story_5028_50280902_12_dialog_content = "真麻煩！",
  ui_story_5028_50280902_13_dialog_content = "（詩燁好像有些失落？）",
  ui_story_5028_50280902_14_dialog_content = "（而且，不管是敵人的神奇動物，還是菲雅身邊的神奇動物，都不願意靠近詩燁。）",
  ui_story_5028_50280902_15_dialog_content = "暗鬼都已經被打趴下了，那些神奇動物也都被詩燁嚇跑了。",
  ui_story_5028_50280902_16_dialog_content = "哼哼哼，這些傢伙怎麼可能是本神奇動物專家的對手？",
  ui_story_5028_50280902_17_dialog_content = "好奇怪啊，為什麼會有神奇動物和暗鬼混在一起？",
  ui_story_5028_50280902_18_dialog_content = "而且牠們的行為，像是在守衛山洞？",
  ui_story_5028_50280902_X18_dialog_content = "牠們應該是被訓練成這樣的。",
  ui_story_5028_50280902_19_dialog_content = "暗鬼也可以訓練？！",
  ui_story_5028_50280902_20_dialog_content = "我不清楚，但是有傳聞稱，蓋里有一條<color=#FFB400>能夠讓動物聽從指揮的鞭子</color>。",
  ui_story_5028_50280902_21_dialog_content = "那條鞭子，或許也能用來馴服暗鬼吧。",
  ui_story_5028_50280902_22_dialog_content = "畢竟用武力讓他人屈服是那些強盜最擅長的事情。",
  ui_story_5028_50280902_23_dialog_content = "那些神奇動物，難道也是這樣嗎？",
  ui_story_5028_50280902_24_dialog_content = "當然也是被他們用這種方式訓練出來的。",
  ui_story_5028_50280902_25_dialog_content = "強盜不是研究者，他們只會用最簡單粗暴的方式達成目的，不會考慮動物的心情。",
  ui_story_5028_50280902_26_dialog_content = "他們怎麼能這樣！",
  ui_story_5028_50280902_27_dialog_content = "妳也是。",
  ui_story_5028_50280902_28_dialog_content = "妳根本不瞭解神奇動物吧，只是按照書上寫的、維克教的來對待牠們。",
  ui_story_5028_50280902_29_dialog_content = "自稱為「神奇動物專家」，卻自由散漫、任性妄為。",
  ui_story_5028_50280902_30_dialog_content = "在這方面，妳和維克沒什麼區別。",
  ui_story_5028_50280902_31_dialog_content = "我和他才不一樣呢！",
  ui_story_5028_50280902_32_dialog_content = "如果想要反駁的話，那麼，我來問妳幾個問題吧。",
  ui_story_5028_50280902_33_dialog_content = "妳知道泥尊鷹的蛋人工孵化到第二階段溫度需要控制在多少度嗎？",
  ui_story_5028_50280902_34_dialog_content = "我......我記得是30，不對，40度？",
  ui_story_5028_50280902_35_dialog_content = "是42.5度，並且每六小時要翻一次面。",
  ui_story_5028_50280902_36_dialog_content = "還要翻面？！",
  ui_story_5028_50280902_37_dialog_content = "當然，不翻面會導致孵化失敗。",
  ui_story_5028_50280902_38_dialog_content = "我，我當然知道！",
  ui_story_5028_50280902_39_dialog_content = "只要讓我翻翻看那本筆記！",
  ui_story_5028_50280902_40_dialog_content = "連對待妳自稱最重視的神奇動物都要靠打小抄才能矇混過關。",
  ui_story_5028_50280902_41_dialog_content = "妳才是一直在亂來的那個人吧。",
  ui_story_5028_50280902_42_dialog_content = "我、我……",
  ui_story_5028_50280902_43_dialog_content = "嗚哇！！！",
  ui_story_5028_50280902_44_dialog_content = "菲雅？！",
  ui_story_5028_50280902_45_dialog_content = "所以說，小孩子是最麻煩的生物。",
  ui_story_5028_50280902_46_dialog_content = "我不是小孩子！哇！",
  ui_story_5028_50280902_47_dialog_content = "只有小孩子才會否認自己是小孩子。",
  ui_story_5028_50280902_48_dialog_content = "我建議妳趁早收手，帶著妳的寵物們回到該回的地方去。",
  ui_story_5028_50280902_49_dialog_content = "妳別再說了，菲雅要哭個不停了！",
  ui_story_5028_50280902_50_dialog_content = "嗚哇！",
  ui_story_5028_50280902_51_dialog_content = "她變成這樣，你也有責任。",
  ui_story_5028_50280902_52_dialog_content = "欸？",
  ui_story_5028_50280902_53_dialog_content = "不讓任性的小孩子長點記性，她就永遠不會有長進。",
  ui_story_5028_50280902_54_dialog_content = "如果你們依舊像現在一樣魯莽地行動，總有一天，你會惹上更大的麻煩。",
  ui_story_5028_50280902_55_dialog_content = "就像過去的我一樣。",
  ui_story_5028_50280902_56_dialog_content = "嗚！妳，妳給我站住！！",
  ui_story_5028_50280902_57_dialog_content = "這個傢伙怎麼這麼喜歡只把話說一半就走掉！",
  ui_story_5028_50280902_58_dialog_content = "她徑直朝山洞裡走去了。",
  ui_story_5028_50280902_59_dialog_content = "這傢伙明明也只知道自說自話，還說我，我......",
  ui_story_5028_50280902_60_dialog_content = "菲雅，妳還好嗎？",
  ui_story_5028_50280902_61_dialog_content = "囉囉！",
  ui_story_5028_50280902_62_dialog_content = "我，嗚......我是不會輕易放棄的！！！",
  ui_story_5028_50280902_63_dialog_content = "咦？！",
  ui_story_5028_50280902_64_dialog_content = "我的目標可是成為神奇動物專家，怎麼會因為這點嘲笑就放棄？",
  ui_story_5028_50280902_65_dialog_content = "我們也跟上吧！",
  ui_story_5028_50280902_66_dialog_content = "現在守衛洞口的傢伙都被放倒了，我們偷偷潛入進去，救出師父！",
  ui_story_5028_50280902_67_dialog_content = "那傢伙叫詩燁對吧？",
  ui_story_5028_50280902_68_dialog_content = "我一定要向她證明我的本事！",
  ui_story_5028_50281001_1_dialog_content = "這裡就是蓋里的祕密基地嗎？品味可真差。",
  ui_story_5028_50281001_2_dialog_content = "到處都是髒兮兮、空蕩蕩的籠子，而且好臭。",
  ui_story_5028_50281001_3_dialog_content = "恐怕不久之前，這裡關著不少神奇動物吧。",
  ui_story_5028_50281001_4_dialog_content = "這些籠子都已經被打開了，裡面沒有動物。",
  ui_story_5028_50281001_5_dialog_content = "是詩燁把牠們放出來了嗎？",
  ui_story_5028_50281001_6_dialog_content = "等一下……",
  ui_story_5028_50281001_7_dialog_content = "菲雅，小心一點，我感應到有很多神奇動物衝過來了。",
  ui_story_5028_50281001_8_dialog_content = "快躲開，別被撞到！",
  ui_story_5028_50281001_9_dialog_content = "欸？",
  ui_story_5028_50281001_10_dialog_content = "欸——？！",
  ui_story_5028_50281001_11_dialog_content = "等等，這到底是怎麼回事？",
  ui_story_5028_50281001_12_dialog_content = "誰來告訴我一下？！",
  ui_story_5028_50281001_13_dialog_content = "喂，你！這裡究竟發生了什麼？",
  ui_story_5028_50281001_14_dialog_content = "咕嘰——！",
  ui_story_5028_50281001_15_dialog_content = "什，什麼？",
  ui_story_5028_50281001_16_dialog_content = "你說前面有一個滿身殺氣，非常可怕的傢伙？",
  ui_story_5028_50281001_17_dialog_content = "那個人把你們放出來，然後一個人向深處去了？",
  ui_story_5028_50281001_18_dialog_content = "滿身殺氣......",
  ui_story_5028_50281001_19_option_content = "不會是強盜頭目吧？",
  ui_story_5028_50281001_20_dialog_content = "你太天真了，PlayerName。",
  ui_story_5028_50281001_21_dialog_content = "強盜頭目可不會放走神奇動物。",
  ui_story_5028_50281001_22_dialog_content = "也，也對喔。",
  ui_story_5028_50281001_23_dialog_content = "動物們說的大概是詩燁吧。",
  ui_story_5028_50281001_24_dialog_content = "這麼說，之前嚇到不少動物的「可怕的傢伙」，該不會也是她吧......",
  ui_story_5028_50281001_25_option_content = "不會是詩燁吧？",
  ui_story_5028_50281001_26_dialog_content = "原來詩燁在神奇動物眼裡的樣子是「滿身殺氣」的嗎？",
  ui_story_5028_50281001_27_dialog_content = "到也符合她總是臭著一張臉的樣子啦。",
  ui_story_5028_50281001_28_dialog_content = "難怪所有動物都害怕她。",
  ui_story_5028_50281001_29_dialog_content = "先別管那些動物了，牠們看起來沒有受傷，能自己跑。",
  ui_story_5028_50281001_30_dialog_content = "我們繼續去尋找維克師父吧。",
  ui_story_5028_50281001_31_dialog_content = "好。",
  ui_story_5028_50281001_32_dialog_content = "這裡好黑啊，什麼都看不清。",
  ui_story_5028_50281001_33_dialog_content = "那些動物們，之前一直被關在這種地方嗎？",
  ui_story_5028_50281001_34_dialog_content = "真讓人不舒服......",
  ui_story_5028_50281001_35_dialog_content = "哼，這麼快就怕了？你的膽子可真小啊，小～空～裔～？",
  ui_story_5028_50281001_36_dialog_content = "那個，菲雅，看妳背後......",
  ui_story_5028_50281001_37_dialog_content = "想用這招嚇人？很可惜，已經過時了喔。",
  ui_story_5028_50281001_38_dialog_content = "你們......還是跟來了。",
  ui_story_5028_50281001_39_dialog_content = "嗚哇哇？！",
  ui_story_5028_50281001_40_dialog_content = "妳，妳怎麼一聲不吭地就出現在我背後了？！",
  ui_story_5028_50281001_41_dialog_content = "先聲明一下，我，我可沒有被妳嚇到！",
  ui_story_5028_50281001_42_dialog_content = "……",
  ui_story_5028_50281001_43_dialog_content = "詩燁，維克先生沒和妳在一起嗎？",
  ui_story_5028_50281001_44_dialog_content = "他？他還被綁在洞穴深處。",
  ui_story_5028_50281001_45_dialog_content = "那妳為什麼不救他？",
  ui_story_5028_50281001_46_dialog_content = "給他鬆綁太麻煩了，帶著他行動會更加麻煩。",
  ui_story_5028_50281001_47_dialog_content = "喂！這個藉口妳用過太多次了吧！",
  ui_story_5028_50281001_48_dialog_content = "而且，放他自由的話，他說不定會幹出更離譜的事情。",
  ui_story_5028_50281001_49_dialog_content = "他那種散漫的性格，根本就無法保護好神奇動物。",
  ui_story_5028_50281001_50_dialog_content = "這件事，應該交給更專業的人來做。",
  ui_story_5028_50281001_51_dialog_content = "嗯，這點我認同，臭師父他實在是太不靠譜了。",
  ui_story_5028_50281001_52_dialog_content = "這個世界上的神奇動物，還是由我這個神奇動物專家來保護吧！",
  ui_story_5028_50281001_53_dialog_content = "隨妳怎麼想。",
  ui_story_5028_50281001_54_dialog_content = "維克就在裡面，如果你們想救他，那就去吧。",
  ui_story_5028_50281001_55_dialog_content = "但是，不要來妨礙我。",
  ui_story_5028_50281001_56_dialog_content = "這個人一定是小看我吧！",
  ui_story_5028_50281001_57_dialog_content = "可惡......到時候，我一定要讓她驚訝得下巴脫臼！",
  ui_story_5028_50281001_58_dialog_content = "囉——！",
  ui_story_5028_50281001_59_dialog_content = "你也是這麼認為的吧，凱羅？",
  ui_story_5028_50281001_60_dialog_content = "我們走，先去救出師父。",
  ui_story_5028_50281001_61_dialog_content = "<color=#e8d9bb>蓋里的基地·深處</color>",
  ui_story_5028_50281001_62_dialog_content = "維克師父！",
  ui_story_5028_50281001_63_dialog_content = "把自己搞成這樣，還真是狼狽啊。",
  ui_story_5028_50281001_64_dialog_content = "我就勉為其難地給你鬆綁好了。",
  ui_story_5028_50281001_65_dialog_content = "哎呀，我就說嘛，你們一定會來救我的。",
  ui_story_5028_50281001_66_dialog_content = "真是來得太及時了，我的手都已經被綁麻了。",
  ui_story_5028_50281001_67_dialog_content = "這位是？",
  ui_story_5028_50281001_68_dialog_content = "你好，維克先生，我叫PlayerName，是——",
  ui_story_5028_50281001_69_option_content = "被菲雅捕捉的空裔",
  ui_story_5028_50281001_70_dialog_content = "嗯嗯～",
  ui_story_5028_50281001_71_dialog_content = "這就是我捕獲的神奇動物——空裔！",
  ui_story_5028_50281001_72_dialog_content = "全世界僅此一隻。",
  ui_story_5028_50281001_73_option_content = "菲雅的夥伴",
  ui_story_5028_50281001_74_dialog_content = "沒錯，他就是我的神奇動物夥伴之一。",
  ui_story_5028_50281001_75_dialog_content = "是全世界唯一的空裔喔！",
  ui_story_5028_50281001_76_dialog_content = "嗯？妳還真的抓到了啊。",
  ui_story_5028_50281001_77_dialog_content = "那當然了！",
  ui_story_5028_50281001_78_dialog_content = "不僅如此，我還完成了你給我的所有任務！",
  ui_story_5028_50281001_79_dialog_content = "還真厲害啊。",
  ui_story_5028_50281001_80_dialog_content = "那當然，我可是要成為「神奇動物專家」的人，怎麼可能連這點小事都做不到呢？",
  ui_story_5028_50281001_81_dialog_content = "既然妳找到了空裔，那麼接下來的事，就有希望了。",
  ui_story_5028_50281001_82_dialog_content = "接下來的事？",
  ui_story_5028_50281001_83_dialog_content = "沒錯，去完成妳出師前的最後一項任務吧，阻止蓋里的陰謀！",
  ui_story_5028_50281001_84_dialog_content = "停停停！",
  ui_story_5028_50281001_85_dialog_content = "你不是說，只要我完成你給的那些任務，我就可以出師了嗎？",
  ui_story_5028_50281001_86_dialog_content = "完成全部的任務後就會接到隱藏任務，故事一般不都是這麼寫的嗎？",
  ui_story_5028_50281001_87_dialog_content = "我就知道你說的話不可信！",
  ui_story_5028_50281001_88_dialog_content = "你們到底在說什麼......",
  ui_story_5028_50281001_89_dialog_content = "有誰能解釋一下這到底是怎麼回事？",
  ui_story_5028_50281001_90_dialog_content = "維克先生，你和那個叫蓋里的人究竟是什麼關係？他又為什麼要綁架你？",
  ui_story_5028_50281001_91_dialog_content = "這就說來話長了。",
  ui_story_5028_50281001_92_dialog_content = "我和蓋里，曾經也算是朋友。",
  ui_story_5028_50281001_93_dialog_content = "我喜歡神奇動物這一點，在別人看起來很奇怪，所以很少有人願意與我交流。",
  ui_story_5028_50281001_94_dialog_content = "但那傢伙在得知我對神奇動物有所瞭解以後，跑來向我詢問關於神奇動物的知識。",
  ui_story_5028_50281001_95_dialog_content = "我以為自己遇到了難得的知己，就將自己的知識傾囊相授。",
  ui_story_5028_50281001_96_dialog_content = "直到那天，我們兩人在酒館喝酒，在我喝得醉醺醺時，他問——",
  ui_story_5028_50281001_97_dialog_content = "維克，既然你對那些動物非常瞭解。",
  ui_story_5028_50281001_98_dialog_content = "那你知不知道，世界上最強的是什麼動物？",
  ui_story_5028_50281001_99_dialog_content = "最強的......動，動物？",
  ui_story_5028_50281001_100_dialog_content = "哈哈，這你可問對人了，嗝——",
  ui_story_5028_50281001_101_dialog_content = "世界上最強的動物名叫......<color=#FFB400>凱羅</color>！",
  ui_story_5028_50281001_102_dialog_content = "哈哈，如果你能取得牠們的信任，就會......天下無敵！",
  ui_story_5028_50281001_103_dialog_content = "到時候......嗝......拳打迦南城，腳踢白夜城，都......都不是問題！",
  ui_story_5028_50281001_104_dialog_content = "蓋里會問你這個問題，恐怕不只是單純的好奇吧？",
  ui_story_5028_50281001_105_dialog_content = "呵呵，這個問題的答案，我直到現在才明白。",
  ui_story_5028_50281001_106_dialog_content = "就連他接近我的原因，也只是為了一個目的。",
  ui_story_5028_50281001_107_dialog_content = "究竟是什麼？",
  ui_story_5028_50281001_108_dialog_content = "他想要復仇，向神奇動物復仇。",
  ui_story_5028_50281001_109_dialog_content = "為什麼？",
  ui_story_5028_50281001_110_dialog_content = "這一點我就不知道了～",
  ui_story_5028_50281001_111_dialog_content = "畢竟那傢伙自從問過我那個問題以後就消失了。",
  ui_story_5028_50281001_112_dialog_content = "直到這次綁架我，他才再次出現。",
  ui_story_5028_50281001_113_dialog_content = "維克師父，你這麼窮，到底有什麼綁架的價值啊？",
  ui_story_5028_50281001_114_dialog_content = "菲雅，被妳這麼一說，為師我好傷心啊——",
  ui_story_5028_50281001_115_dialog_content = "快說正經的啦！",
  ui_story_5028_50281001_116_dialog_content = "哎唷唷唷！",
  ui_story_5028_50281001_117_dialog_content = "他想知道凱羅這種生物的棲息地。",
  ui_story_5028_50281001_118_dialog_content = "咦？！",
  ui_story_5028_50281001_119_dialog_content = "難道，他真相信凱羅這種動物能讓他變得天下無敵？",
  ui_story_5028_50281001_120_dialog_content = "可是，這難道不是廢柴師父胡說出來騙人的嗎？",
  ui_story_5028_50281001_121_dialog_content = "……",
  ui_story_5028_50281001_122_dialog_content = "如果這件事是真的，放著不管的話，整個世界就危險了......",
  ui_story_5028_50281001_123_dialog_content = "放心啦，放心啦，不會有事的。",
  ui_story_5028_50281001_124_dialog_content = "蓋里就算抓到世界上所有的凱羅，也沒辦法用牠們做出什麼會影響世界的事情。",
  ui_story_5028_50281001_125_dialog_content = "就算放著不管，也不會有問題喔。",
  ui_story_5028_50281001_126_dialog_content = "……",
  ui_story_5028_50281001_127_dialog_content = "<size=50>不行——！</size>",
  ui_story_5028_50281001_128_dialog_content = "即將要成為神奇動物專家的我，不能允許這種事情發生！",
  ui_story_5028_50281001_129_dialog_content = "囉！",
  ui_story_5028_50281001_130_dialog_content = "哎呀呀。",
  ui_story_5028_50281001_131_dialog_content = "那些強盜只想著用神奇動物做壞事，卻一點也不關心牠們是否願意，更不會善待牠們！",
  ui_story_5028_50281001_132_dialog_content = "要是讓凱羅們落進蓋里手中，他也只會用粗暴的武力強迫牠們！",
  ui_story_5028_50281001_133_dialog_content = "讓動物違背天性、強迫牠們做不喜歡的事，我決不允許！",
  ui_story_5028_50281001_134_dialog_content = "嗯......嗯！就是要這種氣勢！",
  ui_story_5028_50281001_135_dialog_content = "那麼，就順著這股氣勢，一鼓作氣地找到蓋里，阻止他的計畫吧！",
  ui_story_5028_50281001_136_dialog_content = "就當是為了凱羅，我就最後再信你一次吧！",
  ui_story_5028_50281001_137_dialog_content = "我會和我的神奇動物夥伴一起解決這次的事件！",
  ui_story_5028_50281001_138_dialog_content = "賭上神奇動物專家之名！",
  ui_story_5028_50281001_139_dialog_content = "凱羅、佩可兔、糯糯粘、比卡還有PlayerName，你們都會幫我的，對吧？",
  ui_story_5028_50281001_140_dialog_content = "囉——！",
  ui_story_5028_50281001_141_dialog_content = "佩可佩可！",
  ui_story_5028_50281001_142_dialog_content = "咕嘰......",
  ui_story_5028_50281001_143_dialog_content = "嗨嗨！",
  ui_story_5028_50281001_144_dialog_content = "呃，好，好的？",
  ui_story_5028_50281001_145_dialog_content = "好，那現在就出發！",
  ui_story_5028_50281001_146_dialog_content = "哎呀，看到你們這麼有精神，那大概也不需要為師的幫助了。",
  ui_story_5028_50281001_147_dialog_content = "那為師就先回家，等待著你們的好消息囉——疼疼疼！！！",
  ui_story_5028_50281001_148_dialog_content = "輕點，輕點......為師的老胳膊老腿可經不住妳這麼拉扯啊！",
  ui_story_5028_50281001_149_dialog_content = "之前是誰說自己是「永遠的十八歲」啊？",
  ui_story_5028_50281001_150_dialog_content = "啊哈，啊哈哈哈......",
  ui_story_5028_50281001_151_dialog_content = "說到底，這件事也是師父你惹出來的麻煩吧？",
  ui_story_5028_50281001_152_dialog_content = "自己惹的麻煩，要自己收拾乾淨才行喔？",
  ui_story_5028_50281001_153_dialog_content = "除非你這樣說——",
  ui_story_5028_50281001_154_dialog_content = "「偉大的神奇動物專家菲雅，請妳幫我對付這些暗鬼吧！」",
  ui_story_5028_50281001_155_dialog_content = "我就可以勉為其難地幫幫你。",
  ui_story_5028_50281001_156_dialog_content = "啊哈哈，唯獨這件事不行喔，必須要等到化解蓋里的陰謀之後。",
  ui_story_5028_50281001_157_dialog_content = "既然這樣，那邊巡邏回來的暗鬼就交給師父來對付好啦！",
  ui_story_5028_50281001_158_dialog_content = "啊哈哈......啊？！",
  ui_story_5028_50281001_159_dialog_content = "嘎嗷嗷！",
  ui_story_5028_50281001_160_dialog_content = "哎唷！救命！！！",
  ui_story_5028_50281001_161_dialog_content = "我一個人可對付不來這些啊！",
  ui_story_5028_50281002_1_dialog_content = "哎唷，我的老腰......",
  ui_story_5028_50281002_2_dialog_content = "果然劇烈運動不適合我呀。",
  ui_story_5028_50281002_3_dialog_content = "也太誇張了吧，明明維克先生看起來和我年紀差不多大。",
  ui_story_5028_50281002_4_dialog_content = "可不要以貌取人喔，PlayerName。",
  ui_story_5028_50281002_5_dialog_content = "雖然我是永遠的十八歲，但我的閱歷要比你豐富得多喔。",
  ui_story_5028_50281002_6_dialog_content = "又來了，每次被人懷疑，臭師父你都會這麼說。",
  ui_story_5028_50281002_7_dialog_content = "但其實這只是騙人的吧！",
  ui_story_5028_50281002_8_dialog_content = "嗚嗚，菲雅妳這麼說，為師很傷心啊。",
  ui_story_5028_50281002_9_dialog_content = "（維克先生要哭了？！）",
  ui_story_5028_50281002_10_dialog_content = "大徒弟拋棄我，小徒弟嫌棄我，為師真的這麼不招人喜歡嗎？",
  ui_story_5028_50281002_11_dialog_content = "難怪詩燁師姐都懶得救你，確實很麻煩。",
  ui_story_5028_50281002_12_dialog_content = "哎呀，妳師姐她可不是懶得救為師，她是在鬧彆扭。",
  ui_story_5028_50281002_13_dialog_content = "鬧，鬧彆扭？",
  ui_story_5028_50281002_14_dialog_content = "究竟是要多彆扭，才會把自己的師父留給強盜任人宰割啊......",
  ui_story_5028_50281002_15_dialog_content = "詩燁那孩子啊，對神奇動物的喜愛可不比你們少。",
  ui_story_5028_50281002_16_dialog_content = "不過，她不太幸運呢。你們應該也注意到她的奇怪之處了吧？",
  ui_story_5028_50281002_17_dialog_content = "難道是指......",
  ui_story_5028_50281002_18_dialog_content = "她的腕足？",
  ui_story_5028_50281002_19_dialog_content = "嗯，也可以這麼說。",
  ui_story_5028_50281002_20_dialog_content = "她不被動物喜歡？",
  ui_story_5028_50281002_21_dialog_content = "沒錯，你的觀察很敏銳。",
  ui_story_5028_50281002_22_dialog_content = "詩燁經歷過一些事故，導致她的雙腿與她身邊那隻章魚的腕足融合。",
  ui_story_5028_50281002_23_dialog_content = "原本的她深受動物喜愛，但在與章魚融合後，動物們開始畏懼她。",
  ui_story_5028_50281002_24_dialog_content = "可能對於動物們來說，那種章魚是陌生又可怕的生物吧。",
  ui_story_5028_50281002_25_dialog_content = "這種轉變讓詩燁深受打擊，但卻沒有消磨她對神奇動物的熱愛。",
  ui_story_5028_50281002_26_dialog_content = "只是從那時開始，詩燁對神奇動物的態度就發生了變化。",
  ui_story_5028_50281002_27_dialog_content = "變成了什麼？",
  ui_story_5028_50281002_28_dialog_content = "你們難道沒有察覺嗎？",
  ui_story_5028_50281002_29_dialog_content = "她確實關心著神奇動物，但......",
  ui_story_5028_50281002_30_dialog_content = "為師在她心中卻被劃分成了「業餘神奇動物愛好者」！",
  ui_story_5028_50281002_31_dialog_content = "她認為為師是不專業的傢伙，還覺得為師的做法只會害了神奇動物們！",
  ui_story_5028_50281002_32_dialog_content = "你們說這合理嗎？",
  ui_story_5028_50281002_33_dialog_content = "……",
  ui_story_5028_50281002_34_dialog_content = "詩燁師姐，真是辛苦妳了......",
  ui_story_5028_50281002_35_dialog_content = "竟然連菲雅也這麼說......",
  ui_story_5028_50281002_36_dialog_content = "不過算了，為師已經習慣被誤會了。",
  ui_story_5028_50281002_37_dialog_content = "總之，詩燁並不認同為師隨性而為的做法，所以她立志成為真正的「神奇動物專家」。",
  ui_story_5028_50281002_38_dialog_content = "專業？究竟怎樣才算是專業？",
  ui_story_5028_50281002_39_dialog_content = "她很認真地參考了許多遠古資料，並且設計了許多觀測神奇動物生態的方法喔。",
  ui_story_5028_50281002_40_dialog_content = "比如給抓到的神奇動物套上腳環再放掉。",
  ui_story_5028_50281002_41_dialog_content = "這樣下一次再專門捕捉這種動物時，就可以根據有腳環的動物數量估算總數了。",
  ui_story_5028_50281002_42_dialog_content = "所以，蒼獅龍腳上的腳環，是詩燁師姐套上去的？",
  ui_story_5028_50281002_43_dialog_content = "哎呀，大概是吧。畢竟除了她，也沒有人會做這種事了。",
  ui_story_5028_50281002_44_dialog_content = "她還設計了許多其他方法喔，不得不說，有些還挺好用的！",
  ui_story_5028_50281002_45_dialog_content = "但是，她對我的錯誤認知並沒有因此消解，甚至還變得更嚴重了！",
  ui_story_5028_50281002_46_dialog_content = "她將事故的起因歸於對神奇動物的不瞭解，以及......我的錯。",
  ui_story_5028_50281002_47_dialog_content = "她認為是為師是個不正經的傢伙，變得非常嫌棄為師！",
  ui_story_5028_50281002_48_dialog_content = "啥？原來是你讓詩燁師姐變成那樣的嗎？",
  ui_story_5028_50281002_49_dialog_content = "才不是呢！是單純的事故喔，事故！",
  ui_story_5028_50281002_50_dialog_content = "詩燁不知道自己從何而來，想要追查自己的身世。",
  ui_story_5028_50281002_51_dialog_content = "為師看她身邊一直跟著一隻小章魚，就建議她從這隻章魚的棲息地開始查起。",
  ui_story_5028_50281002_52_dialog_content = "誰知道她竟然孤身一人划船前往了這些章魚棲息的深海，還遭遇了風暴......",
  ui_story_5028_50281002_53_dialog_content = "最後是那隻小章魚主動與她融合，用牠神奇的再生能力救了詩燁。",
  ui_story_5028_50281002_54_dialog_content = "明明為師只是告訴了她尋找小章魚族群的方法，其他什麼也沒有做錯。",
  ui_story_5028_50281002_55_dialog_content = "哼，就算你擺出這幅要哭的表情，我也不會同情你。",
  ui_story_5028_50281002_56_dialog_content = "就是因為師父的粗心大意，才搞出這麼多麻煩事。",
  ui_story_5028_50281002_57_dialog_content = "想要將功補過的話，就立刻帶我們去找凱羅的棲息地，阻止蓋里的邪惡計畫吧！",
  ui_story_5028_50281002_58_dialog_content = "唉，明明是我的徒弟，菲雅卻一點也不懂得尊師重道呢。",
  ui_story_5028_50281002_59_dialog_content = "為師明明已經被綁了這麼久，卻還要我餓著肚子帶路什麼的......",
  ui_story_5028_50281002_60_dialog_content = "師父餓了？",
  ui_story_5028_50281002_61_dialog_content = "那這個大餅給你吃吧！",
  ui_story_5028_50281002_62_dialog_content = "嗯？這麵粉的香氣，這金黃的色澤......那為師就不客氣了！",
  ui_story_5028_50281002_63_dialog_content = "唔姆唔姆，就算是沒有味道的大餅，在餓肚子的時候也會變得美味！",
  ui_story_5028_50281002_64_dialog_content = "為什麼這個餅看起來有點眼熟......不對，為什麼菲雅會隨身攜帶大餅啊？！",
  ui_story_5028_50281002_65_dialog_content = "這是菲雅考慮到綁架師父的壞人不會給師父飯吃。",
  ui_story_5028_50281002_66_dialog_content = "所以特地準備的儲備物資喔！",
  ui_story_5028_50281002_67_dialog_content = "唔姆唔姆，不愧是為師的徒弟，想得真周到！",
  ui_story_5028_50281002_68_dialog_content = "不過，這張大餅已經是好幾天前買的了，希望沒有壞掉......",
  ui_story_5028_50281002_69_dialog_content = "唔姆......噗咳咳咳！！！",
  ui_story_5028_50281002_70_dialog_content = "維克先生？！",
  ui_story_5028_50281002_71_dialog_content = "咳咳咳......我，我沒事，至少現在沒什麼事。",
  ui_story_5028_50281002_72_dialog_content = "師父還要再吃點嗎？菲雅還準備了其他口味的大餅喔！",
  ui_story_5028_50281002_73_dialog_content = "不......不必了，為師已經吃飽了。",
  ui_story_5028_50281002_74_dialog_content = "那麼，我們就出發吧！",
  ui_story_5028_50281002_75_dialog_content = "去阻止壞蛋的陰謀！",
  ui_story_5028_50281002_76_dialog_content = "那些，就是綁架PlayerName的強盜了嗎？",
  ui_story_5028_50281002_77_dialog_content = "看起來，有點奇怪......",
  ui_story_5028_50281002_78_dialog_content = "管他什麼奇怪不奇怪的，衝上去一口氣全都打趴不就好了？",
  ui_story_5028_50281002_79_dialog_content = "真魯莽啊，斯莫奇。",
  ui_story_5028_50281002_80_dialog_content = "一點都不符合貴族的優雅。",
  ui_story_5028_50281002_81_dialog_content = "不要，爭吵。",
  ui_story_5028_50281002_82_dialog_content = "呿……",
  ui_story_5028_50281002_83_dialog_content = "我們，偷偷跟上。找機會，救出PlayerName！",
  ui_story_5028_50281101_1_dialog_content = "<color=#e8d9bb>凱羅的棲息地</color>",
  ui_story_5028_50281101_2_dialog_content = "身手倒是不錯，小丫頭。",
  ui_story_5028_50281101_3_dialog_content = "但是，妳又能堅持多久呢？",
  ui_story_5028_50281101_4_dialog_content = "蓋里",
  ui_story_5028_50281101_X4_dialog_content = "38歲",
  ui_story_5028_50281101_X5_dialog_content = "四處捕捉神奇動物的反派角色",
  ui_story_5028_50281101_5_dialog_content = "竟然利用這些動物攻擊我，你還真是麻煩的傢伙。",
  ui_story_5028_50281101_6_dialog_content = "明明有一身堪稱恐怖的蠻力，能輕輕鬆鬆消滅暗鬼。",
  ui_story_5028_50281101_7_dialog_content = "卻因為那點對這些動物虛情假意的關心而不願意傷害牠們。",
  ui_story_5028_50281101_8_dialog_content = "妳苦苦承受著攻擊，卻又不敢反擊的樣子，還真是可笑。",
  ui_story_5028_50281101_9_dialog_content = "你閉嘴。",
  ui_story_5028_50281101_10_dialog_content = "如果不是因為你，也不會有這麼多麻煩事。",
  ui_story_5028_50281101_11_dialog_content = "更不會有神奇動物成為你的奴隸，被迫與其他動物自相殘殺！",
  ui_story_5028_50281101_12_dialog_content = "奴隸？呵，真可笑。",
  ui_story_5028_50281101_13_dialog_content = "牠們也配被稱為奴隸？牠們只不過是最低賤、最愚蠢的畜生。",
  ui_story_5028_50281101_14_dialog_content = "這些生物，根本就不配存在在這世界上！",
  ui_story_5028_50281101_15_dialog_content = "你給我......閉嘴！！！",
  ui_story_5028_50281101_16_dialog_content = "呼……呼……",
  ui_story_5028_50281101_17_dialog_content = "呃！",
  ui_story_5028_50281101_18_dialog_content = "去吧，殺了她。",
  ui_story_5028_50281101_19_dialog_content = "讓這個小丫頭告別她那點天真的妄想吧。",
  ui_story_5028_50281101_20_dialog_content = "嘎嗷——！",
  ui_story_5028_50281101_21_dialog_content = "不要......",
  ui_story_5028_50281101_22_dialog_content = "阻止牠們！",
  ui_story_5028_50281101_23_dialog_content = "囉！",
  ui_story_5028_50281101_24_dialog_content = "漂亮的一擊，菲雅！",
  ui_story_5028_50281101_25_dialog_content = "哼，你們就盡情地為我的英姿而驚訝吧。",
  ui_story_5028_50281101_26_dialog_content = "詩燁，妳沒事吧？",
  ui_story_5028_50281101_27_dialog_content = "為什麼，你們......",
  ui_story_5028_50281101_28_dialog_content = "放心吧，我們也是來阻止蓋里的！",
  ui_story_5028_50281101_29_dialog_content = "妳的事情，我們都從維克先生那裡知道了。",
  ui_story_5028_50281101_30_dialog_content = "我們會幫妳阻止蓋里的！",
  ui_story_5028_50281101_31_dialog_content = "不行，快跑，不能和他打。",
  ui_story_5028_50281101_32_dialog_content = "這個傢伙，非常麻煩！",
  ui_story_5028_50281101_33_dialog_content = "沒想到妳這小丫頭竟然還叫了幫手。",
  ui_story_5028_50281101_34_dialog_content = "我還以為你會直接逃跑呢，維克。",
  ui_story_5028_50281101_35_dialog_content = "我可不是那麼懦弱的人喔，蓋里。",
  ui_story_5028_50281101_36_dialog_content = "既然你們結成一隊，那我也找些幫手吧。",
  ui_story_5028_50281101_37_dialog_content = "能讓你們都體會到這些畜生的恐怖之處，也算是值得了。",
  ui_story_5028_50281101_X37_dialog_content = "把那些暗鬼也趕過來，你們一起上！",
  ui_story_5028_50281101_38_dialog_content = "吼……",
  ui_story_5028_50281101_39_dialog_content = "給我撕碎他們。",
  ui_story_5028_50281101_40_dialog_content = "是，老大！",
  ui_story_5028_50281101_41_dialog_content = "吼！",
  ui_story_5028_50281101_42_dialog_content = "凱羅，PlayerName，出擊！",
  ui_story_5028_50281101_43_dialog_content = "囉！",
  ui_story_5028_50281101_44_dialog_content = "欸，欸？！還有我？！",
  ui_story_5028_50281101_45_dialog_content = "別愣著了，快指揮！",
  ui_story_5028_50281102_1_dialog_content = "太弱了，真是太弱了。",
  ui_story_5028_50281102_2_dialog_content = "明明擁有這麼多神奇動物，妳卻不知道該怎麼激發牠們的力量。",
  ui_story_5028_50281102_3_dialog_content = "妳這傢伙！",
  ui_story_5028_50281102_4_dialog_content = "讓我來告訴妳吧，想要讓這些生物發揮最強的力量，就要這樣做。",
  ui_story_5028_50281102_5_dialog_content = "快起來，你這懶鬼，給我打趴他們！",
  ui_story_5028_50281102_6_dialog_content = "嗷吼——",
  ui_story_5028_50281102_7_dialog_content = "這是......你馴養的蒼獅龍？",
  ui_story_5028_50281102_8_dialog_content = "嗷吼——！！！",
  ui_story_5028_50281102_9_dialog_content = "囉！",
  ui_story_5028_50281102_10_dialog_content = "快停下！沒有神奇動物會喜歡你這麼做！",
  ui_story_5028_50281102_11_dialog_content = "喜歡？",
  ui_story_5028_50281102_12_dialog_content = "哈哈哈哈哈！我才不需要被這些畜生喜歡！",
  ui_story_5028_50281102_13_dialog_content = "牠們只需要懼怕我、敬畏我、為我賣命就夠了！",
  ui_story_5028_50281102_14_dialog_content = "你太過分了，本神奇動物專家絕不放過你！",
  ui_story_5028_50281102_15_dialog_content = "徒弟太帥了，徒弟加油啊——",
  ui_story_5028_50281102_16_dialog_content = "你的鼓勵除了讓人覺得沒用以外，一點價值也沒有。",
  ui_story_5028_50281102_17_dialog_content = "哎呀，又被徒弟嫌棄了......",
  ui_story_5028_50281102_18_dialog_content = "妳這小鬼個子不高，口氣倒是不小。",
  ui_story_5028_50281102_19_dialog_content = "很可惜，妳沒有能配得上這種口氣的力量。",
  ui_story_5028_50281102_20_dialog_content = "嗷吼——",
  ui_story_5028_50281102_21_dialog_content = "咿呀！",
  ui_story_5028_50281102_22_dialog_content = "菲雅！！！",
  ui_story_5028_50281102_23_dialog_content = "呃！",
  ui_story_5028_50281102_24_dialog_content = "哎呀，完全落入下風了呢......",
  ui_story_5028_50281102_25_dialog_content = "投降，我們投降，請放過我們吧。",
  ui_story_5028_50281102_26_dialog_content = "你這傢伙連反抗都嫌麻煩嗎？",
  ui_story_5028_50281102_27_dialog_content = "因為確實反抗不了啊。",
  ui_story_5028_50281102_28_dialog_content = "菲雅和妳已經不能戰鬥了吧？",
  ui_story_5028_50281102_29_dialog_content = "PlayerName是空裔，不是光靈，並沒有戰鬥能力。",
  ui_story_5028_50281102_30_dialog_content = "而為師的老胳膊老腿也幫不上忙。",
  ui_story_5028_50281102_31_dialog_content = "所以只好投降啦。",
  ui_story_5028_50281102_32_dialog_content = "好歹也要掙扎一下吧......",
  ui_story_5028_50281102_33_dialog_content = "沒辦法，認清現實才是生存之道。",
  ui_story_5028_50281102_34_dialog_content = "你們難道覺得，只要投降，我就會輕輕鬆鬆放你們離開？",
  ui_story_5028_50281102_35_dialog_content = "不，你們還要留下來，見證那個最為重大的時刻。",
  ui_story_5028_50281102_36_dialog_content = "給我綁住他們，帶回去關起來。",
  ui_story_5028_50281102_37_dialog_content = "是，老大！",
  ui_story_5028_50281102_38_dialog_content = "嘿嘿，上次你們讓我們吃了大虧，這次我們會好好「感謝」你們的。",
  ui_story_5028_50281102_39_dialog_content = "囉囉囉——！",
  ui_story_5028_50281102_40_dialog_content = "凱羅！",
  ui_story_5028_50281102_41_dialog_content = "唔！",
  ui_story_5028_50281102_42_dialog_content = "別亂動！",
  ui_story_5028_50281102_43_dialog_content = "輕點綁，我的胳膊很容易抽筋，哎唷唷！",
  ui_story_5028_50281102_44_dialog_content = "呿。",
  ui_story_5028_50281102_45_dialog_content = "完了，徹底陷入絕境了......",
  ui_story_5028_50281102_46_dialog_content = "睜大你們的眼睛，好好看著吧。",
  ui_story_5028_50281102_47_dialog_content = "我會讓所有人知道這些畜生的恐怖，然後把這份恐懼與仇恨，植入每個人心中。",
  ui_story_5028_50281102_48_dialog_content = "哦呀，原來這就是你的目的嗎？",
  ui_story_5028_50281102_49_dialog_content = "為什麼你會對這些神奇動物懷有此等深仇？",
  ui_story_5028_50281102_50_dialog_content = "這不是你這種腦子裡只有動物的人能理解的問題。",
  ui_story_5028_50281102_51_dialog_content = "你只需要知道，這些畜生奪走了我最珍視的東西。",
  ui_story_5028_50281102_52_dialog_content = "最珍視的東西......嗎？",
  ui_story_5028_50281102_53_dialog_content = "真是麻煩。",
  ui_story_5028_50281102_54_dialog_content = "引誘那些畜生的陷阱明明已經做好了一半，卻都讓你們給破壞了。",
  ui_story_5028_50281102_55_dialog_content = "不過沒關係，我還有的是耐心。",
  ui_story_5028_50281102_56_dialog_content = "只要這隻小畜生沒有跑......",
  ui_story_5028_50281102_57_dialog_content = "囉囉囉！！！",
  ui_story_5028_50281102_58_dialog_content = "這是什麼生物？",
  ui_story_5028_50281102_59_dialog_content = "牠雖然樣子奇怪，卻和凱羅有著相同的叫聲。",
  ui_story_5028_50281102_60_dialog_content = "難道也是凱羅嗎？",
  ui_story_5028_50281102_61_dialog_content = "以為師的經驗判斷，這確實是凱羅的同族。",
  ui_story_5028_50281102_62_dialog_content = "另一隻凱羅？為什麼牠長成了這樣？",
  ui_story_5028_50281102_63_dialog_content = "可能性有很多種。",
  ui_story_5028_50281102_64_dialog_content = "發生突變、環境差異、族群不同，都可能導致個體之間樣貌的不同。",
  ui_story_5028_50281102_65_dialog_content = "但牠長得和凱羅完全不一樣，真的是一個物種嗎？",
  ui_story_5028_50281102_66_dialog_content = "導致這種可能性的原因——哎呀，我一時想不起來了。",
  ui_story_5028_50281102_67_dialog_content = "不要在這個時候突然不靠譜啊！",
  ui_story_5028_50281102_68_dialog_content = "呵，珍惜你們最後的快樂時光吧。",
  ui_story_5028_50281102_69_dialog_content = "你到底要做什麼？",
  ui_story_5028_50281102_70_dialog_content = "這些小畜生雖然聽不懂人話，但還是會對同類的叫聲產生反應。",
  ui_story_5028_50281102_71_dialog_content = "囉囉囉——！！！",
  ui_story_5028_50281102_72_dialog_content = "利用這一點，就能把這裡的凱羅都引出來一網打盡，只要加以訓練......",
  ui_story_5028_50281102_73_dialog_content = "哈哈，哈哈哈哈哈！！！",
  ui_story_5028_50281102_74_dialog_content = "整個艾斯特拉的光靈就都會體會到牠們的恐怖！",
  ui_story_5028_50281102_75_dialog_content = "然後，也會感受到和我相同的痛苦。",
  ui_story_5028_50281102_76_dialog_content = "看好他們，別讓他們跑了。",
  ui_story_5028_50281102_77_dialog_content = "是，老大！",
  ui_story_5028_50281102_78_dialog_content = "<color=#e8d9bb>蓋里的基地</color>",
  ui_story_5028_50281102_79_dialog_content = "進去吧！",
  ui_story_5028_50281102_80_dialog_content = "也太粗暴了！",
  ui_story_5028_50281102_81_dialog_content = "等我出去了，一定要狠狠踩你的小腳趾！",
  ui_story_5028_50281102_82_dialog_content = "嗯，氣勢很不錯喔，菲雅。",
  ui_story_5028_50281102_83_dialog_content = "都這個時候了，你還是這幅樣子。",
  ui_story_5028_50281102_84_dialog_content = "沒有危機感的人，真麻煩。",
  ui_story_5028_50281102_85_dialog_content = "閉嘴！再吵就把你們吊起來。",
  ui_story_5028_50281102_86_dialog_content = "……",
  ui_story_5028_50281102_87_dialog_content = "……",
  ui_story_5028_50281102_88_dialog_content = "我才不會聽你的呢，你不讓我說話，我偏要——唔唔唔！",
  ui_story_5028_50281102_89_dialog_content = "還是省點力氣，先想想辦法吧。",
  ui_story_5028_50281102_90_dialog_content = "（該怎麼辦，我一個人實在想不出什麼對策......）",
  ui_story_5028_50281102_91_dialog_content = "（對了！既然不能說話，那就使用感應能力與大家交流吧！）",
  ui_story_5028_50281102_92_dialog_content = "（這樣那些強盜應該就察覺不到我們在商量對策了。）",
  ui_story_5028_50281102_93_option_content = "強制感應！",
  ui_story_5028_50281102_94_dialog_content = "菲雅！能聽得到嗎？",
  ui_story_5028_50281102_95_dialog_content = "嗚哇？！PlayerName，你使用這個能力之前，就不能提前打個招呼嗎？",
  ui_story_5028_50281102_96_dialog_content = "抱歉，但是現在情況緊急！",
  ui_story_5028_50281102_97_dialog_content = "維克先生？",
  ui_story_5028_50281102_98_dialog_content = "哎呀，是空裔的感應能力嗎？真是令人懷念啊。",
  ui_story_5028_50281102_99_dialog_content = "還有詩燁！",
  ui_story_5028_50281102_100_dialog_content = "我聽得到。",
  ui_story_5028_50281102_101_dialog_content = "菲雅，我想和大家商量一下逃跑的方法！",
  ui_story_5028_50281102_102_dialog_content = "跑？該怎麼跑？",
  ui_story_5028_50281102_103_dialog_content = "凱羅已經被抓走了，剩下的神奇動物也沒辦法和強盜正面對抗。",
  ui_story_5028_50281102_104_dialog_content = "你問問詩燁師姐？她雖然很怪，但力氣還挺大的，說不定會有辦法。",
  ui_story_5028_50281102_105_dialog_content = "詩燁，妳有什麼想法嗎？能不能藉助這些神奇動物的力量逃跑？",
  ui_story_5028_50281102_106_dialog_content = "與其讓這些弱小的動物拚命對抗強盜......",
  ui_story_5028_50281102_107_dialog_content = "還不如我自己想辦法掙脫這些麻煩的繩子。",
  ui_story_5028_50281102_108_dialog_content = "只要等我恢復力氣，掙脫它輕而易舉。",
  ui_story_5028_50281102_109_dialog_content = "但是，如果牠們也幫不上忙......維克先生，你有什麼辦法嗎？",
  ui_story_5028_50281102_110_dialog_content = "不要急，PlayerName。",
  ui_story_5028_50281102_111_dialog_content = "現在我們都不能行動，但你可以先用空裔的特殊能力探查四周。",
  ui_story_5028_50281102_112_dialog_content = "我們的命運就都交給你了，PlayerName。",
  ui_story_5028_50281102_113_dialog_content = "不要突然就把命運交給我啊？！",
  ui_story_5028_50281102_114_dialog_content = "但是，我會努力試試看的。",
  ui_story_5028_50281102_115_option_content = "強制感應！",
  ui_story_5028_50281102_116_dialog_content = "……",
  ui_story_5028_50281102_117_dialog_content = "（這附近有巡邏的強盜......）",
  ui_story_5028_50281102_118_dialog_content = "（被關起來的神奇動物......）",
  ui_story_5028_50281102_119_dialog_content = "（好多和凱羅長得一樣的神奇動物？！）",
  ui_story_5028_50281102_120_dialog_content = "維克先生，不好了，這些強盜已經抓到了好多凱羅的同族！",
  ui_story_5028_50281102_121_dialog_content = "哎呀，他竟然真的抓到了？",
  ui_story_5028_50281102_122_dialog_content = "不過沒關係，只要他沒有掌握激發出凱羅能力的方法，就不足為懼。",
  ui_story_5028_50281102_123_dialog_content = "嗯，那我再看看四周。遠處的那一片好像有什麼在動。",
  ui_story_5028_50281102_124_dialog_content = "是藏在雜物堆裡的雷文頓。",
  ui_story_5028_50281102_125_dialog_content = "等等，雷文頓？！",
  ui_story_5028_50281102_126_dialog_content = "PlayerName！你終於注意到我了！",
  ui_story_5028_50281102_127_dialog_content = "明明玩到一半，PlayerName卻消失不見了。",
  ui_story_5028_50281102_128_dialog_content = "是啊，玩到一半，我就被菲雅強行拉走幫忙了......",
  ui_story_5028_50281102_129_dialog_content = "真的非常抱歉！",
  ui_story_5028_50281102_130_dialog_content = "我們找了你好久呢！",
  ui_story_5028_50281102_131_dialog_content = "妳們？還有別人在嗎？我再感應看看！",
  ui_story_5028_50281102_132_dialog_content = "有吉納維芙......",
  ui_story_5028_50281102_133_dialog_content = "PlayerName，跟在你身邊的是新同伴嗎？",
  ui_story_5028_50281102_134_dialog_content = "看來PlayerName還真受歡迎啊。",
  ui_story_5028_50281102_135_dialog_content = "只是一轉瞬，就又套住了這麼多人的心。",
  ui_story_5028_50281102_136_dialog_content = "還有斯莫奇？！她和吉納維芙真的不會吵起來嗎？！",
  ui_story_5028_50281102_137_dialog_content = "嘁，原來是同伴嗎？",
  ui_story_5028_50281102_138_dialog_content = "我還以為能燒個痛快呢。",
  ui_story_5028_50281102_139_dialog_content = "別，別拿我開玩笑啦！",
  ui_story_5028_50281102_140_dialog_content = "太好了，有這麼多人幫忙，一定能扭轉敗局！",
  ui_story_5028_50281102_141_dialog_content = "我現在遇到了點麻煩，需要幫助！",
  ui_story_5028_50281102_142_dialog_content = "當然，PlayerName是我的同伴，我隨時都能幫忙！",
  ui_story_5028_50281102_143_dialog_content = "大家也一樣，都是為了尋找PlayerName才會來的。",
  ui_story_5028_50281102_144_dialog_content = "謝謝！",
  ui_story_5028_50281102_145_dialog_content = "菲雅，詩燁，維克先生，有辦法了！",
  ui_story_5028_50281102_146_dialog_content = "我找到了幫手！",
  ui_story_5028_50281102_147_dialog_content = "哼哼哼，你的動作可真慢！",
  ui_story_5028_50281102_148_dialog_content = "在你磨磨蹭蹭的這段時間裡，我已經想到了一個<color=#FFB400>絕妙的計畫</color>。",
  ui_story_5028_50281102_149_dialog_content = "欸？妳，妳想到計畫了？",
  ui_story_5028_50281102_150_dialog_content = "可別小瞧神奇動物專家。",
  ui_story_5028_50281102_151_dialog_content = "我們可以這样，然後再這样......",
  ui_story_5028_50281201_1_dialog_content = "<color=#e8d9bb>蓋里的基地外</color>",
  ui_story_5028_50281201_2_dialog_content = "你說，老大的計畫真的能成功嗎？",
  ui_story_5028_50281201_3_dialog_content = "噓......小聲點。",
  ui_story_5028_50281201_4_dialog_content = "要是讓老大知道有人懷疑他的計畫，肯定會被掛在樹上晾一天一夜。",
  ui_story_5028_50281201_5_dialog_content = "唉，也不知道那個叫維克的傢伙究竟說了什麼。",
  ui_story_5028_50281201_6_dialog_content = "老大竟然完全相信了他的鬼話！",
  ui_story_5028_50281201_7_dialog_content = "<color=#e8d9bb>嗚——嗚嗚——</color>",
  ui_story_5028_50281201_8_dialog_content = "你聽，是老大下命令的聲音。",
  ui_story_5028_50281201_9_dialog_content = "什麼？說了什麼？",
  ui_story_5028_50281201_10_dialog_content = "<color=#e8d9bb>嗚嗚嗚——嗚嗚——</color>",
  ui_story_5028_50281201_11_dialog_content = "有......有敵襲！",
  ui_story_5028_50281201_12_dialog_content = "從西北邊來的！",
  ui_story_5028_50281201_13_dialog_content = "我們快點過去看看！",
  ui_story_5028_50281201_14_dialog_content = "呼......呼......哪裡有敵人？",
  ui_story_5028_50281201_15_dialog_content = "怎麼回事，這裡明明什麼都沒有！",
  ui_story_5028_50281201_16_dialog_content = "<color=#e8d9bb>嗚嗚——嗚——嗚嗚嗚——</color>",
  ui_story_5028_50281201_17_dialog_content = "怎麼又變成吃早飯的暗號了？！",
  ui_story_5028_50281201_18_dialog_content = "是誰在亂發暗號？",
  ui_story_5028_50281201_19_dialog_content = "太好了，作戰計畫第一步大成功！",
  ui_story_5028_50281201_20_dialog_content = "多虧雷文頓偷來了強盜們的暗號本......",
  ui_story_5028_50281201_21_dialog_content = "吃掉暗號本的佩可兔也立了大功！",
  ui_story_5028_50281201_22_dialog_content = "佩可佩可！",
  ui_story_5028_50281201_23_dialog_content = "接下來看你的了，空裔！",
  ui_story_5028_50281201_24_dialog_content = "雖然有些難為情，但是，在經歷了這麼多意外事件之後——",
  ui_story_5028_50281201_25_dialog_content = "我的逃跑能力可是有了相當大的進步！",
  ui_story_5028_50281201_26_dialog_content = "喂，那邊的蠢強盜，有本事就來抓我啊！",
  ui_story_5028_50281201_27_dialog_content = "什麼？俘虜逃跑了？",
  ui_story_5028_50281201_28_dialog_content = "給我站住！",
  ui_story_5028_50281201_29_dialog_content = "噫！",
  ui_story_5028_50281201_30_dialog_content = "往這邊跑應該沒錯，這裡離凱羅原本的棲息地不遠。",
  ui_story_5028_50281201_31_dialog_content = "剛才去找蓋里的時候，臨空者號就停在那附近，而且......",
  ui_story_5028_50281201_32_dialog_content = "那個追著臨空者號不放的傢伙也在！",
  ui_story_5028_50281201_33_dialog_content = "吼——！",
  ui_story_5028_50281201_34_dialog_content = "你快看那裡！",
  ui_story_5028_50281201_35_dialog_content = "可惡，怎麼會有另一隻蒼獅龍？！",
  ui_story_5028_50281201_36_dialog_content = "嗷吼——",
  ui_story_5028_50281201_37_dialog_content = "呃啊——！！！",
  ui_story_5028_50281201_38_dialog_content = "快去報告老大！",
  ui_story_5028_50281201_39_dialog_content = "好，好的！",
  ui_story_5028_50281201_40_dialog_content = "怪了，明明那隻蒼獅龍已經飛過去了，為什麼這裡還這麼黑？",
  ui_story_5028_50281201_41_dialog_content = "哎唷——！",
  ui_story_5028_50281201_42_dialog_content = "嗨嗨，嗨！",
  ui_story_5028_50281201_43_dialog_content = "好了好了，下回不會讓你吃那麼大的石頭了......",
  ui_story_5028_50281201_44_dialog_content = "是誰在叫喊？發生了什麼事？",
  ui_story_5028_50281201_45_dialog_content = "哎呀！",
  ui_story_5028_50281201_46_dialog_content = "咕嘰嘰......",
  ui_story_5028_50281201_47_dialog_content = "什麼玩意，地上怎麼這麼滑？",
  ui_story_5028_50281201_48_dialog_content = "咕咕！",
  ui_story_5028_50281201_49_dialog_content = "又，又是什麼？！",
  ui_story_5028_50281201_50_dialog_content = "怎麼......這麼想睡......",
  ui_story_5028_50281201_51_dialog_content = "呼啊......",
  ui_story_5028_50281201_52_dialog_content = "計畫進行得很順利。",
  ui_story_5028_50281201_53_dialog_content = "那些小傢伙把強盜們套得牢牢的。",
  ui_story_5028_50281201_54_dialog_content = "沒想到啊，妳還滿有本事的。",
  ui_story_5028_50281201_55_dialog_content = "菲雅畢竟是我的徒弟，優秀也是理所當然的。",
  ui_story_5028_50281201_56_dialog_content = "我可是「神奇動物專家」，怎麼會連這點小事都做不到呢。",
  ui_story_5028_50281201_57_dialog_content = "強盜一個都沒過來。",
  ui_story_5028_50281201_58_dialog_content = "PlayerName，等一下，我這就把籠子打開給你們鬆綁。",
  ui_story_5028_50281201_59_dialog_content = "呼......真是太感謝了。",
  ui_story_5028_50281201_60_dialog_content = "囉！",
  ui_story_5028_50281201_61_dialog_content = "凱羅！太好了，你沒有受傷！",
  ui_story_5028_50281201_62_dialog_content = "第一階段的作戰計畫大獲成功。",
  ui_story_5028_50281201_63_dialog_content = "接下來就是找到蓋里，阻止他的陰謀。",
  ui_story_5028_50281201_64_dialog_content = "菲雅。",
  ui_story_5028_50281201_65_dialog_content = "妳，妳怎麼這樣看著我......",
  ui_story_5028_50281201_66_dialog_content = "不許小瞧我！",
  ui_story_5028_50281201_67_dialog_content = "不，我沒有小瞧妳的意思。",
  ui_story_5028_50281201_68_dialog_content = "說到底，妳仍舊還是個小孩子。",
  ui_story_5028_50281201_69_dialog_content = "都說了，我不是小孩子！",
  ui_story_5028_50281201_70_dialog_content = "要叫我神奇動物專家！",
  ui_story_5028_50281201_71_dialog_content = "隨便吧，這個稱呼實在是太長了，記起來很麻煩。",
  ui_story_5028_50281201_72_dialog_content = "妳這傢伙——！",
  ui_story_5028_50281201_73_dialog_content = "但是，妳用行動證明了自己很瞭解身邊的神奇動物。",
  ui_story_5028_50281201_74_dialog_content = "妳，成長了。",
  ui_story_5028_50281201_75_dialog_content = "欸？",
  ui_story_5028_50281201_76_dialog_content = "妳的意思是認同我了？",
  ui_story_5028_50281201_77_dialog_content = "雖然細節的知識還記得不是很清楚，但，但我可是很有天賦的喔！",
  ui_story_5028_50281201_78_dialog_content = "只要是我的夥伴，我就能瞭解得一清二楚！",
  ui_story_5028_50281201_79_dialog_content = "哈，哈哈哈......知道本神奇動物專家的厲害了吧？",
  ui_story_5028_50281201_80_dialog_content = "不要得意得太早，妳距離被我認同還差得很遠。",
  ui_story_5028_50281201_81_dialog_content = "在獲得我的認同之前，先......",
  ui_story_5028_50281201_82_dialog_content = "我就說這裡怎麼這麼吵，原來是你們這群傢伙搞的鬼。",
  ui_story_5028_50281201_83_dialog_content = "囉——！",
  ui_story_5028_50281201_84_dialog_content = "那個臭大叔回來了！",
  ui_story_5028_50281201_85_dialog_content = "這個傢伙，就是綁架PlayerName的真兇嗎？",
  ui_story_5028_50281201_86_dialog_content = "竟然用暗鬼當手下，還真是低級啊。",
  ui_story_5028_50281201_87_dialog_content = "哎呀？難得小吉納維芙和我意見相同。",
  ui_story_5028_50281201_88_dialog_content = "誰要和妳意見相同啊？！",
  ui_story_5028_50281201_89_dialog_content = "真是讓人不爽的傢伙，乾脆連著這座基地一起燒光好了。",
  ui_story_5028_50281201_90_dialog_content = "哎唷唷，這萬萬不可。",
  ui_story_5028_50281201_91_dialog_content = "這裡可都是蓋里抓來的凱羅，萬一被妳燒光，凱羅們就要遭殃了！",
  ui_story_5028_50281201_92_dialog_content = "哦？竟然還多了幾個人，莫非是豆芽菜你的夥伴？",
  ui_story_5028_50281201_93_dialog_content = "我才不是豆芽菜呢！",
  ui_story_5028_50281201_94_dialog_content = "你們這些傢伙，一個兩個的，為什麼都願意為這些畜生戰鬥？",
  ui_story_5028_50281201_95_dialog_content = "牠們才不是畜生，牠們是我的夥伴！",
  ui_story_5028_50281201_96_dialog_content = "夥伴？哈哈......哈哈哈哈！不，牠們只是畜生。",
  ui_story_5028_50281201_97_dialog_content = "妳把牠們當夥伴，但牠們可不一定這麼認為。",
  ui_story_5028_50281201_98_dialog_content = "哪怕表面無害，畜生終究也只是畜生。",
  ui_story_5028_50281201_99_dialog_content = "一旦牠們認為妳失去了利用價值，就會毫不留情地拋棄妳、殺了妳。",
  ui_story_5028_50281201_100_dialog_content = "歪理邪說！",
  ui_story_5028_50281201_101_dialog_content = "喂，那個小孩子。",
  ui_story_5028_50281201_102_dialog_content = "我叫菲雅！",
  ui_story_5028_50281201_103_dialog_content = "無所謂。這個傢伙已經被不知哪裡來的仇恨觀念蒙昏了頭。",
  ui_story_5028_50281201_104_dialog_content = "想要說服這種人非常麻煩，最直接的說服方法是......",
  ui_story_5028_50281201_105_dialog_content = "是？",
  ui_story_5028_50281201_106_dialog_content = "不知道……？",
  ui_story_5028_50281201_107_dialog_content = "物理說服。",
  ui_story_5028_50281201_108_dialog_content = "哎呀，這個回答果然很有詩燁的風範。",
  ui_story_5028_50281201_109_dialog_content = "想要打架？",
  ui_story_5028_50281201_110_dialog_content = "呵呵，這樣也好。",
  ui_story_5028_50281201_111_dialog_content = "不管一次還是兩次，你們永遠都是我的手下敗將。",
  ui_story_5028_50281201_112_dialog_content = "嘎嗷！！ ！",
  ui_story_5028_50281202_1_dialog_content = "凱羅，去吧！",
  ui_story_5028_50281202_2_dialog_content = "囉——！",
  ui_story_5028_50281202_3_dialog_content = "太遲鈍了。",
  ui_story_5028_50281202_4_dialog_content = "嘎嗷！",
  ui_story_5028_50281202_5_dialog_content = "雷文頓，保護菲雅！",
  ui_story_5028_50281202_6_dialog_content = "不會讓你得逞的！",
  ui_story_5028_50281202_7_dialog_content = "燃索！",
  ui_story_5028_50281202_8_dialog_content = "怎麼樣，我的夥伴們配合得還不錯吧？",
  ui_story_5028_50281202_9_dialog_content = "呃……",
  ui_story_5028_50281202_10_dialog_content = "呵，不過是些小花招，還不夠妳丟人現眼。",
  ui_story_5028_50281202_11_dialog_content = "倒是這些光靈，給我找了不少麻煩。",
  ui_story_5028_50281202_12_dialog_content = "但是，如果是這樣呢？",
  ui_story_5028_50281202_13_dialog_content = "那傢伙的鞭子，散發出了<color=#FFB400>詭異的光芒</color>？！",
  ui_story_5028_50281202_14_dialog_content = "大家小心！",
  ui_story_5028_50281202_15_dialog_content = "囉......囉......！",
  ui_story_5028_50281202_16_dialog_content = "凱羅？凱羅！",
  ui_story_5028_50281202_17_dialog_content = "佩可......",
  ui_story_5028_50281202_18_dialog_content = "你！臭大叔，你做了什麼？！",
  ui_story_5028_50281202_19_dialog_content = "別著急，小鬼。",
  ui_story_5028_50281202_20_dialog_content = "一會妳就能看見妳那可愛的動物朋友撕開妳的肚子的模樣了！",
  ui_story_5028_50281202_21_dialog_content = "我的夥伴才不會這麼做！",
  ui_story_5028_50281202_22_dialog_content = "攻擊他的鞭子！",
  ui_story_5028_50281202_23_dialog_content = "知道了！",
  ui_story_5028_50281202_24_dialog_content = "呀！",
  ui_story_5028_50281202_25_dialog_content = "這個傢伙究竟控制了多少暗鬼......",
  ui_story_5028_50281202_26_dialog_content = "暗鬼這種東西，當然是要多少有多少。",
  ui_story_5028_50281202_27_dialog_content = "就算死了，也會源源不斷地有新的補充進來。",
  ui_story_5028_50281202_28_dialog_content = "大家一起上！",
  ui_story_5028_50281202_29_dialog_content = "<color=#e8d9bb>囉——！</color>",
  ui_story_5028_50281202_30_dialog_content = "是凱羅在叫？",
  ui_story_5028_50281202_31_dialog_content = "<color=#e8d9bb>囉——囉囉——！</color>",
  ui_story_5028_50281202_32_dialog_content = "不，不是我的凱羅！",
  ui_story_5028_50281202_33_dialog_content = "凱羅的叫聲在從四面八方傳來！",
  ui_story_5028_50281202_34_dialog_content = "糟了……",
  ui_story_5028_50281202_35_dialog_content = "他的目標不只是菲雅的神奇動物，而是被所有被帶到這座基地裡的凱羅！！",
  ui_story_5028_50281202_36_dialog_content = "哎呀，這可不妙。",
  ui_story_5028_50281202_37_dialog_content = "不能讓牠們繼續留在這裡了，得有人帶牠們走！",
  ui_story_5028_50281202_38_dialog_content = "詩燁師姐！",
  ui_story_5028_50281202_39_dialog_content = "欸……？",
  ui_story_5028_50281202_40_dialog_content = "妳不是自稱很瞭解神奇動物嗎？",
  ui_story_5028_50281202_41_dialog_content = "現在妳受了傷，也沒辦法幫忙戰鬥，就由妳去帶領牠們逃跑吧！",
  ui_story_5028_50281202_42_dialog_content = "死到臨頭了，也還顧著那些畜生嗎？",
  ui_story_5028_50281202_43_dialog_content = "你們還真是一群怪人。",
  ui_story_5028_50281202_44_dialog_content = "嘎嗷——！",
  ui_story_5028_50281202_45_dialog_content = "弟兄們，一起上！",
  ui_story_5028_50281202_46_dialog_content = "呃！！！",
  ui_story_5028_50281202_47_dialog_content = "讓我看看這次套中了幾個目標，一，二，三......",
  ui_story_5028_50281202_48_dialog_content = "收獲還真不少。",
  ui_story_5028_50281202_49_dialog_content = "妳那速度太慢了，這些傢伙還是一併燒了更痛快。",
  ui_story_5028_50281202_50_dialog_content = "是嗎？那就看看我們兩個人誰套中的獵物更多吧。",
  ui_story_5028_50281202_51_dialog_content = "囉囉囉！！！",
  ui_story_5028_50281202_52_dialog_content = "維克沒有告訴過妳嗎，那些神奇動物，都不願意接近我。",
  ui_story_5028_50281202_53_dialog_content = "那麼本神奇動物專家宣布，這件事即將成為歷史了！",
  ui_story_5028_50281202_54_dialog_content = "什麼……？",
  ui_story_5028_50281202_55_dialog_content = "過來吧，蒼獅龍！",
  ui_story_5028_50281202_56_dialog_content = "嗷吼——！",
  ui_story_5028_50281202_57_dialog_content = "（菲雅她......把那隻龍呼喚了過來。）",
  ui_story_5028_50281202_58_dialog_content = "嗷……",
  ui_story_5028_50281202_59_dialog_content = "抱歉讓你感到難受，但是拜託你了......",
  ui_story_5028_50281202_60_dialog_content = "帶著詩燁去找森林裡的神奇動物，帶著牠們離開這裡！",
  ui_story_5028_50281202_61_dialog_content = "詩燁師姐！",
  ui_story_5028_50281202_62_dialog_content = "……",
  ui_story_5028_50281202_63_dialog_content = "（詩燁慢慢靠近了那隻龍......）",
  ui_story_5028_50281202_64_dialog_content = "......！",
  ui_story_5028_50281202_65_dialog_content = "（太好了，蒼獅龍沒有抗拒詩燁！）",
  ui_story_5028_50281202_66_dialog_content = "竟然真的......",
  ui_story_5028_50281202_67_dialog_content = "可要好好感謝本「神奇動物專家」！",
  ui_story_5028_50281202_68_dialog_content = "快去吧！",
  ui_story_5028_50281202_69_dialog_content = "哈哈......哈哈哈......",
  ui_story_5028_50281202_70_dialog_content = "他怎麼笑了？",
  ui_story_5028_50281202_71_dialog_content = "你們果然只是一群不成器的小鬼。",
  ui_story_5028_50281202_72_dialog_content = "帶著小畜生和一個豆芽菜就敢來妨礙我。",
  ui_story_5028_50281202_73_dialog_content = "雖然有趣的東西一般都要留到最後，但是......",
  ui_story_5028_50281202_74_dialog_content = "提前給你們看看也無妨。",
  ui_story_5028_50281202_75_dialog_content = "出來吧。",
  ui_story_5028_50281202_76_dialog_content = "囉......",
  ui_story_5028_50281202_77_dialog_content = "這是凱羅的聲音？",
  ui_story_5028_50281202_78_dialog_content = "是剛剛那隻凱羅嗎？",
  ui_story_5028_50281202_79_dialog_content = "別，別以為用這種手段就可以嚇到我！",
  ui_story_5028_50281202_80_dialog_content = "囉！",
  ui_story_5028_50281202_81_dialog_content = "噫——？！",
  ui_story_5028_50281202_82_dialog_content = "這這這......這怎麼看都是暗鬼吧？！",
  ui_story_5028_50281202_83_dialog_content = "為什麼牠會發出凱羅的聲音？",
  ui_story_5028_50281202_84_dialog_content = "囉囉囉......囉囉！",
  ui_story_5028_50281202_85_dialog_content = "這個傢伙，確實也是那隻凱羅。",
  ui_story_5028_50281202_86_dialog_content = "凱羅最為強大的力量，就是<color=#FFB400>「擬態」</color>。",
  ui_story_5028_50281202_87_dialog_content = "在同伴的鼓勵之下，牠們能夠變化成任何生物的樣子，並使用相應的能力。",
  ui_story_5028_50281202_88_dialog_content = "這麼重要的事情，你為什麼不早說！",
  ui_story_5028_50281202_89_dialog_content = "哎呀呀，我只是沒想到，凱羅竟然在極度恐懼的狀態下也能使用這種力量。",
  ui_story_5028_50281202_90_dialog_content = "畢竟一般來說，凱羅只會為了保護信任的同伴使用能力。",
  ui_story_5028_50281202_91_dialog_content = "還真是遇到不得了的麻煩了呢。",
  ui_story_5028_50281202_92_dialog_content = "為什麼你到現在還能笑得出來？！",
  ui_story_5028_50281202_93_dialog_content = "這個傢伙看起來也太恐怖了吧，要怎麼對付才行？！",
  ui_story_5028_50281202_94_dialog_content = "這妳可問對人了。",
  ui_story_5028_50281202_95_dialog_content = "凱羅是珍稀的神奇動物，若能獲得牠的信任，就會天下無敵。",
  ui_story_5028_50281202_96_dialog_content = "而能夠對付凱羅的，只有凱羅。",
  ui_story_5028_50281301_1_dialog_content = "囉！",
  ui_story_5028_50281301_2_dialog_content = "囉囉！",
  ui_story_5028_50281301_3_dialog_content = "可惡，這傢伙怎麼這麼強！",
  ui_story_5028_50281301_4_dialog_content = "再多掙扎一會吧，把這份恐懼牢牢記住！",
  ui_story_5028_50281301_5_dialog_content = "然後，這群畜生會踏平艾斯特拉的每個角落。",
  ui_story_5028_50281301_6_dialog_content = "哈哈......哈哈哈哈！",
  ui_story_5028_50281301_7_dialog_content = "再見了，小鬼。",
  ui_story_5028_50281301_8_dialog_content = "就是現在，PlayerName！",
  ui_story_5028_50281301_9_dialog_content = "快用你的力量，將菲雅的信任傳達給凱羅吧！",
  ui_story_5028_50281301_10_dialog_content = "欸？我，我的力量？",
  ui_story_5028_50281301_11_dialog_content = "用你的頭腦，認真想一想！",
  ui_story_5028_50281301_12_dialog_content = "（我的力量......）",
  ui_story_5028_50281301_13_dialog_content = "（我只有感應能力，能讓大家交流。）",
  ui_story_5028_50281301_14_dialog_content = "（交流......菲雅和凱羅一直無法交流，難道說？！）",
  ui_story_5028_50281301_15_dialog_content = "簡單來說，就是感應凱羅的想法和情緒，再轉達給菲雅。",
  ui_story_5028_50281301_16_dialog_content = "剩下的事情，菲雅的天賦會解決！",
  ui_story_5028_50281301_17_dialog_content = "欸？！我還能感應凱羅的想法嗎？",
  ui_story_5028_50281301_18_dialog_content = "那是當然，別忘了，你可是空裔！",
  ui_story_5028_50281301_19_dialog_content = "我......我試試！",
  ui_story_5028_50281301_20_option_content = "強制感應！",
  ui_story_5028_50281301_21_dialog_content = "感受凱羅的想法......",
  ui_story_5028_50281301_22_dialog_content = "囉，囉囉！",
  ui_story_5028_50281301_23_dialog_content = "牠很著急，似乎有什麼力量，卻被禁錮著無法使出......",
  ui_story_5028_50281301_24_dialog_content = "囉囉！",
  ui_story_5028_50281301_25_dialog_content = "這種情緒，像是在說保護？",
  ui_story_5028_50281301_26_dialog_content = "保護......保護？",
  ui_story_5028_50281301_27_dialog_content = "菲雅！凱羅想要保護妳！",
  ui_story_5028_50281301_28_dialog_content = "咦？！",
  ui_story_5028_50281301_29_dialog_content = "囉囉囉！",
  ui_story_5028_50281301_30_dialog_content = "這句話是保護的意思嗎？！",
  ui_story_5028_50281301_31_dialog_content = "囉囉，囉囉！",
  ui_story_5028_50281301_32_dialog_content = "牠好像是在肯定你的想法，而且非常著急！",
  ui_story_5028_50281301_33_dialog_content = "著急......肯定......",
  ui_story_5028_50281301_34_dialog_content = "原來這種叫聲對應的是這個意思嗎？",
  ui_story_5028_50281301_35_dialog_content = "我懂了......菲雅完全明白了！",
  ui_story_5028_50281301_36_dialog_content = "明白？妳明白什麼了？",
  ui_story_5028_50281301_37_dialog_content = "多虧了你說的資訊，現在菲雅能把凱羅的叫聲與牠的意思對應起來了。",
  ui_story_5028_50281301_38_dialog_content = "也就是說，我破譯了凱羅的語言！",
  ui_story_5028_50281301_39_dialog_content = "這樣也行？！",
  ui_story_5028_50281301_40_dialog_content = "囉囉囉！囉囉，囉——！",
  ui_story_5028_50281301_41_dialog_content = "牠......牠在說什麼？",
  ui_story_5028_50281301_42_dialog_content = "牠在說「我要保護菲雅」！",
  ui_story_5028_50281301_43_dialog_content = "囉——！",
  ui_story_5028_50281301_44_dialog_content = "什麼？凱羅，你說你透過與菲雅交流，獲得了新的力量？",
  ui_story_5028_50281301_45_dialog_content = "那就快點使出來吧！",
  ui_story_5028_50281301_46_dialog_content = "唔！凱羅變得好亮啊！",
  ui_story_5028_50281301_47_dialog_content = "凱羅的樣子發生了變化......？！",
  ui_story_5028_50281301_48_dialog_content = "菲雅、凱羅，使用這份力量，打敗蓋里吧！",
  ui_story_5028_50281301_49_dialog_content = "不用你說，我也知道！",
  ui_story_5028_50281301_50_dialog_content = "憑你們的力量，想要打敗我？做夢去吧！",
  ui_story_5028_50281301_51_dialog_content = "去吧，小畜生。碾碎他們！",
  ui_story_5028_50281301_52_dialog_content = "吼——！",
  ui_story_5028_50281301_53_dialog_content = "囉！",
  ui_story_5028_50281302_1_dialog_content = "去吧，凱羅，讓這個臭大叔明白，我們可不是好欺負的！",
  ui_story_5028_50281302_2_dialog_content = "囉！",
  ui_story_5028_50281302_3_dialog_content = "這是......怎麼會？！",
  ui_story_5028_50281302_4_dialog_content = "囉！囉囉囉！",
  ui_story_5028_50281302_5_dialog_content = "蓋里的那隻凱羅，發出了痛苦的叫聲......",
  ui_story_5028_50281302_6_dialog_content = "凱羅......",
  ui_story_5028_50281302_7_dialog_content = "凱羅！瞄準蓋里的鞭子！",
  ui_story_5028_50281302_8_dialog_content = "囉！！！",
  ui_story_5028_50281302_9_dialog_content = "呃！！！",
  ui_story_5028_50281302_10_dialog_content = "就是現在！",
  ui_story_5028_50281302_11_dialog_content = "看我的！",
  ui_story_5028_50281302_12_dialog_content = "燃燒吧！",
  ui_story_5028_50281302_13_dialog_content = "燃索！",
  ui_story_5028_50281302_14_dialog_content = "暗鬼，全部解決了！",
  ui_story_5028_50281302_15_dialog_content = "最後一個敵人也被我套住了，勝利是屬於我的。",
  ui_story_5028_50281302_16_dialog_content = "投機取巧可不好啊，小吉納維芙。",
  ui_story_5028_50281302_17_dialog_content = "那傢伙明明是我先打趴的。",
  ui_story_5028_50281302_18_dialog_content = "妳只是在那傢伙身上留下了鞭子的痕跡而已。",
  ui_story_5028_50281302_19_dialog_content = "所有敵人都被打倒了？",
  ui_story_5028_50281302_20_dialog_content = "成功了......？",
  ui_story_5028_50281302_21_dialog_content = "囉！",
  ui_story_5028_50281302_22_dialog_content = "耶！",
  ui_story_5028_50281302_23_dialog_content = "可惡……",
  ui_story_5028_50281302_24_dialog_content = "蓋里對凱羅的控制解除了！",
  ui_story_5028_50281302_25_dialog_content = "PlayerName，把菲雅的心聲也傳遞給那隻凱羅吧，就像你之前做的那樣！",
  ui_story_5028_50281302_26_dialog_content = "好的！",
  ui_story_5028_50281302_27_option_content = "強制感應！",
  ui_story_5028_50281302_28_dialog_content = "你是凱羅的同族吧？",
  ui_story_5028_50281302_29_dialog_content = "不要再懼怕那個臭大叔了！",
  ui_story_5028_50281302_30_dialog_content = "我們解除了他對你的控制，你再也不用被迫做自己不喜歡的事情了！",
  ui_story_5028_50281302_31_dialog_content = "不要再為他戰鬥了，和我們一起走吧。",
  ui_story_5028_50281302_32_dialog_content = "本神奇動物專家會保護你的！",
  ui_story_5028_50281302_33_dialog_content = "囉......囉？",
  ui_story_5028_50281302_34_dialog_content = "囉！",
  ui_story_5028_50281302_35_dialog_content = "放心吧，我可不是那個壞大叔，我會好好對待你的！",
  ui_story_5028_50281302_36_dialog_content = "……",
  ui_story_5028_50281302_37_dialog_content = "糟糕，這隻凱羅長期被蓋里粗暴對待，身心都已經處在崩潰的邊緣了！",
  ui_story_5028_50281302_38_dialog_content = "要儘快帶牠離開這裡，好好休養才行。",
  ui_story_5028_50281302_39_dialog_content = "我的復仇，我的憎恨......怎麼可能輕易被你們這群愚蠢的傢伙破壞！",
  ui_story_5028_50281302_40_dialog_content = "你這畜生，給我站起來！",
  ui_story_5028_50281302_41_dialog_content = "現在還不是你休息的時候！",
  ui_story_5028_50281302_42_dialog_content = "囉......囉......！",
  ui_story_5028_50281302_43_dialog_content = "這隻凱羅，原來一直在喊痛嗎......",
  ui_story_5028_50281302_44_dialog_content = "快停下，臭大叔！",
  ui_story_5028_50281302_45_dialog_content = "你弄痛牠了！",
  ui_story_5028_50281302_46_dialog_content = "痛？",
  ui_story_5028_50281302_47_dialog_content = "這就對了！",
  ui_story_5028_50281302_48_dialog_content = "不痛怎麼能讓牠畏懼我？",
  ui_story_5028_50281302_49_dialog_content = "不畏懼我，又怎麼能讓牠發揮出最大的力量？",
  ui_story_5028_50281302_50_dialog_content = "給我使出全力，揍趴他們！",
  ui_story_5028_50281302_51_dialog_content = "不然有你好看的！",
  ui_story_5028_50281302_52_dialog_content = "囉囉，囉！",
  ui_story_5028_50281302_53_dialog_content = "囉！",
  ui_story_5028_50281302_54_dialog_content = "噫！怎，怎麼辦？牠在求救！",
  ui_story_5028_50281302_55_dialog_content = "要再擊敗牠一次嗎？",
  ui_story_5028_50281302_56_dialog_content = "囉！",
  ui_story_5028_50281302_57_dialog_content = "快住手，菲雅！",
  ui_story_5028_50281302_58_dialog_content = "那隻凱羅已經非常虛弱了，撐不過你們的攻擊！",
  ui_story_5028_50281302_59_dialog_content = "那，那你倒是說說該怎麼辦啊廢柴師父！",
  ui_story_5028_50281302_60_dialog_content = "哎呀，事到如今，也只能祈求好運從天而降了。",
  ui_story_5028_50281302_61_dialog_content = "我果然不該相信你！",
  ui_story_5028_50281302_62_dialog_content = "哈哈哈，祈禱吧，這是你們最後的機會了。",
  ui_story_5028_50281302_63_dialog_content = "接下來就是——",
  ui_story_5028_50281302_64_dialog_content = "打架什麼的，最麻煩了。",
  ui_story_5028_50281302_65_dialog_content = "哪來的聲音？！",
  ui_story_5028_50281302_66_dialog_content = "但是，放跑你這種傢伙，以後會帶來更多麻煩！",
  ui_story_5028_50281302_67_dialog_content = "嗷吼——",
  ui_story_5028_50281302_68_dialog_content = "呃！我竟然......",
  ui_story_5028_50281302_69_option_content = "好運......變成詩燁了！",
  ui_story_5028_50281302_70_option_content = "詩燁從天而降，踢飛了蓋里！",
  ui_story_5028_50281302_71_dialog_content = "從來就沒有什麼好運。",
  ui_story_5028_50281302_72_dialog_content = "只是不過是過去一次次努力，累積到現在發生了質變而已。",
  ui_story_5028_50281302_73_dialog_content = "詩燁師姐——！",
  ui_story_5028_50281302_74_dialog_content = "多，多虧我機智，之前讓蒼獅龍帶詩燁師姐去救其他動物。",
  ui_story_5028_50281302_75_dialog_content = "這才破壞了蓋里的陰謀！",
  ui_story_5028_50281302_76_dialog_content = "唉，究竟該說妳成長了，還是一點也沒成長？",
  ui_story_5028_50281302_77_dialog_content = "囉......",
  ui_story_5028_50281302_78_dialog_content = "嗚啊？！",
  ui_story_5028_50281302_79_dialog_content = "囉囉？！",
  ui_story_5028_50281302_80_dialog_content = "看起來這隻小傢伙被蓋里折騰得不輕。",
  ui_story_5028_50281302_81_dialog_content = "就讓牠休息一下吧。",
  ui_story_5028_50281302_82_dialog_content = "那麼這個麻煩的傢伙，應該怎麼處理呢？",
  ui_story_5028_50281302_83_dialog_content = "咳咳！唔！",
  ui_story_5028_50281302_84_dialog_content = "（詩燁用一隻腕足拎著蓋里的衣領，把他抓了過來......）",
  ui_story_5028_50281302_85_dialog_content = "（而且滿身殺氣！）",
  ui_story_5028_50281302_86_dialog_content = "（真恐怖！！！）",
  ui_story_5028_50281302_87_dialog_content = "囉囉囉......",
  ui_story_5028_50281302_88_dialog_content = "呵......我......竟然失敗了......",
  ui_story_5028_50281302_89_dialog_content = "你們殺了我吧。",
  ui_story_5028_50281302_90_dialog_content = "死在這些畜生手裡，或許也是我的宿命吧。",
  ui_story_5028_50281302_91_dialog_content = "這個傢伙如果留著，只會帶來麻煩。",
  ui_story_5028_50281302_92_dialog_content = "為了避免麻煩，還是......",
  ui_story_5028_50281302_93_dialog_content = "先讓我們來聽聽這次事件最大的功臣——菲雅的意見吧，妳想怎麼處理他？",
  ui_story_5028_50281302_94_dialog_content = "……",
  ui_story_5028_50281302_95_dialog_content = "菲雅？",
  ui_story_5028_50281302_96_dialog_content = "當然是讓這個臭大叔去蹲大牢了！",
  ui_story_5028_50281302_97_dialog_content = "欸？",
  ui_story_5028_50281302_98_dialog_content = "呵，蹲大牢？",
  ui_story_5028_50281302_99_dialog_content = "等我出來以後，照樣會繼續向這些畜生復仇。",
  ui_story_5028_50281302_100_dialog_content = "如果是那樣，本「神奇動物專家」就會再次出手阻止你！",
  ui_story_5028_50281302_101_dialog_content = "讓你看著這些神奇動物在本「神奇動物專家」的保護下茁壯生長——",
  ui_story_5028_50281302_102_dialog_content = "這就是對你最好的懲罰！",
  ui_story_5028_50281302_103_dialog_content = "嗯～真是精彩的發言。",
  ui_story_5028_50281302_104_dialog_content = "嗚啊，是，是和詩燁師姐一樣的章魚，還是章魚男？！",
  ui_story_5028_50281302_105_dialog_content = "被這樣稱呼，我會非常傷心喔。",
  ui_story_5028_50281302_106_dialog_content = "克萊肯，既然你在這裡，那就意味著影主......",
  ui_story_5028_50281302_107_dialog_content = "真巧啊，PlayerName，你們手中的這位強盜正是影主在尋找的人。",
  ui_story_5028_50281302_108_dialog_content = "這麼麻煩的人，不被影主盯上才比較奇怪吧。",
  ui_story_5028_50281302_109_dialog_content = "這位小姐說得沒錯。",
  ui_story_5028_50281302_110_dialog_content = "蓋里，十年前你的妻兒誤入了神奇動物的領地，被狂暴的神奇動物誤傷致死。",
  ui_story_5028_50281302_111_dialog_content = "從那之後，你就開始四處狩獵神奇動物。",
  ui_story_5028_50281302_112_dialog_content = "如果只是狩獵行為，那麼影主也不會干涉。",
  ui_story_5028_50281302_113_dialog_content = "但你的行為已經越過界限，威脅到了影鎮。",
  ui_story_5028_50281302_114_dialog_content = "威脅到影鎮？有那麼誇張嗎？",
  ui_story_5028_50281302_115_dialog_content = "當然了，這位小姐。",
  ui_story_5028_50281302_116_dialog_content = "影鎮周圍棲息著許多神奇動物，牠們是維護影鎮安全的重要一環。",
  ui_story_5028_50281302_117_dialog_content = "這些神奇動物會為了守護領地而趕走其他有威脅的生物，這其中就包括一部分暗鬼。",
  ui_story_5028_50281302_118_dialog_content = "牠們的存在在影鎮周圍構築起了一道無形的牆壁，將暗鬼與光靈隔開。",
  ui_story_5028_50281302_119_dialog_content = "一旦牠們消失，那麼，影鎮就有可能直接受到暗鬼的衝擊。",
  ui_story_5028_50281302_120_dialog_content = "原來是這樣……",
  ui_story_5028_50281302_121_dialog_content = "呵，影主？",
  ui_story_5028_50281302_122_dialog_content = "既然影主有這個能耐，為什麼當年沒有趁早除掉那群畜生，保護我的妻兒？",
  ui_story_5028_50281302_123_dialog_content = "難道她們不是生活在你們所謂的「規則」之下的人嗎？！",
  ui_story_5028_50281302_124_dialog_content = "影主是影鎮的規則，不是森林的規則。",
  ui_story_5028_50281302_125_dialog_content = "遵守規則本身，亦是規則的體現。",
  ui_story_5028_50281302_126_dialog_content = "呸！說得好聽。",
  ui_story_5028_50281302_127_dialog_content = "蓋里。",
  ui_story_5028_50281302_128_dialog_content = "怎麼，你也要對我說教幾句？",
  ui_story_5028_50281302_129_dialog_content = "還是說，你要為我騙你那件事，向我復仇？",
  ui_story_5028_50281302_130_dialog_content = "嘁，隨你怎麼做好了，不管你說什麼，我也不會改變我的想法。",
  ui_story_5028_50281302_131_dialog_content = "沒有人能阻止我，沒有人！",
  ui_story_5028_50281302_132_dialog_content = "這可由不得你。",
  ui_story_5028_50281302_133_dialog_content = "訓練神奇動物來自相殘殺，最終讓所有神奇動物從世界上消失......",
  ui_story_5028_50281302_134_dialog_content = "就算影主不出手阻止你，也會有像是這位小姐一樣的其他人阻止你吧。",
  ui_story_5028_50281302_135_dialog_content = "蓋里。",
  ui_story_5028_50281302_136_dialog_content = "你知道我的翅膀為什麼只有一邊嗎？",
  ui_story_5028_50281302_137_dialog_content = "不知道，這和我有什麼關係？",
  ui_story_5028_50281302_138_dialog_content = "欸？",
  ui_story_5028_50281302_139_option_content = "為什麼？",
  ui_story_5028_50281302_140_dialog_content = "我也很早就注意到了這件事情，但你每次都以別的事搪塞過去。",
  ui_story_5028_50281302_141_dialog_content = "我很小的時候就非常喜歡這些神奇生物，經常試著接近牠們。",
  ui_story_5028_50281302_142_dialog_content = "但那時的我並不清楚牠們的習性，因此不小心惹怒了一隻神奇動物。",
  ui_story_5028_50281302_143_dialog_content = "憤怒的牠襲擊了我，扯掉我的半邊翅膀，讓我變成現在的樣子。",
  ui_story_5028_50281302_144_dialog_content = "那些畜生這樣對你，你不覺得憤怒嗎？",
  ui_story_5028_50281302_145_dialog_content = "我起初覺得不解、覺得委屈，但後來，在某個朋友的幫助下，我逐漸理解了牠們。",
  ui_story_5028_50281302_146_dialog_content = "在這些神奇動物眼中，我們光靈同樣是一種難以理解的生物。",
  ui_story_5028_50281302_147_dialog_content = "牠們會本能地懷疑、懼怕我們，在我們離得太近時，牠們會為了自保而攻擊我們。",
  ui_story_5028_50281302_148_dialog_content = "這和我們對神奇動物所做的一模一樣。",
  ui_story_5028_50281302_149_dialog_content = "更何況對於牠們來說，光靈是狩獵牠們、捕捉它們、侵犯牠們家園的壞人。",
  ui_story_5028_50281302_150_dialog_content = "如果不是因為那位朋友有著能讓光靈與動物心意相通的能力......",
  ui_story_5028_50281302_151_dialog_content = "恐怕我一輩子也不會知道，牠們對我們懷抱著這樣的情感吧。",
  ui_story_5028_50281302_152_dialog_content = "所以我理解了牠們，並且原諒了牠們。",
  ui_story_5028_50281302_153_dialog_content = "但這不一樣。",
  ui_story_5028_50281302_154_dialog_content = "你原不原諒牠們，那是你的一廂情願。",
  ui_story_5028_50281302_155_dialog_content = "我的家人們可是失去了生命啊！",
  ui_story_5028_50281302_156_dialog_content = "據我所知，在那件事發生後，你就開始一個人在那片森林裡狩獵，對不對？",
  ui_story_5028_50281302_157_dialog_content = "沒錯，我把那群畜生都宰了，一個都不剩。",
  ui_story_5028_50281302_158_dialog_content = "你殺了牠們，明明已經報了仇，為什麼還要繼續折磨別的神奇生物？",
  ui_story_5028_50281302_159_dialog_content = "甚至還要用恐懼使牠們屈服，讓牠們主動去攻擊光靈。",
  ui_story_5028_50281302_160_dialog_content = "當然是為了讓所有人都知道，畜生和光靈是不一樣的，牠們恐怖又該死。",
  ui_story_5028_50281302_161_dialog_content = "如果你眼中的神奇動物是這副模樣——",
  ui_story_5028_50281302_162_dialog_content = "殺害你的至親，奪走你的幸福，毀滅你的後半生。",
  ui_story_5028_50281302_163_dialog_content = "那麼，持續著無意義殺戮的你，又和那些被你所厭惡的「畜生」有什麼區別呢？",
  ui_story_5028_50281302_164_dialog_content = "......！",
  ui_story_5028_50281302_165_dialog_content = "我的老朋友，你的生命還很漫長，希望在未來的歲月裡，你能想清楚這件事。",
  ui_story_5028_50281302_166_dialog_content = "我已經沒什麼要對他說的了喔，神奇的章魚先生。",
  ui_story_5028_50281302_167_dialog_content = "哦，你們已經聊完了嗎？",
  ui_story_5028_50281302_168_dialog_content = "那麼，請聽聽我的請求吧。",
  ui_story_5028_50281302_169_dialog_content = "幾位，我希望你們能將他和他的手下交給影主。",
  ui_story_5028_50281302_170_dialog_content = "守護影鎮的安全，給犯人合適的懲罰，這是影主做出的承諾。",
  ui_story_5028_50281302_171_dialog_content = "至於這位小姐說的「蹲大牢」，我會向影主諫言。",
  ui_story_5028_50281302_172_dialog_content = "哎呀，我倒是沒什麼意見，你們呢？",
  ui_story_5028_50281302_173_dialog_content = "那位大人雖然不關心神奇動物，但是在處理犯人方面最專業了。",
  ui_story_5028_50281302_174_dialog_content = "如果要額外蓋一座監獄給他住的話，會很麻煩。",
  ui_story_5028_50281302_175_dialog_content = "影主那裡，應該有不少合適犯人住的地方吧。",
  ui_story_5028_50281302_176_dialog_content = "我沒意見。",
  ui_story_5028_50281302_177_dialog_content = "能讓他蹲大牢的話，我也沒意見！",
  ui_story_5028_50281302_178_option_content = "那就拜託克萊肯了。",
  ui_story_5028_50281302_179_option_content = "非常感謝。",
  ui_story_5028_50281302_180_dialog_content = "那邊的幾位，能拜託你們幫忙，將這些強盜們一起送回影鎮嗎？",
  ui_story_5028_50281302_181_dialog_content = "要幫忙嗎？可以喔。",
  ui_story_5028_50281302_182_dialog_content = "嘁，又是無聊的工作。",
  ui_story_5028_50281302_183_dialog_content = "我們看起來也幫不上什麼忙了，這裡剩下的動物，還是交給專業人士來救助吧。",
  ui_story_5028_50281302_184_dialog_content = "嗯！",
  ui_story_5028_50281302_185_dialog_content = "那麼，我先回去復命了。再見，各位。",
  ui_story_5028_50281302_186_dialog_content = "希望那個傢伙不會惹出別的麻煩。",
  ui_story_5028_50281302_187_dialog_content = "哎呀，這種事情就是後話了。",
  ui_story_5028_50281401_1_dialog_content = "總之，這件事情算是告一段落了，可喜可賀，可喜可賀。",
  ui_story_5028_50281401_2_dialog_content = "原來凱羅真的有這麼強。",
  ui_story_5028_50281401_3_dialog_content = "我還以為師父說的「天下無敵」只是騙人用的呢！",
  ui_story_5028_50281401_4_dialog_content = "為師從來不會騙自己的徒弟喔，不管是詩燁還是菲雅，都是為師最重視的徒弟。",
  ui_story_5028_50281401_5_dialog_content = "他確實不騙人。",
  ui_story_5028_50281401_6_dialog_content = "妳看，妳詩燁師姐都這麼說——",
  ui_story_5028_50281401_7_dialog_content = "他不值得信任的原因，只是因為不靠譜。",
  ui_story_5028_50281401_8_dialog_content = "詩燁，你這麼說為師，為師要哭了，嗚嗚嗚......",
  ui_story_5028_50281401_9_dialog_content = "可是為什麼，凱羅明明擁有這麼強大的力量，之前遇到危險的時候卻沒有使用出來？",
  ui_story_5028_50281401_10_dialog_content = "不對不對，更奇怪的是......",
  ui_story_5028_50281401_11_dialog_content = "為什麼師父擁有凱羅這麼厲害的神奇動物，卻還是一個一事無成的廢柴呢？！",
  ui_story_5028_50281401_12_dialog_content = "對啊，這太奇怪了！",
  ui_story_5028_50281401_13_dialog_content = "……",
  ui_story_5028_50281401_14_dialog_content = "唉......還是我來解釋吧。",
  ui_story_5028_50281401_15_dialog_content = "凱羅這種生物是非常特殊的，牠們擁有強大的力量。",
  ui_story_5028_50281401_16_dialog_content = "這種力量只有在和牠互相信任的生物溝通時才能使用。",
  ui_story_5028_50281401_17_dialog_content = "但是，由於凱羅數量稀少，凱羅們之間的語言也逐漸失傳。",
  ui_story_5028_50281401_18_dialog_content = "而由於凱羅千變萬化的特性，牠們使用的肢體語言也各不相同，無法讓他人準確地理解。",
  ui_story_5028_50281401_19_dialog_content = "因此，很少有光靈能夠與凱羅溝通。",
  ui_story_5028_50281401_20_dialog_content = "有時候，甚至凱羅們自己都會因為不理解對方的叫聲而無法交流。",
  ui_story_5028_50281401_21_dialog_content = "這就導致凱羅一族的幼體在野外的成活率非常低。",
  ui_story_5028_50281401_22_dialog_content = "妳在棲息地裡看到的那些凱羅，其實全都是由維克親手撫養長大的。",
  ui_story_5028_50281401_23_dialog_content = "維克師父這麼厲害嗎？！",
  ui_story_5028_50281401_24_dialog_content = "但既然凱羅無法交流，那他又是怎麼知道凱羅的習性的呢？",
  ui_story_5028_50281401_25_dialog_content = "有一種方法能讓他人明白凱羅的心意，那就是......",
  ui_story_5028_50281401_26_option_content = "我……？",
  ui_story_5028_50281401_27_dialog_content = "準確來說，是空裔的感應能力。",
  ui_story_5028_50281401_28_option_content = "空裔......？",
  ui_story_5028_50281401_29_dialog_content = "沒錯。",
  ui_story_5028_50281401_30_dialog_content = "空裔的感應能力能直接突破語言障礙，感知到凱羅的想法。",
  ui_story_5028_50281401_31_dialog_content = "理解這種想法，再將凱羅的叫聲與想法對應，逐漸理解它們的語言......",
  ui_story_5028_50281401_32_dialog_content = "我終於知道了，菲雅，妳的天賦是能夠迅速地理解牠們。",
  ui_story_5028_50281401_33_dialog_content = "所以師父給我的第一個任務才會是「抓捕一隻空裔」嗎？",
  ui_story_5028_50281401_34_dialog_content = "是的，「溝通」正是激發凱羅真正能力的重要因素。",
  ui_story_5028_50281401_35_dialog_content = "那我為什麼也能聽懂凱羅說的話？",
  ui_story_5028_50281401_36_dialog_content = "大概是因為在你們的旅途中，凱羅早已經把你也當成同伴了吧。",
  ui_story_5028_50281401_37_dialog_content = "可是，為什麼蓋里的凱羅也能使用那個能力？",
  ui_story_5028_50281401_38_dialog_content = "我不清楚。",
  ui_story_5028_50281401_39_dialog_content = "但我猜，可能是那條鞭子造成的影響。",
  ui_story_5028_50281401_40_dialog_content = "那條鞭子可以將恐懼與屈服深深烙在神奇動物的內心裡。",
  ui_story_5028_50281401_41_dialog_content = "恐懼是與信任對立的另一個極端，凱羅恐懼到極點，以至於變成了那樣扭曲的形態。",
  ui_story_5028_50281401_42_dialog_content = "哼，這可不是真正的「溝通」！",
  ui_story_5028_50281401_43_dialog_content = "肯定是因為這樣，他才沒辦法戰勝身為「神奇動物專家」、與凱羅真正成功溝通的我！",
  ui_story_5028_50281401_44_dialog_content = "維克先生一直都知道這些事？",
  ui_story_5028_50281401_45_dialog_content = "也不是一直都知道。",
  ui_story_5028_50281401_46_dialog_content = "他曾經與一位空裔相識。",
  ui_story_5028_50281401_47_dialog_content = "在那位空裔的幫助下，他成功與凱羅溝通，瞭解了這種神奇動物。",
  ui_story_5028_50281401_48_dialog_content = "直到十七年前。",
  ui_story_5028_50281401_49_dialog_content = "等等，維克先生不是說自己是永遠的十八歲嗎？",
  ui_story_5028_50281401_50_dialog_content = "他究竟有多少歲啊？！",
  ui_story_5028_50281401_51_dialog_content = "咳咳，好啦！現在可不是敘舊的時候！",
  ui_story_5028_50281401_52_dialog_content = "這裡還有不少事等著我們處理呢。",
  ui_story_5028_50281401_53_dialog_content = "囉！囉——！",
  ui_story_5028_50281401_54_dialog_content = "發生了什麼事？你讓我看牠？",
  ui_story_5028_50281401_55_dialog_content = "囉......囉......",
  ui_story_5028_50281401_56_dialog_content = "這是......牠的情況突然開始惡化了。",
  ui_story_5028_50281401_57_dialog_content = "糟了，一定是長期的恐懼和受傷讓牠的情況變得很差。",
  ui_story_5028_50281401_58_dialog_content = "再加上在這次戰鬥中身受重傷，牠的身體一下子崩潰了。",
  ui_story_5028_50281401_59_dialog_content = "你們有誰會用光能術治療？",
  ui_story_5028_50281401_60_dialog_content = "……",
  ui_story_5028_50281401_61_dialog_content = "快，現在去影鎮找人求救，應該還來得及！",
  ui_story_5028_50281401_62_dialog_content = "蒼獅龍，幫幫我們！",
  ui_story_5028_50281401_63_dialog_content = "要來不及了！",
  ui_story_5028_50281401_64_dialog_content = "囉！",
  ui_story_5028_50281401_65_dialog_content = "欸？凱，凱羅？！",
  ui_story_5028_50281401_66_dialog_content = "囉囉！囉囉囉！",
  ui_story_5028_50281401_67_dialog_content = "這些都是剛才被我放走的那些凱羅......",
  ui_story_5028_50281401_68_dialog_content = "牠們竟然都回來了？",
  ui_story_5028_50281401_69_dialog_content = "囉！囉囉！",
  ui_story_5028_50281401_70_dialog_content = "你說，讓我與牠們交流，這樣就能獲得幫助？",
  ui_story_5028_50281401_71_dialog_content = "好，我試試看！",
  ui_story_5028_50281401_72_dialog_content = "凱羅的同族們，請幫幫我，救救牠吧！",
  ui_story_5028_50281401_73_dialog_content = "幫幫我們......",
  ui_story_5028_50281401_74_dialog_content = "救救牠......",
  ui_story_5028_50281401_75_dialog_content = "囉！",
  ui_story_5028_50281401_76_dialog_content = "囉囉囉！",
  ui_story_5028_50281401_77_dialog_content = "這些光，和剛剛菲雅的凱羅發出的光一樣！",
  ui_story_5028_50281401_78_dialog_content = "你們可要好好看著。",
  ui_story_5028_50281401_79_dialog_content = "這說不定會成為絕無僅有的場景。",
  ui_story_5028_50281401_80_dialog_content = "凱羅們在空裔的幫助下與菲雅心意相通，爆發出強大的力量......",
  ui_story_5028_50281401_81_dialog_content = "囉囉囉——",
  ui_story_5028_50281401_82_dialog_content = "凱羅們發出的光，包圍了那隻受傷的凱羅......",
  ui_story_5028_50281401_83_dialog_content = "牠的傷慢慢恢復了！",
  ui_story_5028_50281401_83X_dialog_content = "這就是凱羅的力量。",
  ui_story_5028_50281401_84_dialog_content = "能夠模仿出其他神奇動物，甚至是光靈的能力。",
  ui_story_5028_50281401_85_dialog_content = "就算被形容為「天下無敵」也不為過。",
  ui_story_5028_50281401_86_dialog_content = "果然被形容為「天下無敵」也不為過。",
  ui_story_5028_50281401_87_dialog_content = "原來如此……",
  ui_story_5028_50281401_88_option_content = "真厲害",
  ui_story_5028_50281401_89_dialog_content = "PlayerName也很厲害喔。",
  ui_story_5028_50281401_90_dialog_content = "欸？",
  ui_story_5028_50281401_91_option_content = "真羨慕",
  ui_story_5028_50281401_92_dialog_content = "如果我也有這麼強大的力量，就能更好地守護朋友們了......",
  ui_story_5028_50281401_93_dialog_content = "你本身也有著非常強大的力量，那就是讓人們互相交流的感應能力。",
  ui_story_5028_50281401_94_dialog_content = "這種力量雖然沒辦法用於戰鬥，卻能夠讓人們互相理解。",
  ui_story_5028_50281401_95_dialog_content = "它能化解誤會、消除仇恨，甚至能夠阻止戰爭的發生。",
  ui_story_5028_50281401_96_dialog_content = "是這樣嗎……",
  ui_story_5028_50281401_97_dialog_content = "我知道了！",
  ui_story_5028_50281401_98_dialog_content = "你們看，那隻凱羅好像恢復精神了。",
  ui_story_5028_50281401_99_dialog_content = "囉......囉？",
  ui_story_5028_50281401_100_dialog_content = "你已經沒事啦！",
  ui_story_5028_50281401_101_dialog_content = "是大家一起幫忙，治好了你！",
  ui_story_5028_50281401_102_dialog_content = "囉囉，囉！",
  ui_story_5028_50281401_103_dialog_content = "嗯嗯，當然，你可要好好感謝本「神奇動物專家」喔！",
  ui_story_5028_50281401_104_dialog_content = "囉囉囉！",
  ui_story_5028_50281401_105_dialog_content = "嗚哇！哈哈哈，好癢！",
  ui_story_5028_50281401_106_dialog_content = "總是呆在這個地方也不好，是時候把這些小傢伙送回牠們原本生活的地方了。",
  ui_story_5028_50281401_107_dialog_content = "欸？凱羅們要回去了？",
  ui_story_5028_50281401_108_dialog_content = "囉！",
  ui_story_5028_50281401_109_dialog_content = "凱羅，你要離開我嗎？",
  ui_story_5028_50281401_110_dialog_content = "能不能不要走？！",
  ui_story_5028_50281401_111_dialog_content = "囉......",
  ui_story_5028_50281401_112_dialog_content = "囉嗚！",
  ui_story_5028_50281401_113_dialog_content = "不，不行嗎？可是，可是......",
  ui_story_5028_50281401_114_dialog_content = "唉，說到底妳還是個小孩子。",
  ui_story_5028_50281401_115_dialog_content = "尊重神奇動物的習性和願望，也是我們這樣的研究者必須具備的品質。",
  ui_story_5028_50281401_116_dialog_content = "不可以將妳的想法強加給神奇動物。",
  ui_story_5028_50281401_117_dialog_content = "我，我才不是小孩子！",
  ui_story_5028_50281401_118_dialog_content = "囉！",
  ui_story_5028_50281401_119_dialog_content = "這是……",
  ui_story_5028_50281401_120_dialog_content = "泥尊鷹的能力，妳竟然使用這招......呼啊......",
  ui_story_5028_50281401_121_dialog_content = "囉囉！",
  ui_story_5028_50281401_122_dialog_content = "哎呀，這麼快就要離開了嗎？",
  ui_story_5028_50281401_123_dialog_content = "與夥伴離別，菲雅醒來的時候，一定會大哭大鬧一通吧。",
  ui_story_5028_50281401_124_dialog_content = "要安撫好小孩子的情緒，非常麻煩。",
  ui_story_5028_50281401_125_dialog_content = "為師不擅長照顧小孩呢，所以這件事就麻煩為師的大徒弟啦。",
  ui_story_5028_50281401_126_dialog_content = "唉......",
  ui_story_5028_50281401_127_dialog_content = "要好好和夥伴們一起生活喔！",
  ui_story_5028_50281401_128_dialog_content = "也要記得遠離看起來就危險的傢伙。",
  ui_story_5028_50281401_129_dialog_content = "囉！",
  ui_story_5028_50281401_130_dialog_content = "故事到這裡結束了。",
  ui_story_5028_50281401_131_dialog_content = "凱羅和牠的同族們，至今仍幸福地生活在森林裡。",
  ui_story_5028_50281401_132_dialog_content = "而名為菲雅的少女得到了成長，成為了名副其實的「神奇動物專家」。",
  ui_story_5028_50281401_133_dialog_content = "可喜可賀，可喜可賀。",
  ui_story_5028_50281401_134_dialog_content = "然後呢，然後發生了什麼事？",
  ui_story_5028_50281401_135_dialog_content = "薇絲，能不能先讓我休息一下？",
  ui_story_5028_50281401_136_dialog_content = "我已經對著這本《神奇動物大冒險》整整講了三個小時......",
  ui_story_5028_50281401_137_dialog_content = "嗓子都要燒起來了！",
  ui_story_5028_50281401_138_dialog_content = "啊，抱歉抱歉，先休息一下吧。",
  ui_story_5028_50281401_139_dialog_content = "我有些聽入迷了，現在還覺得意猶未盡呢！",
  ui_story_5028_50281401_140_dialog_content = "真想知道後續發生了什麼。",
  ui_story_5028_50281401_141_dialog_content = "妳也可以直接去問寫這本書的人啊，她一定——",
  ui_story_5028_50281401_142_dialog_content = "PlayerName！！！",
  ui_story_5028_50281401_143_dialog_content = "看吧，說什麼來什麼。",
  ui_story_5028_50281401_144_dialog_content = "我想要去海邊尋找神奇動物！",
  ui_story_5028_50281401_145_dialog_content = "作為我的神奇動物夥伴，空裔，我不允許你拒絕！",
  ui_story_5028_50281401_146_dialog_content = "好好好......唉，說了多少次了，我明明不是神奇動物。",
  ui_story_5028_50281401_147_dialog_content = "現在想要否認？很可惜，已經晚了。",
  ui_story_5028_50281401_148_dialog_content = "作為你的主人，本神奇動物專家可不允許你隨便逃走。",
  ui_story_5028_50281401_149_dialog_content = "明明是妳自說自話地非要乘上臨空者號的吧！",
  ui_story_5028_50281401_150_dialog_content = "而且那條蒼獅龍竟然也跟來了！",
  ui_story_5028_50281401_151_dialog_content = "快想想辦法讓牠回到該回的地方去啊！",
  ui_story_5028_50281401_152_dialog_content = "向臨空者號求偶是不會有結果的！",
  ui_story_5028_50281401_153_dialog_content = "我都說過啦，只要過了交配期，蒼獅龍大概就會回去。",
  ui_story_5028_50281401_154_dialog_content = "尊重神奇動物的習性和願望，是我這樣的神奇動物專家必須具備的品質。",
  ui_story_5028_50281401_155_dialog_content = "所以，我是不會強迫牠回去的！",
  ui_story_5028_50281401_156_dialog_content = "妳這個時候說得好聽......",
  ui_story_5028_50281401_157_dialog_content = "當初如果凱羅沒有回來，妳不知道要哭多少個小時呢！",
  ui_story_5028_50281401_158_dialog_content = "什，什麼？",
  ui_story_5028_50281401_159_dialog_content = "我怎麼不記得了！",
  ui_story_5028_50281401_160_dialog_content = "狡辯是沒用的，快點承認吧！",
  ui_story_5028_50281401_161_dialog_content = "你你你！",
  ui_story_5028_50281401_162_dialog_content = "凱羅，咬他！",
  ui_story_5028_50281401_163_dialog_content = "囉——嗷嗚！",
  ui_story_5028_50281401_164_dialog_content = "嗷！！！",
  ui_story_5028_50281401_165_dialog_content = "我的腿！！！",
  ui_story_5028_50281401_166_dialog_content = "噗！",
  ui_story_5028_50281401_167_dialog_content = "教育小孩子要用委婉一些的方法喔，PlayerName。",
  ui_story_5028_50281401_168_dialog_content = "薇絲，快救救我！",
  ui_story_5028_50281401_169_dialog_content = "快幫我把凱羅弄走！",
  ui_story_5028_50281401_170_dialog_content = "好啦好啦。你們就放過PlayerName吧。",
  ui_story_5028_50281401_171_dialog_content = "囉——！",
  ui_story_5028_50281401_172_dialog_content = "哼哼，知道本神奇動物專家的厲害了吧？",
  ui_story_5028_50281401_173_dialog_content = "我的腿......上面已經都是凱羅的牙印了！",
  ui_story_5028_50281401_174_dialog_content = "不過，明明那時候凱羅已經離開了，為什麼牠現在還會跟在菲雅小姐身邊呢？",
  ui_story_5028_50281401_175_dialog_content = "因為本神奇動物專家魅力無窮，凱羅也不願意離開我。",
  ui_story_5028_50281401_176_dialog_content = "囉囉囉——囉！",
  ui_story_5028_50281401_177_dialog_content = "咦？凱羅是不是說了什麼？",
  ui_story_5028_50281401_178_dialog_content = "有嗎？菲雅剛才沒聽清，凱羅，你剛才說了什麼？再說一遍？",
  ui_story_5028_50281401_179_dialog_content = "囉囉囉......",
  ui_story_5028_50281401_180_dialog_content = "「還不是因為菲雅太讓人擔心了......？」",
  ui_story_5028_50281401_181_dialog_content = "「一想到菲雅可能會哭很久......」",
  ui_story_5028_50281401_182_dialog_content = "「我就擔心的不行，所以最後就回......」",
  ui_story_5028_50281401_183_dialog_content = "竟然是這樣嗎？！",
  ui_story_5028_50281401_184_dialog_content = "囉囉囉！囉囉！",
  ui_story_5028_50281401_185_dialog_content = "嗚啊啊——！凱羅！！！",
  ui_story_5028_50281401_186_dialog_content = "不要再說了！！！",
  ui_story_5028_50281401_187_dialog_content = "故事在這裡告一段落。",
  ui_story_5028_50281401_188_dialog_content = "但是，神奇動物專家的冒險，永不結束。"
}
return config
